insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('aux-canarias:5-15e69f9725','aux-canarias',5,'¿Por qué mayoría se elige al Comisionado de Transparencia y Acceso a la Información Pública de Canarias?','["Mayoría absoluta del Parlamento", "Tres quintas partes del Parlamento", "Mayoría simple del Parlamento", "Por el Gobierno, oído el Parlamento"]'::jsonb,1,'Art. 60.3 EACan','El Comisionado de Transparencia es elegido por mayoría de tres quintas partes del Parlamento.',null),
('aux-canarias:5-0a9ac4155c','aux-canarias',5,'¿Cuál de estas funciones corresponde al Parlamento de Canarias?','["Aprobar los reglamentos ejecutivos de las leyes aprobadas por el Parlamento de Canarias", "Ejercer el derecho de gracia respecto de los condenados por tribunales canarios", "Nombrar al Presidente del Tribunal Superior de Justicia", "Designar a los senadores representantes de la Comunidad Autónoma"]'::jsonb,3,'Art. 43 d) EACan','Entre las funciones del Parlamento está designar, para cada legislatura, a los senadores representantes de la Comunidad Autónoma.',null),
('aux-canarias:5-7f7cfacb8e','aux-canarias',5,'¿Quién compone el Gobierno de Canarias?','["La Presidencia, la Vicepresidencia y los consejeros", "La Presidencia y los presidentes de los cabildos", "La Presidencia, los consejeros y los viceconsejeros", "La Presidencia, la Vicepresidencia, los consejeros y los presidentes de los cabildos"]'::jsonb,0,'Art. 51.1 EACan','El Gobierno está compuesto por las personas titulares de la Presidencia y de la Vicepresidencia y por los consejeros o consejeras.',null),
('aux-canarias:6-e8ed456c73','aux-canarias',6,'¿Qué norma regula actualmente la Presidencia y el Gobierno de Canarias?','["La Ley 1/1983, de 14 de abril", "La Ley 4/2023, de 23 de marzo", "El Decreto 212/1991, de 11 de septiembre", "La Ley 14/1990, de 26 de julio"]'::jsonb,1,'Art. 1 Ley 4/2023 Canarias','La Ley 4/2023, de 23 de marzo, de la Presidencia y del Gobierno de Canarias, derogó la Ley 1/1983 con efectos desde el 4 de abril de 2023.',null),
('aux-canarias:6-bdd3629a3d','aux-canarias',6,'¿Qué requisito exige la Ley 4/2023 para ser presidente o presidenta de Canarias?','["Ser diputado o diputada del Parlamento de Canarias", "Haber nacido en Canarias y residir en el archipiélago al menos cinco años", "Haber sido miembro del Gobierno en una legislatura anterior", "Tener al menos cinco años de vecindad en Canarias"]'::jsonb,0,'Art. 3 Ley 4/2023 Canarias','Para ser presidente o presidenta de Canarias se requiere tener la condición de diputado o diputada del Parlamento de Canarias.',null),
('aux-canarias:6-2a38e1a84c','aux-canarias',6,'¿Qué es el Gobierno de Canarias según la Ley 4/2023?','["El órgano supremo consultivo de la comunidad autónoma", "El órgano de coordinación de los cabildos insulares y de los ayuntamientos del archipiélago con el Estado", "El órgano superior colegiado de dirección política de la comunidad autónoma y de su administración", "El órgano unipersonal que ostenta la más alta representación de la comunidad autónoma y la ordinaria del Estado"]'::jsonb,2,'Art. 20 Ley 4/2023 Canarias','El Gobierno es el órgano superior colegiado de dirección política de la comunidad y de su administración.',null),
('aux-canarias:6-29a9ecdf4e','aux-canarias',6,'¿Dónde tiene su sede el Gobierno de Canarias?','["En la capital donde resida la Presidencia en cada legislatura", "En Santa Cruz de Tenerife", "En Las Palmas de Gran Canaria", "Compartida entre las dos capitales de Canarias"]'::jsonb,3,'Art. 22 Ley 4/2023 Canarias','La sede del Gobierno y de sus comisiones delegadas es compartida entre las dos capitales, aunque puede reunirse en cualquier localidad.',null),
('aux-canarias:6-8920433371','aux-canarias',6,'¿Cómo funciona el Gobierno de Canarias según la Ley 4/2023?','["En Consejo de Gobierno y en la Conferencia de Consejeros y Viceconsejeros", "En Consejo de Gobierno y en comisiones delegadas del Gobierno", "Exclusivamente en Consejo de Gobierno", "En Pleno y en Comisión Permanente, presidida por el vicepresidente del Gobierno"]'::jsonb,1,'Art. 23 Ley 4/2023 Canarias','El Gobierno de Canarias funciona en Consejo de Gobierno y en comisiones delegadas del Gobierno.',null),
('aux-canarias:6-d1a2547d25','aux-canarias',6,'¿Qué límite establece la Ley 4/2023 para garantizar la presencia equilibrada de mujeres y hombres en el Gobierno de Canarias?','["Ningún sexo puede superar el 60 % ni bajar del 40 %", "Ningún sexo puede superar el 55 % ni bajar del 45 %", "Al menos un tercio de los consejeros deben ser mujeres", "Debe haber igual número de consejeras y consejeros"]'::jsonb,0,'Art. 24.2 Ley 4/2023 Canarias','El número de personas de cada sexo no puede superar el 60 % ni ser inferior al 40 % del total del órgano.',null),
('aux-canarias:6-1c4608fc62','aux-canarias',6,'¿Quién ejerce la Secretaría del Gobierno de Canarias?','["El consejero o consejera de menor edad del Gobierno", "El vicepresidente o vicepresidenta del Gobierno", "El consejero o consejera que designe el presidente o presidenta", "Un funcionario de carrera del subgrupo A1 nombrado por el Consejo"]'::jsonb,2,'Art. 25.1 Ley 4/2023 Canarias','La Secretaría del Gobierno la ejerce el consejero o consejera que designe el presidente; en su defecto la suple el de menor edad.',null),
('aux-canarias:6-a07d91e128','aux-canarias',6,'¿Qué quórum exige la Ley 4/2023 para la válida constitución del Consejo de Gobierno de Canarias?','["Todos sus miembros", "La mayoría de sus miembros, entre ellos el presidente o quien le supla", "Dos tercios de sus miembros, con presencia del vicepresidente", "La mitad de sus miembros, sin necesidad de la presencia del presidente"]'::jsonb,1,'Art. 34 Ley 4/2023 Canarias','Es necesaria la asistencia de la mayoría de sus miembros, entre los que estará el presidente o presidenta o quien le supla.',null),
('aux-canarias:6-3299ce6b5f','aux-canarias',6,'¿Cómo se adoptan las decisiones del Consejo de Gobierno de Canarias?','["Como expresión unitaria de su voluntad, sin votación formal", "Por unanimidad de los presentes, que se hace constar expresamente en el acta", "Por mayoría absoluta de sus miembros", "Por mayoría simple de los presentes, con voto dirimente del presidente"]'::jsonb,0,'Art. 37.1 Ley 4/2023 Canarias','Las decisiones constituyen la expresión unitaria de la voluntad del Consejo, obligan a todos sus miembros y no están sujetas a votación formal.',null),
('aux-canarias:6-80e6c492aa','aux-canarias',6,'¿Qué forma revisten las decisiones del Consejo de Gobierno de Canarias que aprueban disposiciones generales?','["La de orden", "La de acuerdo", "La de resolución", "La de decreto"]'::jsonb,3,'Art. 37.2 Ley 4/2023 Canarias','Revisten la forma de decreto cuando aprueban disposiciones generales; en otro caso, la de acuerdo.',null),
('aux-canarias:6-cabb718b7a','aux-canarias',6,'¿Qué carácter tienen las deliberaciones del Consejo de Gobierno de Canarias?','["Secreto únicamente en materia presupuestaria", "Reservado solo hasta el final de la legislatura", "Público, salvo acuerdo en contrario", "Reservado y secreto, también después del cese de sus miembros"]'::jsonb,3,'Art. 36.1 Ley 4/2023 Canarias','Las deliberaciones son reservadas y secretas y sus miembros deben mantener ese carácter aun después de cesar.',null),
('aux-canarias:6-f20cd2ba37','aux-canarias',6,'¿Quién firma las actas del Consejo de Gobierno de Canarias?','["El presidente o presidenta", "Todos los consejeros asistentes", "Quien desempeñe la Secretaría del Gobierno", "El vicepresidente o vicepresidenta"]'::jsonb,2,'Art. 38.2 Ley 4/2023 Canarias','Las actas son firmadas por quien desempeñe la Secretaría del Gobierno.',null),
('aux-canarias:6-b7d361d119','aux-canarias',6,'¿Puede reunirse el Consejo de Gobierno de Canarias sin convocatoria previa ni orden del día?','["Sí, si lo solicita al menos la mitad de los consejeros con un día de antelación", "Sí, si lo decide el presidente y están presentes todos sus integrantes", "No, en ningún caso, porque la convocatoria y el orden del día son siempre obligatorios", "Solo en periodo de Gobierno en funciones"]'::jsonb,1,'Art. 33.4 Ley 4/2023 Canarias','Puede reunirse sin convocatoria ni orden del día cuando lo decida el presidente y se hallen presentes todos los integrantes.',null),
('aux-canarias:6-d4aa5c5f64','aux-canarias',6,'¿A quién corresponde determinar el número, la denominación y las competencias de las consejerías del Gobierno de Canarias?','["Al presidente o presidenta", "Al Consejo de Gobierno a propuesta de la Vicepresidencia", "A la Comisión Preparatoria de Asuntos del Gobierno", "Al Parlamento de Canarias mediante ley"]'::jsonb,0,'Art. 13 i) Ley 4/2023 Canarias','Corresponde al presidente determinar el número, denominación, competencias y orden de precedencia de las consejerías.',null),
('aux-canarias:6-a9b9ede6c9','aux-canarias',6,'¿Quién resuelve los conflictos de atribuciones entre las consejerías del Gobierno de Canarias?','["La Secretaría del Gobierno", "El Consejo Consultivo de Canarias", "El presidente o presidenta", "El vicepresidente o vicepresidenta"]'::jsonb,2,'Art. 13 r) Ley 4/2023 Canarias','Corresponde al presidente coordinar la actividad de las consejerías y resolver los conflictos de atribuciones entre ellas.',null),
('aux-canarias:6-aed1d27c7f','aux-canarias',6,'¿Cómo se nombra y cesa a los consejeros y consejeras del Gobierno de Canarias?','["Por real decreto", "Por resolución del Parlamento a propuesta del presidente", "Por acuerdo del Consejo de Gobierno", "Por decreto del presidente o presidenta"]'::jsonb,3,'Art. 56.1 Ley 4/2023 Canarias','El nombramiento y cese de los consejeros se realiza por el presidente o presidenta mediante decreto.',null),
('aux-canarias:6-ddb5c958fc','aux-canarias',6,'¿En qué plazo deben tomar posesión los consejeros tras la publicación de su nombramiento en el BOC?','["Dentro de los cinco días naturales siguientes", "Dentro de los diez días hábiles siguientes", "En el mismo día de la publicación del decreto de nombramiento en el BOC", "Dentro de los quince días naturales siguientes"]'::jsonb,0,'Art. 56.2 Ley 4/2023 Canarias','La toma de posesión debe producirse dentro de los cinco días naturales siguientes a la publicación del nombramiento.',null),
('aux-canarias:6-b7b34b30db','aux-canarias',6,'¿Qué condición se exige para ser consejero o consejera del Gobierno de Canarias?','["Ser diputado del Parlamento de Canarias", "Tener la condición política de canario", "Haber residido diez años en Canarias", "Ser funcionario de carrera"]'::jsonb,1,'Art. 55.2 Ley 4/2023 Canarias','Se requiere tener la condición política de canario, los derechos de sufragio y no estar inhabilitado ni sancionado para ser cargo público.',null),
('aux-canarias:6-b10454e471','aux-canarias',6,'¿Qué forma adoptan las disposiciones generales de los consejeros y consejeras de Canarias?','["Orden", "Resolución", "Instrucción", "Decreto"]'::jsonb,0,'Art. 77.1 d) Ley 4/2023 Canarias','Las disposiciones generales del vicepresidente y de los consejeros adoptan la forma de orden; si afectan a varios departamentos, orden conjunta.',null),
('aux-canarias:6-4e9fceb7da','aux-canarias',6,'¿Qué forma revisten las disposiciones generales acordadas por las comisiones delegadas del Gobierno de Canarias?','["Acuerdos de Comisión", "Órdenes conjuntas", "Decretos de Comisión Delegada", "Resoluciones"]'::jsonb,2,'Art. 77.1 b) Ley 4/2023 Canarias','Las disposiciones generales acordadas por las comisiones delegadas adoptan la forma de decretos de Comisión Delegada.',null),
('aux-canarias:6-cff84f7116','aux-canarias',6,'¿Qué exige la entrada en vigor de las disposiciones reglamentarias del Gobierno de Canarias?','["Su publicación en extracto en el BOC", "Su íntegra publicación en el Boletín Oficial de Canarias", "Su comunicación al Parlamento de Canarias", "Su publicación en el BOE"]'::jsonb,1,'Art. 79 Ley 4/2023 Canarias','La entrada en vigor de las disposiciones reglamentarias exige su íntegra publicación en el BOC.',null),
('aux-canarias:6-468ece5fff','aux-canarias',6,'¿Dónde se ubica la sede de la Vicepresidencia del Gobierno de Canarias?','["En la misma capital que la Presidencia", "En la capital que elija el vicepresidente", "En Santa Cruz de Tenerife", "En capital distinta a la de la Presidencia"]'::jsonb,3,'Art. 51 Ley 4/2023 Canarias','La sede de la Vicepresidencia se ubica en capital distinta a la de la Presidencia.',null),
('aux-canarias:6-163f8e5a55','aux-canarias',6,'¿Puede el vicepresidente o vicepresidenta de Canarias ser titular de una consejería?','["Solo con autorización del Parlamento", "Solo de la consejería de Presidencia", "Sí, cuando así lo disponga el presidente o presidenta", "No, es incompatible con la titularidad de una consejería"]'::jsonb,2,'Art. 49.1 Ley 4/2023 Canarias','El vicepresidente es miembro del Gobierno y puede ostentar la titularidad de una consejería cuando así lo disponga el presidente.',null),
('aux-canarias:6-d006d39b3f','aux-canarias',6,'¿Quién sustituye al presidente o presidenta de Canarias en caso de fallecimiento?','["El consejero o consejera de mayor edad", "El consejero que designe el Consejo de Gobierno", "El presidente o presidenta del Parlamento de Canarias, de forma interina hasta la nueva investidura", "El vicepresidente o vicepresidenta y, en su defecto, el consejero que corresponda por orden de precedencia"]'::jsonb,3,'Art. 16.1 Ley 4/2023 Canarias','Le sustituye el vicepresidente y, en su defecto, el consejero que corresponda según el orden de precedencia.',null),
('aux-canarias:6-47c18e4347','aux-canarias',6,'¿Qué mayoría parlamentaria debe reconocer la notoria incapacidad permanente del presidente o presidenta de Canarias como causa de cese?','["Mayoría de tres quintos", "Mayoría absoluta", "Mayoría simple", "Mayoría de dos tercios"]'::jsonb,1,'Art. 15.2 Ley 4/2023 Canarias','La notoria incapacidad debe ser reconocida por el Parlamento de Canarias por mayoría absoluta.',null),
('aux-canarias:6-e56819812f','aux-canarias',6,'¿Cuántas comisiones delegadas puede constituir el Gobierno de Canarias y con qué carácter?','["Las que decida, de carácter permanente o temporal", "Solo una, de carácter permanente", "Las que autorice el Parlamento", "Hasta tres, siempre temporales"]'::jsonb,0,'Art. 40 Ley 4/2023 Canarias','El Gobierno puede constituir comisiones delegadas, de carácter permanente o temporal, para las funciones que se les atribuyan o deleguen.',null),
('aux-canarias:6-92276f88a8','aux-canarias',6,'¿Quién puede crear la Portavocía del Gobierno de Canarias?','["El Parlamento de Canarias", "El Consejo de Gobierno", "El presidente o presidenta", "La Secretaría del Gobierno"]'::jsonb,2,'Art. 46.1 Ley 4/2023 Canarias','El presidente o presidenta podrá crear la Portavocía del Gobierno, cuyo titular asiste a las reuniones con obligación de secreto.',null),
('aux-canarias:7-7b5d0a60eb','aux-canarias',7,'¿Cuáles son los órganos necesarios de los cabildos insulares según el Estatuto de Canarias?','["El pleno, la presidencia, la junta de portavoces y la comisión de reglamento", "El pleno, la presidencia, el consejo de gobierno y la comisión especial de cuentas", "El pleno, la presidencia, las vicepresidencias y el consejo de gobierno", "La presidencia, el consejo de gobierno y la comisión de cuentas"]'::jsonb,2,'Art. 67.2 EACan','Son órganos necesarios de los cabildos el pleno, la presidencia, las vicepresidencias y el consejo de gobierno.',null),
('aux-canarias:7-32b2de7c8e','aux-canarias',7,'¿Qué mayoría exige el Estatuto para la ley que regula la organización de los cabildos insulares?','["Mayoría simple", "Mayoría absoluta", "Dos tercios", "Tres quintos"]'::jsonb,1,'Art. 67.1 EACan','Una ley del Parlamento aprobada por mayoría absoluta regula la organización de los cabildos insulares.',null),
('aux-canarias:7-9af362f100','aux-canarias',7,'¿Cuál es la duración del mandato de los miembros de los plenos de los cabildos insulares?','["Seis años", "Cuatro años", "Tres años", "Cinco años"]'::jsonb,1,'Art. 68.2 EACan','La duración del mandato de los plenos de los cabildos es de cuatro años.',null),
('aux-canarias:7-175f13908a','aux-canarias',7,'¿Dónde está fijada la capital de la isla de Fuerteventura?','["En Antigua", "En Valverde", "En Puerto del Rosario", "En Arrecife"]'::jsonb,2,'Art. 66 EACan','La capital de cada isla está en la sede del cabildo: Fuerteventura en Puerto del Rosario, Lanzarote en Arrecife y El Hierro en Valverde.',null),
('aux-canarias:7-ae3d6d483a','aux-canarias',7,'¿A qué isla está agregada administrativamente La Graciosa?','["A Fuerteventura", "A Gran Canaria", "A Tenerife", "A Lanzarote"]'::jsonb,3,'Art. 65.1 EACan','La Graciosa está agregada administrativamente a Lanzarote, igual que Alegranza, Montaña Clara y los Roques; Lobos, a Fuerteventura.',null),
('aux-canarias:7-b3ca3c55b2','aux-canarias',7,'¿Qué es la Conferencia de Presidentes según el Estatuto de Canarias?','["Un foro de colaboración del Gobierno de Canarias y los cabildos insulares", "Una comisión del Parlamento con los presidentes de los grupos", "El órgano consultivo del Parlamento integrado por los presidentes de los cabildos y los alcaldes de las capitales", "El órgano de coordinación de los alcaldes canarios con la Federación Canaria de Municipios"]'::jsonb,0,'Art. 74.1 EACan','Es un foro institucional de colaboración del Gobierno de Canarias y los cabildos, integrado por los presidentes de Canarias y de las islas.',null),
('aux-canarias:7-0667e8a315','aux-canarias',7,'¿Qué órgano canaliza el parecer de los ayuntamientos en las iniciativas legislativas que afectan a su organización y competencias?','["La Federación Canaria de Municipios", "La Comisión Bilateral de Cooperación", "La Comisión General de Cabildos Insulares", "El Consejo Municipal de Canarias"]'::jsonb,3,'Art. 76 EACan','El Consejo Municipal de Canarias es el órgano de participación y colaboración de la Administración autonómica y los ayuntamientos.',null),
('aux-canarias:7-f5d66eabee','aux-canarias',7,'¿Quién coordina la actividad de los cabildos insulares cuando afecte directamente al interés general de Canarias?','["La Conferencia de Presidentes", "El Gobierno de Canarias", "El Parlamento de Canarias", "La Diputación del Común"]'::jsonb,1,'Art. 73 EACan','El Gobierno de Canarias coordina la actividad de los cabildos en cuanto afecte directamente al interés general de la Comunidad.',null),
('aux-canarias:7-e28c4c566c','aux-canarias',7,'¿Cuál de estos principios debe tenerse en cuenta al atribuir competencias a islas y municipios según el Estatuto?','["No duplicidad de competencias", "Jerarquía insular", "Uniformidad territorial", "Igualdad de servicios en todas las islas"]'::jsonb,0,'Art. 64.2 f) EACan','Los principios son garantía de autonomía local, equidad, eficacia, eficiencia, máxima proximidad, no duplicidad y estabilidad presupuestaria.',null),
('aux-canarias:7-5a3612f892','aux-canarias',7,'¿Qué carácter tienen los municipios según el Estatuto de Canarias?','["Órganos periféricos de la Comunidad Autónoma", "Agrupaciones de islas sin autonomía propia", "Entidades locales básicas con personalidad jurídica propia", "Entidades instrumentales de los cabildos"]'::jsonb,2,'Art. 75.1 EACan','Los municipios son las entidades locales básicas de Canarias, con personalidad jurídica propia y autonomía plena.',null),
('aux-canarias:7-d2d0de728e','aux-canarias',7,'¿Cuál de estas materias es una competencia ejecutiva insular de los cabildos según el Estatuto?','["Turismo", "Administración de Justicia", "Universidades", "Policía autonómica"]'::jsonb,0,'Art. 70.2 f) EACan','Entre las funciones ejecutivas insulares figuran el turismo, la ordenación del territorio, las carreteras o la asistencia social.',null),
('aux-canarias:7-363ecc0856','aux-canarias',7,'Según la Ley 8/2015 de Cabildos Insulares, ¿qué son los cabildos insulares?','["Entidades locales de segundo grado formadas por la agrupación obligatoria de los municipios de cada isla", "Mancomunidades obligatorias de los municipios de cada isla", "Órganos periféricos de la Administración autonómica en cada isla", "Instituciones de la Comunidad Autónoma y órganos de gobierno, administración y representación de cada isla"]'::jsonb,3,'Art. 2 Ley 8/2015 Canarias','Los cabildos son instituciones de la Comunidad Autónoma y órganos de gobierno, administración y representación de cada una de las siete islas.',null),
('aux-canarias:7-faa0347410','aux-canarias',7,'¿Pueden los cabildos insulares mancomunarse para la prestación conjunta de servicios propios o transferidos?','["No, y los actos que lo contravengan son nulos de pleno derecho", "Sí, si pertenecen a la misma provincia", "Solo para servicios de transporte interinsular", "Sí, con autorización del Gobierno de Canarias"]'::jsonb,0,'Art. 3 Ley 8/2015 Canarias','Los cabildos no pueden mancomunarse o federarse para la prestación conjunta de servicios; los actos contrarios son nulos de pleno derecho.',null),
('aux-canarias:7-5f0fd86eca','aux-canarias',7,'¿Qué plazo de audiencia a los cabildos establece la Ley 8/2015 cuando un anteproyecto de ley afecta a las materias que regula?','["Diez días", "Quince días", "Un mes", "Veinte días hábiles"]'::jsonb,1,'Art. 4 Ley 8/2015 Canarias','El Gobierno dará audiencia a los cabildos por un plazo de quince días antes de aprobar el anteproyecto o proyecto.',null),
('aux-canarias:7-07f938de0c','aux-canarias',7,'¿Qué servicios deben garantizar los cabildos en los municipios de menos de 1.000 habitantes?','["Los de abastecimiento de agua", "Los de recogida de residuos", "Los de policía local", "Los de secretaría e intervención"]'::jsonb,3,'Art. 8.1 b) Ley 8/2015 Canarias','En todo caso, el cabildo garantizará en los municipios de menos de 1.000 habitantes la prestación de los servicios de secretaría e intervención.',null),
('aux-canarias:7-6bef3e6544','aux-canarias',7,'¿En qué municipios asume el cabildo la prestación de prevención y extinción de incendios cuando estos no la presten?','["En los de menos de 20.000 habitantes", "En los de menos de 5.000 habitantes", "En todos los de la isla", "En los de menos de 50.000 habitantes"]'::jsonb,0,'Art. 8.1 c) Ley 8/2015 Canarias','Asume el tratamiento de residuos en municipios de menos de 5.000 habitantes y la prevención y extinción de incendios en los de menos de 20.000.',null),
('aux-canarias:7-432e3eea4d','aux-canarias',7,'¿En qué municipios asume el cabildo el tratamiento de residuos cuando estos no lo presten?','["En los de menos de 1.000 habitantes", "En los de menos de 20.000 habitantes", "En los de menos de 5.000 habitantes", "En los de menos de 10.000 habitantes"]'::jsonb,2,'Art. 8.1 c) Ley 8/2015 Canarias','El cabildo asume la prestación del tratamiento de residuos en los municipios de menos de 5.000 habitantes cuando no la presten.',null),
('aux-canarias:7-745f688540','aux-canarias',7,'¿Cómo es, con carácter general, la asistencia de los cabildos a los municipios según la Ley 8/2015?','["Obligatoria en todos los casos, aunque el ayuntamiento no lo haya solicitado", "Voluntaria, previa solicitud del ayuntamiento", "Obligatoria para los municipios de menos de 20.000 habitantes", "Decidida de oficio por el pleno del cabildo"]'::jsonb,1,'Art. 10.4 Ley 8/2015 Canarias','La asistencia es voluntaria, previa solicitud del ayuntamiento, salvo cuando sea legalmente obligatoria.',null),
('aux-canarias:7-22a19d931f','aux-canarias',7,'¿A qué municipios prestan asistencia los cabildos especialmente, según la Ley 8/2015?','["A los de menos de 1.000 habitantes exclusivamente", "A los capitalinos", "A los de más de 50.000 habitantes", "A los de menos de 20.000 habitantes"]'::jsonb,3,'Art. 10.1 Ley 8/2015 Canarias','Prestan asistencia especialmente a los municipios de menos de 20.000 habitantes y a los de insuficiente capacidad económica y de gestión.',null),
('aux-canarias:7-0c49cee0d7','aux-canarias',7,'¿Qué principio debe atenderse, entre otros, en la atribución de competencias propias a los cabildos?','["Suficiencia financiera", "Subordinación al Gobierno", "Uniformidad insular", "Jerarquía administrativa"]'::jsonb,0,'Art. 7.2 g) Ley 8/2015 Canarias','Los principios son garantía de la autonomía insular, eficacia, eficiencia, máxima proximidad, no duplicidad, estabilidad presupuestaria y suficiencia financiera.',null),
('aux-canarias:7-46ff6c7030','aux-canarias',7,'¿En qué municipios presta el cabildo los servicios de administración electrónica y contratación centralizada?','["En los de población inferior a 5.000 habitantes", "En los de población superior a 20.000 habitantes", "En los de población inferior a 20.000 habitantes", "En todos los municipios de la isla"]'::jsonb,2,'Art. 8.1 g) Ley 8/2015 Canarias','Es competencia propia del cabildo la prestación de esos servicios en los municipios con población inferior a 20.000 habitantes.',null),
('aux-canarias:7-36f2d0a745','aux-canarias',7,'¿Cómo ejercen los cabildos sus competencias propias según la Ley 8/2015?','["Previa autorización del Gobierno de Canarias", "Bajo su propia responsabilidad y sin sujeción a instrucciones", "Por delegación de los municipios de la isla, conforme a lo que acuerden sus plenos", "Bajo la dirección y las instrucciones del consejero competente por razón de la materia"]'::jsonb,1,'Art. 7.1 Ley 8/2015 Canarias','Las competencias propias se ejercen bajo su propia responsabilidad, en el marco de las leyes y sin sujeción a directrices o instrucciones.',null),
('aux-canarias:7-be7a287aec','aux-canarias',7,'¿Cuál de estas materias figura entre los ámbitos de competencia de los cabildos en la Ley 8/2015?','["Seguridad privada", "Universidades", "Aguas", "Sistema penitenciario"]'::jsonb,2,'Art. 6.2 t) Ley 8/2015 Canarias','Entre los ámbitos materiales figuran, entre otros, ordenación del territorio, carreteras, turismo, servicios sociales y aguas.',null),
('aux-canarias:7-029a7ca86f','aux-canarias',7,'¿Qué ley regula los municipios de Canarias?','["La Ley 4/2023, de 23 de marzo", "La Ley 7/2015, de 1 de abril", "La Ley 8/2015, de 1 de abril", "La Ley 14/1990, de 26 de julio"]'::jsonb,1,'Art. 1 Ley 7/2015 Canarias','La Ley 7/2015, de 1 de abril, de los municipios de Canarias regula los municipios y demás entidades del sector público municipal.',null),
('aux-canarias:7-142866d2a7','aux-canarias',7,'¿Qué entidad de gestión desconcentrada menciona expresamente la Ley de Municipios de Canarias?','["La de la isla de La Graciosa", "La de los islotes de Alegranza y Montaña Clara", "La de la isla de Lobos", "La del Parque Nacional del Teide"]'::jsonb,0,'Art. 2.1 d) Ley 7/2015 Canarias','La ley se aplica, entre otras entidades, a la entidad de gestión desconcentrada de la isla de La Graciosa.',null),
('aux-canarias:7-0ad3911bcd','aux-canarias',7,'¿Cuál de estos principios de atribución de competencias a los municipios recoge la Ley 7/2015?','["Tutela autonómica", "Subsidiariedad insular", "Uniformidad", "Máxima proximidad"]'::jsonb,3,'Art. 5.1 b) Ley 7/2015 Canarias','Los principios son garantía de la autonomía municipal, máxima proximidad, igualdad en el acceso a los servicios y suficiencia financiera y estabilidad presupuestaria.',null),
('aux-canarias:7-c84240048f','aux-canarias',7,'Según la Ley 7/2015, ¿qué competencias se atribuyen a los municipios en virtud de la garantía de la autonomía municipal?','["Las que no quieran asumir los cabildos", "Las que afecten preponderantemente al círculo de intereses vecinales", "Las que determine cada año la ley de presupuestos", "Solo las que sean exclusivamente municipales"]'::jsonb,1,'Art. 6.1 Ley 7/2015 Canarias','Se atribuye a los municipios toda competencia que afecte preponderantemente al círculo de intereses vecinales, aunque no sea exclusivamente municipal.',null),
('aux-canarias:7-58369ba912','aux-canarias',7,'¿Qué son las competencias propias de los municipios según la Ley 7/2015?','["Las que asumen por acuerdo del Pleno municipal adoptado por mayoría absoluta de sus miembros", "Las que les delegan los cabildos insulares mediante decreto de su presidente o presidenta", "Aquellas cuya titularidad les atribuyen las leyes del Estado y de la Comunidad Autónoma", "Las que figuran en sus ordenanzas fiscales"]'::jsonb,2,'Art. 10.1 Ley 7/2015 Canarias','Son competencias propias aquellas cuya titularidad atribuyen las leyes del Estado y de la Comunidad Autónoma de Canarias.',null),
('aux-canarias:7-6ba576cc77','aux-canarias',7,'En las competencias delegadas a los municipios, ¿quién conserva la titularidad?','["La administración delegante", "La Comunidad Autónoma en todo caso", "El cabildo insular", "El municipio delegado"]'::jsonb,0,'Art. 10.2 Ley 7/2015 Canarias','Son delegadas las competencias cuyo ejercicio se atribuye al municipio, conservando la titularidad la administración delegante.',null),
('aux-canarias:7-1a3f4c5d61','aux-canarias',7,'¿Qué llevan aparejado las nuevas competencias propias que impliquen cargas adicionales para los municipios canarios?','["Una subida automática de los tributos municipales", "Un plazo de carencia de dos años", "La autorización del Ministerio de Hacienda", "Los correspondientes traspasos de recursos y medios de la comunidad autónoma"]'::jsonb,3,'Art. 9 Ley 7/2015 Canarias','Por el principio de suficiencia financiera, llevarán aparejados los traspasos de recursos y medios de la comunidad autónoma.',null),
('aux-canarias:7-18095491c7','aux-canarias',7,'¿Cuál de estas materias figura entre las competencias que los municipios canarios asumen en todo caso según la Ley 7/2015?','["Igualdad de género", "Defensa", "Puertos de interés general", "Relaciones internacionales"]'::jsonb,0,'Art. 11 h) Ley 7/2015 Canarias','Los municipios asumen las competencias que les asignen las leyes sectoriales canarias en materias como igualdad de género, vivienda, urbanismo o turismo.',null),
('aux-canarias:7-da2de27a5b','aux-canarias',7,'Para prestar residuos o incendios en municipios que no los presten, ¿qué plazo debe conceder el cabildo para que manifiesten su voluntad de hacerlo?','["Quince días", "Dos meses", "Tres meses", "Un mes"]'::jsonb,1,'Art. 12.2 Ley 7/2015 Canarias','El cabildo debe conceder a los municipios un plazo de dos meses; si no se manifiestan, viene obligado a prestarlos.',null),
('aux-canarias:7-fe5518553d','aux-canarias',7,'¿Quién solicita la asistencia del cabildo en los municipios de más de 20.000 habitantes?','["El Pleno, por mayoría absoluta", "La Junta de Portavoces", "El alcalde, dando cuenta al Pleno", "El secretario municipal"]'::jsonb,2,'Art. 12.1 Ley 7/2015 Canarias','La asistencia la solicita el alcalde, dando cuenta al Pleno (o a la Junta de Gobierno local en los municipios de gran población).',null),
('aux-canarias:8-3558913fbc','aux-canarias',8,'Si los Presupuestos Generales de Canarias no se aprueban antes del primer día del ejercicio, ¿qué ocurre?','["Se aplica el proyecto presentado por el Gobierno", "Rige el presupuesto del Estado", "Se tramita un presupuesto provisional por decreto-ley", "Se prorrogan automáticamente los anteriores"]'::jsonb,3,'Art. 185.3 EACan','Si no se aprueban antes del primer día del ejercicio, los anteriores quedan automáticamente prorrogados.',null),
('aux-canarias:8-2aa2f1a25b','aux-canarias',8,'¿Qué período tienen los Presupuestos Generales de la Comunidad Autónoma de Canarias?','["Plurianual de cuatro años", "Anual, igual que los del Estado", "El de la legislatura", "Bienal"]'::jsonb,1,'Art. 185.2 EACan','Los Presupuestos tienen carácter anual e igual período que los del Estado.',null),
('aux-canarias:8-e030d517c9','aux-canarias',8,'¿A quién corresponde la aprobación y fiscalización de los Presupuestos Generales de Canarias?','["Al Tribunal de Cuentas", "A la Audiencia de Cuentas", "Al Parlamento de Canarias", "Al Gobierno de Canarias"]'::jsonb,2,'Art. 185.1 EACan','Corresponde al Parlamento de Canarias la aprobación y fiscalización de los Presupuestos Generales de la Comunidad.',null),
('aux-canarias:8-e5207540ed','aux-canarias',8,'¿Cómo define la Ley 11/2006 de la Hacienda Pública Canaria los Presupuestos Generales de la Comunidad Autónoma?','["El plan plurianual de inversiones aprobado por el Gobierno", "El documento que recoge la previsión de ingresos tributarios de la comunidad", "La relación de créditos ampliables de cada consejería", "La expresión cifrada, conjunta y sistemática de los derechos y obligaciones a liquidar durante el ejercicio"]'::jsonb,3,'Art. 35 Ley 11/2006 Canarias','Los Presupuestos son la expresión cifrada, conjunta y sistemática de los derechos y obligaciones a liquidar durante el ejercicio por los órganos y entidades del sector público.',null),
('aux-canarias:8-0ae8f7068b','aux-canarias',8,'¿Con qué período coincide el ejercicio presupuestario de la Comunidad Autónoma de Canarias?','["Con el periodo de sesiones del Parlamento", "Del 1 de julio al 30 de junio", "Con la legislatura", "Con el año natural"]'::jsonb,3,'Art. 37 Ley 11/2006 Canarias','El ejercicio presupuestario coincide con el año natural.',null),
('aux-canarias:8-d63c3117a8','aux-canarias',8,'¿Hasta qué fecha pueden reconocerse obligaciones imputables al ejercicio presupuestario anterior en Canarias?','["Hasta el quince de enero siguiente", "Hasta el treinta y uno de diciembre", "Hasta el treinta y uno de marzo siguiente", "Hasta el treinta y uno de enero siguiente"]'::jsonb,0,'Art. 37 b) Ley 11/2006 Canarias','Se imputan las obligaciones reconocidas hasta el quince de enero siguiente por gastos realizados antes de que expire el ejercicio.',null),
('aux-canarias:8-945edfe7ba','aux-canarias',8,'¿Antes de qué fecha debe remitirse al Parlamento el proyecto de Ley de Presupuestos Generales de Canarias?','["Antes del 30 de septiembre del año anterior", "Antes del 1 de noviembre del año anterior", "Antes del 15 de diciembre del año anterior", "Antes del 1 de octubre del año anterior"]'::jsonb,1,'Art. 39.1 Ley 11/2006 Canarias','El proyecto de ley se remite al Parlamento de Canarias antes del día 1 de noviembre del año anterior al que se refiera.',null),
('aux-canarias:8-ff6e4f4b15','aux-canarias',8,'¿Quién eleva al Gobierno de Canarias el anteproyecto de Ley de Presupuestos Generales?','["La Comisión de Presupuestos del Parlamento", "El presidente del Gobierno", "El consejero competente en materia de Hacienda", "La Intervención General"]'::jsonb,2,'Art. 38.4 Ley 11/2006 Canarias','Corresponde al consejero competente en materia de Hacienda elevar al Gobierno el anteproyecto de Ley de Presupuestos.',null),
('aux-canarias:8-ceb685ef4f','aux-canarias',8,'Si la Ley de Presupuestos de Canarias no se aprueba antes del primer día del ejercicio, ¿qué se prorroga?','["Solo los créditos de personal y los destinados a la amortización de la deuda", "Los presupuestos definitivos del ejercicio anterior, con todas sus modificaciones", "Los presupuestos iniciales del ejercicio anterior", "El proyecto de ley remitido al Parlamento"]'::jsonb,2,'Art. 40.1 Ley 11/2006 Canarias','Se consideran automáticamente prorrogados los presupuestos iniciales del ejercicio anterior y los créditos generados para nuevas competencias.',null),
('aux-canarias:8-780e23b848','aux-canarias',8,'¿Qué créditos no se prorrogan cuando no se aprueban a tiempo los Presupuestos de Canarias?','["Los de la sección de Deuda Pública", "Los de programas o actuaciones que terminen en el ejercicio prorrogado", "Los destinados a los cabildos insulares", "Los de personal"]'::jsonb,1,'Art. 40.2 Ley 11/2006 Canarias','La prórroga no afecta a los créditos de programas o actuaciones que terminen en el ejercicio prorrogado ni a obligaciones que se extingan en él.',null),
('aux-canarias:8-de335b4ba7','aux-canarias',8,'¿Qué clasificación de los estados de gastos agrupa los créditos por capítulos, separando operaciones corrientes, de capital y financieras?','["La clasificación económica", "La clasificación orgánica", "La clasificación territorial", "La clasificación por programas"]'::jsonb,0,'Art. 42.1 c) Ley 11/2006 Canarias','La clasificación económica agrupa los créditos por capítulos, separando operaciones corrientes, de capital y financieras.',null),
('aux-canarias:8-6abf30c5e1','aux-canarias',8,'¿Qué clasificación de los gastos agrupa los créditos por ámbito exterior, regional o insular?','["La clasificación orgánica", "La clasificación económica", "La clasificación funcional", "La clasificación territorial"]'::jsonb,3,'Art. 42.1 d) Ley 11/2006 Canarias','La clasificación territorial agrupa por ámbito exterior, regional o insular los créditos asignados a los centros gestores.',null),
('aux-canarias:8-7bf0e49346','aux-canarias',8,'¿Según qué clasificaciones se estructuran los estados de ingresos de los entes con presupuesto limitativo en Canarias?','["Orgánica, por programas y territorial", "Por programas y económica", "Económica y funcional", "Orgánica y económica"]'::jsonb,3,'Art. 43 Ley 11/2006 Canarias','Los estados de ingresos se estructuran siguiendo las clasificaciones orgánica y económica.',null),
('aux-canarias:8-1da081951c','aux-canarias',8,'¿Qué carácter tienen los créditos para gastos en la Ley de la Hacienda Pública Canaria?','["Ampliable en todo caso", "Limitativo", "Estimativo", "Orientativo"]'::jsonb,1,'Art. 48 Ley 11/2006 Canarias','Los créditos para gastos son limitativos: no pueden adquirirse compromisos por cuantía superior a los créditos autorizados.',null),
('aux-canarias:8-34bde77eaf','aux-canarias',8,'¿Qué consecuencia tienen los actos administrativos que adquieran compromisos de gasto superiores a los créditos autorizados?','["Son anulables", "Son válidos si se convalidan por el Gobierno", "Son nulos de pleno derecho", "Son irregularidades no invalidantes"]'::jsonb,2,'Art. 48 Ley 11/2006 Canarias','Son nulos de pleno derecho los actos y disposiciones de rango inferior a ley que incumplan la limitación de los créditos.',null),
('aux-canarias:8-53847205d4','aux-canarias',8,'¿A cuántos ejercicios pueden aplicarse como máximo los compromisos de gasto plurianuales en Canarias, con carácter general?','["Cuatro", "Tres", "Cinco", "Seis"]'::jsonb,0,'Art. 49.2 Ley 11/2006 Canarias','El número de ejercicios a que pueden aplicarse los gastos no será superior a cuatro.',null),
('aux-canarias:8-ced4b8ee78','aux-canarias',8,'¿Qué porcentaje del crédito inicial puede imputarse en el ejercicio inmediato siguiente en un gasto plurianual en Canarias?','["El 60 %", "El 80 %", "El 70 %", "El 50 %"]'::jsonb,2,'Art. 49.2 Ley 11/2006 Canarias','Los porcentajes son el 70 % en el ejercicio siguiente, el 60 % en el segundo y el 50 % en el tercero y cuarto.',null),
('aux-canarias:8-c49854bbbc','aux-canarias',8,'¿Qué retención adicional de crédito se practica en los contratos de obra plurianuales en Canarias?','["El 15 % del presupuesto de licitación", "El 10 % del presupuesto de licitación", "El 20 % del importe de adjudicación", "El 5 % del presupuesto de licitación"]'::jsonb,1,'Art. 49.2 Ley 11/2006 Canarias','Se efectúa una retención adicional del 10 % del presupuesto de licitación, que se ajusta al 10 % de la adjudicación una vez adjudicada la obra.',null),
('aux-canarias:8-2cf10d1ee2','aux-canarias',8,'¿Cuáles son las fases de la gestión del presupuesto de gastos en la Ley 11/2006, por orden?','["Aprobación, reconocimiento de la obligación, compromiso, ordenación del pago y pago material", "Autorización, disposición, liquidación y pago", "Compromiso, aprobación, ordenación del pago, reconocimiento de la obligación y pago material", "Aprobación, compromiso, reconocimiento de la obligación, ordenación del pago y pago material"]'::jsonb,3,'Art. 68.1 Ley 11/2006 Canarias','Las fases son aprobación del gasto, compromiso, reconocimiento de la obligación, ordenación del pago y pago material.',null),
('aux-canarias:8-49b0a0157b','aux-canarias',8,'¿Qué fase de la ejecución del gasto inicia el procedimiento sin implicar relaciones con terceros?','["La aprobación del gasto", "El compromiso de gasto", "El reconocimiento de la obligación", "La ordenación del pago"]'::jsonb,0,'Art. 68.2 Ley 11/2006 Canarias','La aprobación inicia el procedimiento de ejecución del gasto, sin que implique relaciones con terceras personas.',null),
('aux-canarias:8-c841e30370','aux-canarias',8,'¿Qué fase de la ejecución del gasto vincula a la Hacienda Pública frente a terceros a la realización del gasto?','["El compromiso de gasto", "La aprobación del gasto", "El pago material", "La ordenación del pago"]'::jsonb,0,'Art. 68.3 Ley 11/2006 Canarias','El compromiso es un acto con relevancia jurídica para con terceros que vincula a la Hacienda Pública a realizar el gasto.',null),
('aux-canarias:8-0a77370ffd','aux-canarias',8,'¿Qué son las generaciones de crédito según la Ley 11/2006?','["Créditos para gastos que no pueden demorarse al ejercicio siguiente", "Traspasos de dotaciones entre créditos", "Modificaciones que incrementan los créditos por ingresos no previstos o superiores a los previstos", "Remanentes del ejercicio anterior que se suman al actual"]'::jsonb,2,'Art. 55.1 Ley 11/2006 Canarias','Las generaciones incrementan los créditos como consecuencia de ingresos no previstos o superiores a los del presupuesto inicial.',null),
('aux-canarias:8-2f2a3f7c75','aux-canarias',8,'¿Qué son las transferencias de crédito según la Ley 11/2006?','["Créditos que se amplían hasta el importe de las obligaciones", "Traspasos de dotaciones entre créditos", "Incrementos de crédito por ingresos no previstos", "Aportaciones a los cabildos insulares"]'::jsonb,1,'Art. 54.1 Ley 11/2006 Canarias','Las transferencias son traspasos de dotaciones entre créditos, con las restricciones del art. 54.',null),
('aux-canarias:8-f2d077605e','aux-canarias',8,'¿Desde qué créditos no pueden realizarse transferencias a créditos para operaciones corrientes?','["Desde créditos de la sección Deuda Pública", "Desde créditos para gastos de funcionamiento", "Desde créditos de personal", "Desde créditos para operaciones de capital"]'::jsonb,3,'Art. 54.1 a) Ley 11/2006 Canarias','No pueden hacerse transferencias desde operaciones financieras al resto de créditos ni desde operaciones de capital a operaciones corrientes.',null),
('aux-canarias:8-f7ec5c9896','aux-canarias',8,'¿Cómo se tramita en Canarias un crédito extraordinario o suplemento de crédito de la Administración autonómica?','["Por orden del consejero de Hacienda publicada en el Boletín Oficial de Canarias", "Por resolución de la Intervención General", "Mediante proyecto de ley remitido al Parlamento", "Por decreto del Gobierno sin intervención parlamentaria"]'::jsonb,2,'Art. 57.2 Ley 11/2006 Canarias','El consejero de Hacienda propone al Gobierno la remisión de un proyecto de ley al Parlamento.',null),
('aux-canarias:8-4112ab575a','aux-canarias',8,'¿Cuál de estas es una modalidad de modificación de créditos prevista en la Ley 11/2006?','["Prórrogas", "Retenciones", "Anticipos de caja fija", "Incorporaciones"]'::jsonb,3,'Art. 53.1 Ley 11/2006 Canarias','Las modificaciones son transferencias, generaciones, ampliaciones, créditos extraordinarios y suplementos, e incorporaciones.',null),
('aux-canarias:8-268e8bab70','aux-canarias',8,'¿Cuándo aprueba el Gobierno de Canarias los escenarios presupuestarios plurianuales?','["En el primer cuatrimestre del año", "En el último trimestre del año", "En el mes de julio", "Al aprobar el proyecto de presupuestos"]'::jsonb,0,'Art. 26.1 Ley 11/2006 Canarias','El Gobierno aprueba en el primer cuatrimestre los escenarios presupuestarios referidos a los tres ejercicios siguientes.',null),
('aux-canarias:8-d9b738a389','aux-canarias',8,'¿A qué periodo se refieren los programas de actuación plurianual de los entes con presupuesto limitativo?','["A un único ejercicio, prorrogable una sola vez por igual periodo", "No inferior a dos años ni superior a tres", "A la legislatura completa", "No inferior a tres años ni superior a cinco"]'::jsonb,1,'Art. 28.1 Ley 11/2006 Canarias','Se refieren a un período no inferior a dos años ni superior a tres, salvo causa justificada.',null),
('aux-canarias:9-181aaec658','aux-canarias',9,'¿Cuántas instituciones enumera el artículo 13 del Tratado de la Unión Europea?','["Cinco", "Seis", "Nueve", "Siete"]'::jsonb,3,'Art. 13 TUE','Parlamento Europeo, Consejo Europeo, Consejo, Comisión, Tribunal de Justicia de la UE, Banco Central Europeo y Tribunal de Cuentas.',null),
('aux-canarias:9-acc0d5fedb','aux-canarias',9,'¿Cuál de los siguientes NO es una institución de la Unión según el artículo 13 del TUE?','["El Comité de las Regiones", "El Tribunal de Cuentas", "El Banco Central Europeo", "El Consejo Europeo"]'::jsonb,0,'Art. 13 TUE','El Comité de las Regiones y el Comité Económico y Social son órganos consultivos, no instituciones.',null),
('aux-canarias:9-adc557cc63','aux-canarias',9,'¿Por cuánto tiempo se elige a los miembros del Parlamento Europeo?','["Cinco años", "Cuatro años", "Dos años y medio", "Seis años"]'::jsonb,0,'Art. 14.3 TUE','Se eligen por sufragio universal directo, libre y secreto.',null),
('aux-canarias:9-883e69bbcf','aux-canarias',9,'El número de miembros del Parlamento Europeo no puede exceder de:','["700, incluido el Presidente", "750, más el Presidente", "751, más el Presidente", "800, más el Presidente"]'::jsonb,1,'Art. 14.2 TUE','Ningún Estado puede tener más de 96 escaños ni menos de 6.',null),
('aux-canarias:9-f5c49c7604','aux-canarias',9,'¿Dónde tiene su sede oficial el Parlamento Europeo?','["En Fráncfort", "En Luxemburgo", "En Bruselas", "En Estrasburgo"]'::jsonb,3,'Sedes de las instituciones','También trabaja en Bruselas y su Secretaría General está en Luxemburgo.',null),
('aux-canarias:9-86af4aa8d7','aux-canarias',9,'¿Quiénes componen el Consejo Europeo?','["Los Ministros de Asuntos Exteriores de los Estados miembros, el Alto Representante y el Presidente de la Comisión", "Un representante de cada Estado miembro de rango ministerial", "Los Presidentes de los Parlamentos nacionales de los Estados miembros y el Presidente del Parlamento Europeo", "Los Jefes de Estado o de Gobierno de los Estados miembros, su Presidente y el Presidente de la Comisión"]'::jsonb,3,'Art. 15.2 TUE','El Alto Representante participa en sus trabajos, pero no es miembro.',null),
('aux-canarias:9-9dca3f307a','aux-canarias',9,'El Presidente del Consejo Europeo es elegido por un mandato de:','["Seis meses, coincidiendo con la presidencia rotatoria", "Cinco años, no renovable", "Dos años, renovable indefinidamente", "Dos años y medio, renovable una sola vez"]'::jsonb,3,'Art. 15.5 TUE','Lo elige el propio Consejo Europeo por mayoría cualificada.',null),
('aux-canarias:9-192e078a02','aux-canarias',9,'El Consejo de la Unión Europea está compuesto por:','["Un representante de cada Estado miembro de rango ministerial", "Un comisario por cada Estado miembro, nombrado por su Gobierno nacional", "Los Jefes de Estado o de Gobierno de los Estados miembros y su Presidente", "Los embajadores de los Estados miembros ante la Unión, con rango de representantes permanentes"]'::jsonb,0,'Art. 16.2 TUE','Ese representante puede comprometer al Gobierno de su Estado y ejercer el derecho de voto.',null),
('aux-canarias:9-5373126ce3','aux-canarias',9,'Desde 2014, la mayoría cualificada en el Consejo se define como:','["Al menos dos tercios de los Estados miembros que representen como mínimo la mitad de la población de la Unión", "La mayoría absoluta de los Estados miembros, sea cual sea su población, siempre que incluya a los cuatro más poblados", "Al menos el 55 % de los miembros del Consejo que representen al menos el 65 % de la población de la Unión", "Al menos el 65 % de los miembros del Consejo que representen como mínimo el 55 % de la población de la Unión"]'::jsonb,2,'Art. 16.4 TUE','La minoría de bloqueo debe incluir al menos a cuatro miembros del Consejo.',null),
('aux-canarias:9-a492dbcdd1','aux-canarias',9,'¿Qué institución tiene, como regla general, la iniciativa legislativa en la Unión Europea?','["La Comisión Europea", "El Consejo Europeo", "El Consejo de la Unión", "El Parlamento Europeo"]'::jsonb,0,'Art. 17.2 TUE','Los actos legislativos solo pueden adoptarse a propuesta de la Comisión, salvo que los Tratados dispongan otra cosa.',null),
('aux-canarias:9-c49aedc5ee','aux-canarias',9,'¿Cómo se elige al Presidente de la Comisión Europea?','["Lo eligen los ciudadanos de la Unión por sufragio universal directo cada cinco años", "Lo nombra el Consejo de la Unión por mayoría simple, a propuesta del Parlamento Europeo", "El Consejo Europeo propone un candidato por mayoría cualificada y el Parlamento Europeo lo elige por mayoría de sus miembros", "Lo elige directamente el Consejo Europeo por unanimidad, sin intervención del Parlamento"]'::jsonb,2,'Art. 17.7 TUE','El Consejo Europeo tiene en cuenta el resultado de las elecciones al Parlamento Europeo.',null),
('aux-canarias:9-d38de659a5','aux-canarias',9,'¿Qué cargo ocupa el Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad dentro de la Comisión?','["Es su Secretario General, con voz pero sin voto", "Es uno de sus Vicepresidentes", "Es su Presidente, por razón de su cargo", "No forma parte de la Comisión, sino del Consejo Europeo"]'::jsonb,1,'Art. 18.4 TUE','Además preside el Consejo de Asuntos Exteriores.',null),
('aux-canarias:9-3850780d38','aux-canarias',9,'¿Dónde tiene su sede el Tribunal de Justicia de la Unión Europea?','["En Bruselas", "En Estrasburgo", "En Luxemburgo", "En La Haya"]'::jsonb,2,'Sedes de las instituciones','En La Haya está el Tribunal Internacional de Justicia y en Estrasburgo el Tribunal Europeo de Derechos Humanos, que no son órganos de la UE.',null),
('aux-canarias:9-c7b4a72317','aux-canarias',9,'¿Dónde tiene su sede el Banco Central Europeo?','["En Ámsterdam", "En Luxemburgo", "En Bruselas", "En Fráncfort"]'::jsonb,3,'Sedes de las instituciones','El BCE dirige la política monetaria de la zona euro.',null),
('aux-canarias:9-d1b1befa8f','aux-canarias',9,'Según el artículo 288 del TFUE, el reglamento:','["Obliga al Estado destinatario en cuanto al resultado, dejando a las autoridades nacionales la elección de la forma y los medios", "No es vinculante y solo expresa una opinión de las instituciones", "Tiene alcance general, es obligatorio en todos sus elementos y directamente aplicable en cada Estado miembro", "Solo es obligatorio para sus destinatarios, que deben estar designados en él"]'::jsonb,2,'Art. 288 TFUE','La segunda opción describe la directiva, la tercera la decisión y la cuarta los dictámenes.',null),
('aux-canarias:9-38d9608f7c','aux-canarias',9,'¿Qué acto de la Unión obliga al Estado miembro destinatario en cuanto al resultado que deba conseguirse, dejando a las autoridades nacionales la elección de la forma y de los medios?','["La recomendación", "La decisión", "El reglamento", "La directiva"]'::jsonb,3,'Art. 288 TFUE','Las directivas deben transponerse al derecho interno.',null),
('aux-canarias:9-d63068fa55','aux-canarias',9,'Según el artículo 288 del TFUE, las recomendaciones y los dictámenes:','["Son obligatorios en todos sus elementos", "Solo obligan a sus destinatarios", "Obligan solo en cuanto al resultado", "No son vinculantes"]'::jsonb,3,'Art. 288 TFUE','Son actos de las instituciones sin fuerza obligatoria.',null),
('aux-canarias:9-adc94d5d15','aux-canarias',9,'En el procedimiento legislativo ordinario, los actos se adoptan conjuntamente por:','["El Consejo Europeo y el Parlamento, a propuesta del Consejo", "La Comisión y el Consejo Europeo, oído el Parlamento", "El Parlamento Europeo y el Consejo, a propuesta de la Comisión", "El Consejo de la Unión por unanimidad, previa consulta al Parlamento"]'::jsonb,2,'Art. 294 TFUE','Antes del Tratado de Lisboa se llamaba procedimiento de codecisión.',null),
('aux-canarias:9-921e704e0a','aux-canarias',9,'¿Quién elige al Defensor del Pueblo Europeo?','["El Tribunal de Justicia", "El Consejo Europeo", "El Parlamento Europeo", "La Comisión Europea"]'::jsonb,2,'Art. 228 TFUE','Recibe reclamaciones sobre casos de mala administración en la acción de las instituciones, órganos y organismos de la Unión.',null),
('aux-canarias:9-621a22500a','aux-canarias',9,'¿Cuántos ciudadanos de la Unión, como mínimo, deben respaldar una iniciativa ciudadana europea?','["Quinientos mil, de al menos cinco Estados miembros distintos de la Unión", "Dos millones, procedentes como mínimo de la mitad de los Estados miembros", "Cien mil, sin importar su nacionalidad ni su Estado de residencia", "Un millón, de un número significativo de Estados miembros"]'::jsonb,3,'Art. 11.4 TUE','Con ella se invita a la Comisión a presentar una propuesta legislativa.',null),
('aux-canarias:9-91d3a410c4','aux-canarias',9,'¿Qué artículo del Tratado de la Unión Europea regula la retirada voluntaria de un Estado miembro?','["El artículo 7", "El artículo 49", "El artículo 50", "El artículo 48"]'::jsonb,2,'Art. 50 TUE','El artículo 49 regula la adhesión, el 7 la suspensión de derechos y el 48 la revisión de los Tratados.',null),
('aux-canarias:9-45e30cfd30','aux-canarias',9,'¿A qué institución corresponde el control de las cuentas de la Unión?','["Al Banco Central Europeo", "A la Oficina Europea de Lucha contra el Fraude", "Al Tribunal de Justicia de la Unión", "Al Tribunal de Cuentas Europeo"]'::jsonb,3,'Art. 285 TFUE','Tiene su sede en Luxemburgo y está formado por un nacional de cada Estado miembro.',null),
('aux-canarias:9-cbce805a50','aux-canarias',9,'¿Cuándo puede el Gobierno de Canarias formar parte de las delegaciones españolas ante la Unión Europea?','["Siempre que lo solicite el Parlamento de Canarias", "Solo en materia de pesca", "Solo cuando se negocien ayudas de Estado para Canarias", "Cuando se vea afectada su condición de región ultraperiférica"]'::jsonb,3,'Art. 196.3 EACan','El Gobierno de Canarias podrá formar parte de las delegaciones españolas cuando se vea afectada su condición de región ultraperiférica.',null),
('aux-canarias:9-ed3c6cb8c0','aux-canarias',9,'¿A quién corresponde la gestión de los fondos europeos en materias de competencia de Canarias?','["A los cabildos insulares", "Al Estado, a través de la Delegación del Gobierno", "A la Comunidad Autónoma de Canarias", "A la Administración General del Estado y a los cabildos de forma conjunta"]'::jsonb,2,'Art. 197.2 EACan','Corresponde a la Comunidad Autónoma de Canarias la gestión de los fondos europeos en materias de su competencia.',null),
('aux-canarias:10-abd6fa82d1','aux-canarias',10,'La Ley Orgánica 3/2007 tiene por objeto:','["Hacer efectivo el derecho de igualdad de trato y de oportunidades entre mujeres y hombres", "Establecer medidas de protección integral contra la violencia de género y de igualdad de oportunidades en el empleo", "Hacer efectivo el derecho de igualdad de trato entre mujeres y hombres, pero solo en el ámbito del empleo público y de la negociación colectiva", "Regular la igualdad de trato y la no discriminación por cualquier circunstancia personal"]'::jsonb,0,'Art. 1.1 LO 3/2007','Su objeto es hacer efectivo el derecho de igualdad de trato y de oportunidades entre mujeres y hombres.',null),
('aux-canarias:10-16efc76198','aux-canarias',10,'El principio de igualdad de trato entre mujeres y hombres supone:','["La igualdad en el ámbito laboral y en el acceso al empleo", "La ausencia de toda discriminación, directa o indirecta, por razón de sexo", "La ausencia de discriminación directa por razón de sexo, pero no de la indirecta, que se rige por la normativa laboral", "La paridad obligatoria en todos los órganos públicos y privados, con independencia de su composición"]'::jsonb,1,'Art. 3 LO 3/2007','Supone la ausencia de toda discriminación, directa o indirecta, por razón de sexo, especialmente por maternidad, obligaciones familiares y estado civil.',null),
('aux-canarias:10-8accd0afb2','aux-canarias',10,'Se considera discriminación directa por razón de sexo la situación en que una persona:','["Recibe una medida de acción positiva destinada a corregir situaciones de desigualdad", "Es tratada igual que otra persona en una situación distinta", "Es, ha sido o pudiera ser tratada, en atención a su sexo, de manera menos favorable que otra en situación comparable", "Sufre una desventaja particular respecto de personas del otro sexo por una disposición, criterio o práctica aparentemente neutros"]'::jsonb,2,'Art. 6.1 LO 3/2007','Es la situación de quien es, ha sido o pudiera ser tratada, en atención a su sexo, de manera menos favorable que otra en situación comparable. El trato por disposición aparentemente neutra es la discriminación indirecta.',null),
('aux-canarias:10-c7da8489aa','aux-canarias',10,'El acoso sexual es cualquier comportamiento, verbal o físico, de naturaleza sexual que:','["Se produzca fuera del lugar de trabajo", "Se repita al menos tres veces y lo denuncie la persona afectada o un tercero", "Produzca una lesión física acreditada", "Tenga el propósito o produzca el efecto de atentar contra la dignidad de una persona"]'::jsonb,3,'Art. 7.1 LO 3/2007','Tiene el propósito o produce el efecto de atentar contra la dignidad de una persona, en particular cuando crea un entorno intimidatorio, degradante u ofensivo.',null),
('aux-canarias:10-9aaa0a6127','aux-canarias',10,'Todo trato desfavorable a las mujeres relacionado con el embarazo o la maternidad constituye:','["Discriminación directa por razón de sexo", "Discriminación indirecta por razón de sexo, salvo que la empresa acredite una justificación objetiva", "Acoso por razón de sexo", "Una infracción laboral leve"]'::jsonb,0,'Art. 8 LO 3/2007','Constituye discriminación directa por razón de sexo.',null),
('aux-canarias:10-eb32ff35e3','aux-canarias',10,'Según la LO 3/2007, el principio de igualdad de trato y oportunidades informará la actuación de todos los Poderes Públicos con carácter:','["Excepcional", "Transversal", "Subsidiario", "Voluntario"]'::jsonb,1,'Art. 15 LO 3/2007','Informará, con carácter transversal, la actuación de todos los Poderes Públicos.',null),
('aux-canarias:10-a521c1b9da','aux-canarias',10,'¿Qué empresas deben elaborar y aplicar un plan de igualdad?','["Todas, cualquiera que sea su plantilla", "Las de más de 250 trabajadores", "Las de cincuenta o más trabajadores", "Solo las empresas públicas y las que contraten con la Administración, cualquiera que sea su plantilla"]'::jsonb,2,'Art. 45.2 LO 3/2007','Las empresas de cincuenta o más trabajadores.',null),
('aux-canarias:10-bfa8324011','aux-canarias',10,'Según la LO 3/2007, hay composición equilibrada cuando las personas de cada sexo:','["Son exactamente el 50 %", "No superan el 70 % ni son menos del 30 %", "No superan el 55 % ni son menos del 45 %", "No superan el 60 % ni son menos del 40 %"]'::jsonb,3,'Disp. adicional 1.ª LO 3/2007','Las personas de cada sexo no superan el sesenta por ciento ni son menos del cuarenta por ciento.',null),
('aux-canarias:10-b5efb188da','aux-canarias',10,'El Plan para la Igualdad entre mujeres y hombres en la Administración General del Estado se aprueba por el Gobierno:','["Cada diez años", "Cada año", "Solo cuando lo pide el Congreso", "Al inicio de cada legislatura"]'::jsonb,3,'Art. 64 LO 3/2007','Su cumplimiento se evalúa anualmente por el Consejo de Ministros.',null),
('aux-canarias:10-da1501c93d','aux-canarias',10,'En los litigios sobre acoso sexual y acoso por razón de sexo, está legitimada:','["Cualquier ciudadano", "Únicamente la persona acosada", "El sindicato mayoritario en todo caso", "El Ministerio Fiscal en exclusiva"]'::jsonb,1,'Art. 12.3 LO 3/2007','La persona acosada es la única legitimada.',null),
('aux-canarias:10-27296d84d3','aux-canarias',10,'Según el art. 6.3 de la LO 3/2007, toda orden de discriminar, directa o indirectamente, por razón de sexo:','["Se considerará en todo caso discriminatoria", "No tiene relevancia jurídica si no llega a ejecutarse", "Solo es discriminatoria si se ejecuta", "Es válida si procede de un superior"]'::jsonb,0,'Art. 6.3 LO 3/2007','La orden de discriminar es en sí misma discriminación.',null),
('aux-canarias:10-b60680165b','aux-canarias',10,'Las acciones positivas para hacer efectivo el derecho a la igualdad pueden adoptarlas:','["Solo el Gobierno y las Administraciones públicas", "Solo los jueces y tribunales en sus sentencias", "Solo las empresas de más de 250 trabajadores, dentro de su plan de igualdad negociado con la representación legal de los trabajadores", "Los poderes públicos y también las personas físicas y jurídicas privadas"]'::jsonb,3,'Art. 11 LO 3/2007','Deben ser razonables y proporcionadas.',null),
('aux-canarias:10-97962d8a3a','aux-canarias',10,'Los proyectos de disposiciones de carácter general y los planes de especial relevancia que se sometan a la aprobación del Consejo de Ministros deberán incorporar:','["Un informe del Consejo de Estado en todo caso", "Un informe sobre su impacto por razón de género", "Un informe económico de la UE", "La firma de todas las Comunidades Autónomas"]'::jsonb,1,'Art. 19 LO 3/2007','Es el informe de impacto de género.',null),
('aux-canarias:10-ec0ceab504','aux-canarias',10,'Según la LO 3/2007, se considera discriminación por razón de sexo cualquier trato adverso o efecto negativo producido como consecuencia de:','["Su afiliación a un partido político o a un sindicato", "Su cambio de domicilio", "La presentación por una persona de una queja, reclamación, denuncia o demanda destinada a impedir su discriminación", "Su ascenso profesional o la obtención de un puesto de libre designación tras un procedimiento de provisión con convocatoria pública"]'::jsonb,2,'Art. 9 LO 3/2007','Es la garantía de indemnidad frente a represalias.',null),
('aux-canarias:10-74af988505','aux-canarias',10,'Entre los criterios de actuación de las Administraciones en el empleo público, la LO 3/2007 incluye:','["Promover la presencia equilibrada de mujeres y hombres en los órganos de selección y valoración", "Suprimir los planes de igualdad", "Establecer cuotas obligatorias del 60 % de mujeres en todos los órganos de selección y valoración", "Reservar los puestos directivos a la persona más antigua"]'::jsonb,0,'Art. 51 d) LO 3/2007','También establecer medidas efectivas para eliminar cualquier discriminación retributiva.',null),
('aux-canarias:10-1c94361489','aux-canarias',10,'En los procedimientos (no penales) en que se aleguen actuaciones discriminatorias por razón de sexo, corresponde probar la ausencia de discriminación a:','["La persona demandante", "El Ministerio Fiscal", "La persona demandada", "El juez"]'::jsonb,2,'Art. 13.1 LO 3/2007','Es la inversión de la carga de la prueba; no se aplica a los procesos penales.',null),
('aux-canarias:10-e2b422fe2f','aux-canarias',10,'¿A quién se aplica la Ley 1/2010 canaria de igualdad, además de en el territorio del archipiélago?','["A quien tenga la condición política de canario y resida en el exterior", "A las empresas con sede social en Canarias que operen fuera del archipiélago, en todo caso", "A todos los españoles de origen canario, con independencia de su lugar de residencia", "A ninguna persona fuera del archipiélago"]'::jsonb,0,'Art. 2.1 Ley 1/2010 Canarias','La ley se aplica en el territorio del archipiélago y a quien tenga la condición política de canario o canaria y resida en el exterior.',null),
('aux-canarias:10-aebdd6f495','aux-canarias',10,'Según la Ley 1/2010 canaria, ¿qué principio comporta aplicar la perspectiva de género en la planificación, ejecución y evaluación de todas las políticas?','["La coordinación", "La acción positiva", "La transversalidad", "La corresponsabilidad"]'::jsonb,2,'Art. 4.15 Ley 1/2010 Canarias','La transversalidad comporta aplicar la perspectiva de género en las fases de planificación, ejecución y evaluación de todas las políticas.',null),
('aux-canarias:10-6f6d3b8f2f','aux-canarias',10,'¿Qué informe deben incorporar los proyectos de ley, reglamentos y planes del Gobierno de Canarias según la Ley 1/2010?','["Un informe del Consejo Consultivo de Canarias", "Un informe de evaluación del impacto de género", "Un informe de la Comisión Interdepartamental para la Igualdad", "Un informe del Observatorio de la Igualdad de Género"]'::jsonb,1,'Art. 6.2 Ley 1/2010 Canarias','En su tramitación debe emitirse un informe de evaluación del impacto de género de su contenido.',null),
('aux-canarias:10-ad1a1ed028','aux-canarias',10,'¿Qué órgano elabora y tramita la Estrategia de Igualdad de Género del Gobierno de Canarias?','["El Consejo Canario de Igualdad de Género", "La Consejería de Hacienda", "La Comisión Interdepartamental para la Igualdad", "El Instituto Canario de Igualdad"]'::jsonb,3,'Art. 7.2 Ley 1/2010 Canarias','La elaboración y tramitación de la Estrategia de Igualdad de Género corresponde al Instituto Canario de Igualdad.',null),
('aux-canarias:10-886eb72077','aux-canarias',10,'¿Qué naturaleza tiene la Estrategia de Igualdad de Género para la Administración Pública de Canarias?','["Vinculante", "Orientativa", "Facultativa para cada consejería", "Solo vinculante para los cabildos"]'::jsonb,0,'Art. 7.1 Ley 1/2010 Canarias','La estrategia es de carácter transversal y de naturaleza vinculante para la Administración Pública de la Comunidad Autónoma.',null),
('aux-canarias:10-1668c88e2b','aux-canarias',10,'¿Qué órgano emite el informe de evaluación de impacto de género sobre el anteproyecto de Ley del Presupuesto de Canarias?','["La Audiencia de Cuentas", "El Instituto Canario de Igualdad, a través de su unidad de presupuestos con perspectiva de género", "La Intervención General", "La Comisión de Impacto de Género en los Presupuestos"]'::jsonb,3,'Art. 9.1 Ley 1/2010 Canarias','Lo emite la Comisión de Impacto de Género en los Presupuestos, dependiente de la consejería de Hacienda, con participación del Instituto Canario de Igualdad.',null),
('aux-canarias:10-569670d9f4','aux-canarias',10,'¿Dónde se crean las Unidades de Igualdad de Género según la Ley 1/2010 canaria?','["Solo en la consejería competente en igualdad", "En cada cabildo insular", "En todas las consejerías", "En los ayuntamientos de más de 20.000 habitantes"]'::jsonb,2,'Art. 68.1 Ley 1/2010 Canarias','Se crean Unidades de Igualdad de Género en todas las consejerías para impulsar la perspectiva de género en sus políticas.',null),
('aux-canarias:10-04972b8400','aux-canarias',10,'¿Qué órgano asume en cada consejería las funciones de la Unidad de Igualdad de Género, salvo que se determine otro?','["La dirección general de personal", "La secretaría general técnica", "El gabinete del consejero", "La viceconsejería"]'::jsonb,1,'Art. 68.2 Ley 1/2010 Canarias','Cada consejería encomienda a su secretaría general técnica o, en su defecto, al órgano que determine el consejero, las funciones de la Unidad.',null),
('aux-canarias:10-d7d8a9e214','aux-canarias',10,'¿A qué organismo está adscrito el Observatorio de la Igualdad de Género de Canarias?','["A la Consejería de Educación", "Al Instituto Canario de Igualdad", "Al Parlamento de Canarias", "A la Presidencia del Gobierno"]'::jsonb,1,'Art. 69.1 Ley 1/2010 Canarias','El Observatorio es un órgano asesor adscrito al Instituto Canario de Igualdad.',null),
('aux-canarias:10-36ca0db97f','aux-canarias',10,'¿Quién preside la Comisión Interdepartamental para la Igualdad entre Mujeres y Hombres de Canarias?','["La persona titular de la consejería competente en igualdad", "La directora o director del Instituto Canario de Igualdad, por delegación", "El presidente del Gobierno de Canarias", "El vicepresidente del Gobierno"]'::jsonb,0,'Art. 67.1 Ley 1/2010 Canarias','La Comisión, con representación de todas las consejerías, la preside el titular de la consejería competente en materia de igualdad.',null),
('aux-canarias:10-f3d730299e','aux-canarias',10,'¿Qué es el Consejo Canario de Igualdad de Género?','["El órgano directivo de la política de igualdad del Gobierno de Canarias, con rango de dirección general", "Un órgano de la Diputación del Común", "La comisión parlamentaria de igualdad", "El órgano de consulta del Instituto Canario de Igualdad y de participación de organizaciones"]'::jsonb,3,'Art. 70.1 Ley 1/2010 Canarias','Es el órgano de consulta del Instituto Canario de Igualdad y de participación de organizaciones y agentes sociales que trabajan por la igualdad.',null),
('aux-canarias:10-58a96ba00d','aux-canarias',10,'¿Quién elabora periódicamente planes de igualdad según el artículo 35 de la Ley 1/2010 canaria?','["El Parlamento de Canarias", "Los cabildos insulares exclusivamente", "El Gobierno de Canarias, sus empresas públicas y entidades instrumentales", "Solo las empresas privadas de más de 50 trabajadores con sede en Canarias"]'::jsonb,2,'Art. 35.1 Ley 1/2010 Canarias','El Gobierno de Canarias, sus empresas públicas y entidades instrumentales elaboran periódicamente planes de igualdad.',null),
('aux-canarias:10-7cb467bece','aux-canarias',10,'¿Qué distintivo pueden tener las empresas para obtener preferencia en la adjudicación en caso de empate según la Ley 1/2010?','["La Marca de Excelencia Canaria en igualdad", "El certificado de empresa familiar canaria", "El sello de Responsabilidad Social de Canarias", "El distintivo Igualdad en la Empresa del Estado únicamente"]'::jsonb,0,'Art. 13.2 Ley 1/2010 Canarias','Los pliegos darán preferencia, en igualdad de condiciones, a las empresas con la Marca de Excelencia Canaria de Igualdad o con medidas de igualdad.',null),
('aux-canarias:10-3f10a6ba7b','aux-canarias',10,'¿Con qué empresas no formalizará la Administración canaria ayudas y subvenciones según la Ley 1/2010?','["Con las que no tengan plan de igualdad, sea cual sea su número de trabajadores", "Con las de menos de diez trabajadores", "Con las sancionadas o condenadas en firme por prácticas laborales discriminatorias", "Con las que tengan sede fuera de Canarias"]'::jsonb,2,'Art. 14.2 Ley 1/2010 Canarias','No se formalizarán con empresas sancionadas o condenadas en firme por alentar o tolerar prácticas laborales discriminatorias.',null),
('aux-canarias:10-a97385668f','aux-canarias',10,'¿Qué se designará en los consejos escolares de los centros públicos y concertados de Canarias según la Ley 1/2010?','["Una comisión de igualdad de tres miembros", "Una persona con formación en igualdad de género", "Un inspector de igualdad nombrado por el Instituto Canario de Igualdad", "Un representante del Instituto Canario de Igualdad en cada centro"]'::jsonb,1,'Art. 20 Ley 1/2010 Canarias','Se designará una persona con formación en igualdad de género que impulse y siga las medidas educativas de igualdad.',null),
('aux-canarias:11-9d99fae358','aux-canarias',11,'La LO 1/2004 actúa contra la violencia que se ejerce sobre las mujeres por parte de quienes sean o hayan sido sus cónyuges o parejas:','["Aun sin convivencia", "Solo si conviven", "Solo si están casados", "Solo si hay hijos en común"]'::jsonb,0,'Art. 1.1 LO 1/2004','Comprende a quienes sean o hayan sido sus cónyuges o hayan estado ligados por relaciones similares de afectividad, aun sin convivencia.',null),
('aux-canarias:11-6668dda15d','aux-canarias',11,'Según la LO 1/2004, la violencia de género comprende:','["Solo la violencia física que cause lesiones", "Todo acto de violencia física y psicológica, incluidas las agresiones a la libertad sexual, las amenazas, las coacciones o la privación arbitraria de libertad", "Todo acto de violencia física, incluidas las agresiones a la libertad sexual, pero no la violencia psicológica, las amenazas ni las coacciones, que se rigen por el Código Penal", "Solo la violencia física ejercida en el domicilio familiar que cause lesiones acreditadas por un médico, excluidas las amenazas, las coacciones y la violencia psicológica"]'::jsonb,1,'Art. 1.3 LO 1/2004','Comprende todo acto de violencia física y psicológica, incluidas agresiones a la libertad sexual, amenazas, coacciones o privación arbitraria de libertad.',null),
('aux-canarias:11-ea6568aba0','aux-canarias',11,'¿Cuál de estos derechos tiene la trabajadora víctima de violencia de género?','["Una indemnización automática a cargo de su empresa", "El ascenso de categoría", "La reducción o reordenación de su tiempo de trabajo, la movilidad geográfica o la suspensión con reserva de puesto", "La reducción de jornada sin disminución proporcional del salario, la movilidad geográfica y el cambio de empresa dentro del grupo"]'::jsonb,2,'Art. 21.1 LO 1/2004','Tiene derecho, entre otros, a la reducción o reordenación de jornada, la movilidad geográfica, el cambio de centro, la suspensión con reserva de puesto y la extinción del contrato.',null),
('aux-canarias:11-63bf6aaa1c','aux-canarias',11,'Para acreditar la situación de violencia de género y acceder a los derechos laborales sirve, entre otros:','["Una declaración jurada de un vecino o familiar", "El certificado de empadronamiento junto con una declaración jurada de la propia trabajadora", "Un parte de lesiones expedido por una clínica privada sin intervención judicial ni fiscal", "La orden de protección o el informe del Ministerio Fiscal"]'::jsonb,3,'Art. 23 LO 1/2004','Se acredita con sentencia condenatoria, orden de protección, informe del Ministerio Fiscal, informe de los servicios sociales o especializados u otro título previsto.',null)
insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('aux-canarias:11-d853c73739','aux-canarias',11,'La funcionaria víctima de violencia de género tiene derecho, entre otros, a:','["La excedencia, la reducción o reordenación de su tiempo de trabajo y la movilidad geográfica", "El cambio automático de cuerpo o escala", "Un permiso retribuido de un año, la reducción de jornada sin merma de retribuciones y la jubilación anticipada voluntaria", "La jubilación anticipada sin reducción de la pensión y un permiso retribuido de un año completo"]'::jsonb,0,'Art. 24 LO 1/2004','Tiene derecho a la reducción o reordenación de su tiempo de trabajo, a la movilidad geográfica de centro de trabajo y a la excedencia.',null),
('aux-canarias:11-950dd33fd5','aux-canarias',11,'¿Qué órganos judiciales creó la LO 1/2004?','["Las Audiencias de Familia", "Los Juzgados de Violencia sobre la Mujer", "Los Tribunales de Igualdad", "Las Salas de Género del Tribunal Supremo"]'::jsonb,1,'Art. 43 LO 1/2004','Creó los Juzgados de Violencia sobre la Mujer, añadiendo el art. 87 bis a la LOPJ.',null),
('aux-canarias:11-d2a2da9527','aux-canarias',11,'El Fiscal contra la Violencia sobre la Mujer:','["Es elegido por el Congreso por mayoría de tres quintos", "Depende orgánicamente del Ministerio de Igualdad, que lo nombra a propuesta del Consejo de Ministros", "Es nombrado, oído el Consejo Fiscal, como delegado, con categoría de Fiscal de Sala", "Es un fiscal de cada provincia"]'::jsonb,2,'Art. 70 LO 1/2004','Se nombra, oído el Consejo Fiscal, como delegado, con categoría de Fiscal de Sala.',null),
('aux-canarias:11-8d79dca1e9','aux-canarias',11,'Según la LO 1/2004, la víctima de violencia de género tiene derecho a recibir asesoramiento jurídico gratuito:','["Solo si es funcionaria o empleada pública", "Solo después de que recaiga sentencia condenatoria firme contra el agresor", "En el momento inmediatamente previo a la interposición de la denuncia", "Solo si tiene hijos menores a su cargo"]'::jsonb,2,'Art. 20.1 LO 1/2004','También tienen derecho a defensa y representación gratuitas.',null),
('aux-canarias:11-069ad0f102','aux-canarias',11,'Según la LO 1/2004, en cada partido judicial habrá:','["Uno o más Juzgados de Violencia sobre la Mujer", "Un Juzgado de Paz especializado", "Un Tribunal de Violencia de Género con jurado", "Una Audiencia especializada"]'::jsonb,0,'Art. 43 LO 1/2004 (art. 87 bis LOPJ)','La LO 1/2004 añadió el art. 87 bis a la LOPJ.',null),
('aux-canarias:11-421d20b1f9','aux-canarias',11,'La información a las víctimas de violencia de género sobre sus derechos se garantizará también a las mujeres que, por sus circunstancias personales y sociales, tengan dificultad de acceso, como:','["Solo las mujeres extranjeras en situación irregular", "Solo las empleadas públicas", "Solo las menores de edad, a través de sus representantes legales", "Las mujeres con discapacidad, en formato accesible"]'::jsonb,3,'Art. 18.2 LO 1/2004','También a quienes no dominen las lenguas oficiales (art. 18.3).',null),
('aux-canarias:11-370f462afb','aux-canarias',11,'El Observatorio Estatal de Violencia sobre la Mujer es:','["Una organización no gubernamental de ámbito estatal declarada de utilidad pública", "Un órgano colegiado de asesoramiento, evaluación y colaboración institucional", "Una sección especializada de la Fiscalía", "Un juzgado especializado en violencia sobre la mujer con competencia en toda España"]'::jsonb,1,'Art. 30.1 LO 1/2004','Remite al Gobierno y a las CCAA un informe anual.',null),
('aux-canarias:11-668b27dad0','aux-canarias',11,'La suspensión y la extinción del contrato de trabajo de la trabajadora víctima de violencia de género:','["Darán lugar a situación legal de desempleo", "Requieren autorización judicial previa", "No dan derecho a prestación por desempleo, salvo que lo reconozca una sentencia", "Se consideran despido disciplinario"]'::jsonb,0,'Art. 21.2 LO 1/2004','El tiempo de suspensión se considera periodo de cotización efectiva.',null),
('aux-canarias:11-ab56a26820','aux-canarias',11,'Las ausencias o faltas de puntualidad al trabajo de la trabajadora víctima de violencia de género motivadas por su situación física o psicológica:','["Se descuentan del sueldo en todo caso, aunque los servicios sociales de atención o de salud acrediten que están motivadas por su situación física o psicológica", "Se considerarán justificadas y serán remuneradas cuando así lo determinen los servicios sociales de atención o de salud", "Requieren autorización judicial", "Serán siempre sancionadas como falta leve, aunque los servicios sociales de atención o de salud acrediten que derivan de su situación"]'::jsonb,1,'Art. 21.4 LO 1/2004','Deben comunicarse a la empresa a la mayor brevedad.',null),
('aux-canarias:11-6e0331bfdf','aux-canarias',11,'Los servicios de asistencia social integral a las víctimas de violencia de género responderán, entre otros, a los principios de:','["Gratuidad parcial, voluntariedad, subsidiariedad respecto de los servicios generales y atención exclusiva en horario de oficina", "Secreto, discrecionalidad, gratuidad parcial, subsidiariedad respecto de los servicios generales y atención en horario de oficina", "Centralización y uniformidad", "Atención permanente, actuación urgente, especialización de prestaciones y multidisciplinariedad profesional"]'::jsonb,3,'Art. 19.1 LO 1/2004','Son los principios de la asistencia social integral.',null),
('aux-canarias:11-841732c9db','aux-canarias',11,'La Delegación del Gobierno contra la Violencia de Género, entre otras funciones:','["Dicta resoluciones vinculantes para los juzgados de violencia sobre la mujer", "Dirige y coordina a la policía judicial en las investigaciones de violencia de género y dicta instrucciones a los juzgados especializados", "Elabora la Macroencuesta de Violencia contra las Mujeres y está legitimada ante los órganos jurisdiccionales", "Impone sanciones administrativas a los agresores y dirige las investigaciones de la policía judicial en los casos más graves"]'::jsonb,2,'Art. 29 LO 1/2004','Formula las políticas públicas en materia de violencia de género.',null),
('aux-canarias:11-64c8e973e7','aux-canarias',11,'¿Qué norma aprobó el Texto Refundido de la Ley General de derechos de las personas con discapacidad y de su inclusión social?','["El Real Decreto Legislativo 1/2013, de 29 de noviembre", "El Real Decreto Legislativo 5/2015, de 30 de octubre", "La Ley 39/2006, de 14 de diciembre", "La Ley 51/2003, de 2 de diciembre"]'::jsonb,0,'RDL 1/2013','La Ley 39/2006 regula la dependencia y el RDL 5/2015 es el TREBEP.',null),
('aux-canarias:11-63497b067f','aux-canarias',11,'Según el Real Decreto Legislativo 1/2013, tienen la consideración de personas con discapacidad, a todos los efectos, aquellas a quienes se haya reconocido un grado de discapacidad:','["Igual o superior al 33 %", "Igual o superior al 65 %", "Igual o superior al 25 %", "Superior al 50 %"]'::jsonb,0,'Art. 4.2 RDL 1/2013','También se consideran así, entre otros, los pensionistas de la Seguridad Social con incapacidad permanente total, absoluta o gran invalidez.',null),
('aux-canarias:11-74178294b8','aux-canarias',11,'Las empresas públicas y privadas que empleen a 50 o más trabajadores están obligadas a que, de entre ellos, sean trabajadores con discapacidad al menos:','["El 2 %", "El 7 %", "El 1 %", "El 5 %"]'::jsonb,0,'Art. 42.1 RDL 1/2013','Excepcionalmente pueden quedar exentas aplicando medidas alternativas.',null),
('aux-canarias:11-31cb197c4c','aux-canarias',11,'Según el RDL 1/2013, los «ajustes razonables» son:','["Las ayudas económicas que concede la Administración a las personas con un grado de discapacidad superior al 65 % para adaptar su puesto de trabajo y su vivienda habitual", "Las reducciones de jornada a las que tienen derecho todos los trabajadores con discapacidad", "Las modificaciones y adaptaciones necesarias y adecuadas que no impongan una carga desproporcionada o indebida, cuando se requieran en un caso particular", "Las bonificaciones fiscales que reciben las empresas por contratar personas con discapacidad"]'::jsonb,2,'Art. 2 RDL 1/2013','Buscan facilitar la accesibilidad y la participación en igualdad de condiciones.',null),
('aux-canarias:11-aac049efe9','aux-canarias',11,'Según el RDL 1/2013, la accesibilidad universal es:','["El derecho de las personas con discapacidad a recibir una prestación económica de la Comunidad Autónoma para adaptar su vivienda habitual y su vehículo particular", "La condición que deben cumplir entornos, procesos, bienes, productos, servicios y objetos para ser comprensibles, utilizables y practicables por todas las personas", "La obligación de reservar plazas de aparcamiento en todos los edificios públicos", "El acceso gratuito de las personas con discapacidad a los transportes públicos"]'::jsonb,1,'Art. 2 RDL 1/2013','Debe darse en condiciones de seguridad y comodidad y de la forma más autónoma y natural posible.',null),
('aux-canarias:12-d7d8e86ce2','aux-canarias',12,'Las personas físicas, ¿pueden elegir si se comunican con las Administraciones por medios electrónicos?','["Sí, en todo momento, salvo que estén obligadas", "No, siempre deben usar medios electrónicos", "No, siempre deben ir en persona", "Solo si son mayores de 65 años"]'::jsonb,0,'Art. 14.1 Ley 39/2015','Pueden elegir en todo momento, salvo que estén obligadas a relacionarse electrónicamente.',null),
('aux-canarias:12-ab1354051e','aux-canarias',12,'¿Cuál de los siguientes NO está obligado, con carácter general, a relacionarse electrónicamente con las Administraciones?','["Una persona jurídica", "Una persona física que actúa en su propio nombre", "Una entidad sin personalidad jurídica", "Un empleado público en trámites por razón de su condición"]'::jsonb,1,'Art. 14.2 Ley 39/2015','Están obligados las personas jurídicas, las entidades sin personalidad, los profesionales con colegiación obligatoria, los representantes de obligados y los empleados públicos en esos trámites.',null),
('aux-canarias:12-8d6c5c78e7','aux-canarias',12,'Las personas tienen derecho a comunicarse con las Administraciones a través de:','["Un número de WhatsApp oficial de cada organismo", "Su correo electrónico personal, que tiene la misma validez que el registro", "Un Punto de Acceso General electrónico", "Los perfiles oficiales en redes sociales"]'::jsonb,2,'Art. 13 a) Ley 39/2015','Tienen derecho a comunicarse a través de un Punto de Acceso General electrónico de la Administración.',null),
('aux-canarias:12-07713e43a7','aux-canarias',12,'Es un derecho del interesado en el procedimiento:','["Obtener una resolución favorable si la Administración no resuelve en plazo", "Conocer en cualquier momento el estado de la tramitación de los procedimientos en los que sea interesado", "Elegir al instructor del procedimiento", "Conocer en cualquier momento el estado de tramitación de cualquier procedimiento de la Administración, aunque no tenga la condición de interesado"]'::jsonb,1,'Art. 53.1 a) Ley 39/2015','También el sentido del silencio, el órgano competente y obtener copia de los documentos.',null),
('aux-canarias:12-dba7cb5ed0','aux-canarias',12,'La Administración instructora deberá traducir al castellano:','["Los documentos que deban surtir efecto fuera del territorio de la Comunidad y los dirigidos a interesados que lo soliciten expresamente", "Todos los documentos redactados en lengua cooficial, sin excepción", "Solo los documentos dirigidos a interesados que residan fuera de la Comunidad Autónoma", "Los documentos que deban surtir efecto en la Comunidad, y los dirigidos a interesados que no conozcan la lengua cooficial aunque no lo pidan"]'::jsonb,0,'Art. 15.3 Ley 39/2015','Se traducen los que deban surtir efecto fuera de la Comunidad y los que pidan los interesados.',null),
('aux-canarias:12-1c976c00d5','aux-canarias',12,'En los procedimientos sancionadores, el presunto responsable tiene derecho, además:','["A elegir la sanción entre las previstas para la infracción", "A no declarar contra sí mismo, pero no a la presunción de inocencia, que es exclusiva del proceso penal", "A que se le notifique la sanción", "A la presunción de no existencia de responsabilidad administrativa mientras no se demuestre lo contrario"]'::jsonb,3,'Art. 53.2 b) Ley 39/2015','Es la presunción de inocencia en el ámbito sancionador.',null),
('aux-canarias:12-054568e021','aux-canarias',12,'Si concurren varios interesados en un procedimiento de la AGE y existe discrepancia en cuanto a la lengua:','["Se tramitará en la lengua cooficial", "Lo decide el interesado que figure en primer lugar", "Se tramitará en ambas lenguas", "El procedimiento se tramitará en castellano"]'::jsonb,3,'Art. 15.1 Ley 39/2015','En caso de discrepancia, se tramita en castellano.',null),
('aux-canarias:12-e475067c65','aux-canarias',12,'Según el art. 53.1 d), los interesados pueden formular alegaciones y aportar documentos:','["Solo en la solicitud inicial", "Solo en el período de prueba", "En cualquier fase del procedimiento anterior al trámite de audiencia", "En cualquier fase del procedimiento, incluso después de dictarse la resolución"]'::jsonb,2,'Art. 53.1 d) Ley 39/2015','Hasta el trámite de audiencia, que deberán ser tenidos en cuenta al redactar la propuesta de resolución.',null),
('aux-canarias:12-8b28da9995','aux-canarias',12,'Es un derecho de las personas en sus relaciones con las AAPP según el art. 13:','["Elegir al funcionario que tramite su expediente", "Obtener una resolución favorable si la Administración incumple el plazo máximo para resolver", "Ser tratados con respeto y deferencia por las autoridades y empleados públicos", "Ser atendidos en la lengua que elijan, cualquiera que sea la Administración"]'::jsonb,2,'Art. 13 e) Ley 39/2015','Otros: comunicarse por el Punto de Acceso General electrónico, ser asistidos en el uso de medios electrónicos, usar lenguas cooficiales, acceso a información pública…',null),
('aux-canarias:12-ae223b69ac','aux-canarias',12,'En los procedimientos tramitados por la AGE, la lengua será:','["Siempre la lengua cooficial del territorio donde tenga su sede el órgano", "El castellano, sin que los interesados puedan utilizar ninguna otra lengua, aunque se dirijan a órganos con sede en una Comunidad Autónoma con lengua cooficial", "El castellano, aunque los interesados que se dirijan a órganos con sede en una Comunidad con lengua cooficial podrán utilizar también esta", "La que elija el funcionario que tramite el procedimiento, castellano o lengua cooficial, sin que el interesado pueda solicitar que se utilice otra"]'::jsonb,2,'Art. 15.1 Ley 39/2015','La lengua de la AGE es el castellano, con posibilidad de usar la cooficial ante órganos con sede en esa Comunidad.',null),
('aux-canarias:12-5e70fa5556','aux-canarias',12,'La obligación de relacionarse electrónicamente con la Administración para ciertos colectivos de personas físicas puede establecerse:','["Reglamentariamente, para cualquier persona física mayor de edad", "Por resolución del órgano instructor en cada procedimiento concreto", "Reglamentariamente, si queda acreditado que tienen acceso y disponibilidad de los medios electrónicos", "Solo por ley y únicamente para los profesionales que estén colegiados"]'::jsonb,2,'Art. 14.3 Ley 39/2015','Puede imponerse por reglamento a colectivos que, por capacidad económica, técnica o dedicación profesional, tengan acceso a esos medios.',null),
('aux-canarias:12-d6d9417425','aux-canarias',12,'Según el artículo 13 de la Ley 39/2015, es un derecho de las personas en sus relaciones con las Administraciones Públicas:','["Obtener siempre una resolución favorable cuando cumplan los requisitos formales", "Exigir que se les atienda fuera del horario de atención al público", "Elegir al funcionario que tramitará su procedimiento", "Ser tratadas con respeto y deferencia por las autoridades y empleados públicos, que habrán de facilitarles el ejercicio de sus derechos"]'::jsonb,3,'Art. 13 e) Ley 39/2015','El artículo 13 recoge también, entre otros, el derecho a ser asistidas en el uso de medios electrónicos.',null),
('aux-canarias:12-226c8f5c00','aux-canarias',12,'¿Cuál de los siguientes está obligado a relacionarse electrónicamente con las Administraciones según el artículo 14.2 de la Ley 39/2015?','["Las personas físicas mayores de 65 años", "Los extranjeros residentes en España", "Las personas jurídicas", "Los autónomos sin colegiación obligatoria"]'::jsonb,2,'Art. 14.2 Ley 39/2015','También las entidades sin personalidad jurídica, los profesionales de colegiación obligatoria en el ejercicio de su actividad, sus representantes y los empleados públicos en los trámites por su condición de tales.',null),
('aux-canarias:13-44bc3e0a04','aux-canarias',13,'En la atención al público, la escucha activa consiste en:','["Prestar atención plena al interlocutor y demostrarle que se le entiende, por ejemplo resumiendo o preguntando", "Escuchar en silencio, sin hacer preguntas ni dar ninguna señal, hasta que el ciudadano haya terminado de hablar", "Tomar nota de la petición del ciudadano y remitirla por escrito a la unidad competente para que esta le conteste", "Hablar más que el ciudadano para dirigir la conversación hacia la solución que ya se conoce de antemano en cada caso"]'::jsonb,0,'Comunicación en la atención al público','Incluye señales verbales y no verbales de comprensión, como asentir o parafrasear.',null),
('aux-canarias:13-f31b8a1c23','aux-canarias',13,'La empatía en la atención al ciudadano supone:','["Tratar a cada persona con la misma frialdad para ser imparcial", "Dar siempre la razón al ciudadano para evitar conflictos", "Ponerse en el lugar del otro y comprender su situación y sus sentimientos", "Compartir con el ciudadano las opiniones personales sobre la Administración"]'::jsonb,2,'Comunicación en la atención al público','Comprender no significa necesariamente estar de acuerdo.',null),
('aux-canarias:13-3b033aa693','aux-canarias',13,'La asertividad es la habilidad de:','["Responder con rapidez sin escuchar los argumentos del otro", "Expresar las propias opiniones y necesidades de forma clara y respetuosa, sin agredir ni someterse", "Imponer el criterio propio al interlocutor cuando se tiene autoridad para ello, aunque el otro no esté de acuerdo", "Evitar cualquier desacuerdo con el ciudadano cediendo a lo que pide, aunque no sea posible atenderlo"]'::jsonb,1,'Comunicación en la atención al público','Es el punto medio entre la conducta pasiva y la agresiva.',null),
('aux-canarias:13-60a2ab5f15','aux-canarias',13,'La proxémica estudia:','["La forma de redactar los escritos y comunicaciones administrativos dirigidos a los ciudadanos", "El tono, el volumen, el ritmo y las pausas de la voz al hablar con otras personas", "Los gestos, la postura y los movimientos del cuerpo durante la conversación", "El uso del espacio y las distancias entre las personas en la comunicación"]'::jsonb,3,'Comunicación no verbal','Los gestos y movimientos los estudia la kinésica y los aspectos de la voz, el paralenguaje.',null),
('aux-canarias:13-f54887cc1c','aux-canarias',13,'El tono, el volumen, el ritmo y las pausas de la voz forman parte de:','["El paralenguaje", "La proxémica", "La comunicación escrita", "La kinésica"]'::jsonb,0,'Comunicación no verbal','Acompañan a las palabras y pueden reforzar o contradecir el mensaje verbal.',null),
('aux-canarias:13-844b7c8d20','aux-canarias',13,'La kinésica es la parte de la comunicación no verbal que estudia:','["Los gestos, la postura y los movimientos corporales", "Las características de la voz, como el tono, el timbre y el volumen", "El vocabulario técnico de la Administración", "Las distancias que mantienen los interlocutores durante la conversación"]'::jsonb,0,'Comunicación no verbal','La mirada y la expresión facial también se incluyen en la kinésica.',null),
('aux-canarias:13-ede0015717','aux-canarias',13,'Según el Real Decreto 951/2005, ¿cuál de los siguientes es uno de los programas del marco general para la mejora de la calidad en la AGE?','["El programa de quejas y sugerencias", "El programa de teletrabajo", "El programa de acción social", "El programa de evaluación del desempeño individual"]'::jsonb,0,'Art. 3.1 RD 951/2005','Los programas son: análisis de la demanda y evaluación de la satisfacción, cartas de servicios, quejas y sugerencias, evaluación de la calidad, reconocimiento y Observatorio de la Calidad.',null),
('aux-canarias:13-72cd274a1a','aux-canarias',13,'Según el Real Decreto 951/2005, ¿en qué plazo debe informarse al ciudadano de las actuaciones realizadas tras una queja o sugerencia?','["Tres meses desde su presentación", "Quince días naturales", "Veinte días hábiles", "Un mes desde su presentación"]'::jsonb,2,'Art. 16.1 RD 951/2005','El plazo se suspende si se requiere al interesado para que aclare su queja, por un máximo de diez días hábiles.',null),
('aux-canarias:13-ebaf0acf08','aux-canarias',13,'Si el ciudadano no recibe respuesta a su queja en el plazo establecido, según el RD 951/2005 puede dirigirse a:','["El Tribunal de Cuentas", "La Inspección General de Servicios del departamento", "El Defensor del Pueblo, como único cauce", "El juzgado de lo contencioso-administrativo"]'::jsonb,1,'Art. 16.3 RD 951/2005','La Inspección General de Servicios conocerá las causas de la falta de contestación.',null),
('aux-canarias:13-84784ce8d7','aux-canarias',13,'Las quejas formuladas conforme al Real Decreto 951/2005:','["No tienen la calificación de recurso administrativo ni interrumpen los plazos de los procedimientos", "Interrumpen los plazos para recurrir", "Tienen la consideración de recurso de alzada ante el superior jerárquico del órgano que dictó el acto del que se quejan", "Suspenden la ejecución del acto del que se quejan"]'::jsonb,0,'Art. 19 RD 951/2005','Tampoco condicionan el ejercicio de las demás acciones o derechos del interesado.',null),
('aux-canarias:13-1fa7ef5638','aux-canarias',13,'¿Cómo pueden presentarse las quejas y sugerencias según el RD 951/2005?','["Por escrito dirigido al Subsecretario, con firma reconocida ante notario", "A través del Defensor del Pueblo, que las traslada al órgano afectado", "Mediante comparecencia personal ante la Inspección General de Servicios del departamento", "De forma presencial, por correo postal o por medios electrónicos"]'::jsonb,3,'Art. 15 RD 951/2005','Las presentadas por medios electrónicos deben ir firmadas electrónicamente.',null),
('aux-canarias:13-0b6c067508','aux-canarias',13,'Las cartas de servicios se aprueban, según el RD 951/2005:','["Por orden del Ministro, sin necesidad de informe previo", "Por real decreto del Consejo de Ministros, a propuesta del Ministro del departamento y previo dictamen preceptivo del Consejo de Estado en pleno", "Por resolución del Subsecretario del departamento, previo informe favorable de la Secretaría General competente en función pública", "Por acuerdo de la Comisión General de Secretarios de Estado y Subsecretarios"]'::jsonb,2,'Art. 11.1 RD 951/2005','La resolución de aprobación se publica en el BOE.',null),
('aux-canarias:13-407bd7a1f8','aux-canarias',13,'Las cartas de servicios deben actualizarse:','["Cada cinco años", "Periódicamente y, al menos, cada tres años", "Cada año", "Solo cuando cambie la normativa del servicio"]'::jsonb,1,'Art. 10.4 RD 951/2005','También deben revisarse cuando cambien los servicios o los compromisos.',null),
('aux-canarias:13-8dc776c70a','aux-canarias',13,'¿Qué recogen las cartas de servicios?','["Los servicios que se ofrecen, los derechos de los usuarios y los compromisos de calidad asumidos", "La relación de puestos de trabajo del organismo", "Las retribuciones de los empleados públicos que prestan servicio en la unidad y su régimen de jornada y horario", "Las sanciones que pueden imponerse a los ciudadanos que incumplan las normas de utilización de los servicios"]'::jsonb,0,'Art. 8 RD 951/2005','Incluyen medidas de subsanación en caso de incumplimiento, que no dan lugar a responsabilidad patrimonial.',null),
('aux-canarias:13-bf2730e7d6','aux-canarias',13,'Las medidas de subsanación previstas en una carta de servicios para el caso de incumplimiento de los compromisos:','["Suponen la anulación de los actos administrativos dictados durante el incumplimiento", "Obligan a abrir un expediente disciplinario al responsable del servicio incumplido", "Dan derecho a una indemnización automática al usuario afectado por el incumplimiento", "No darán lugar a responsabilidad patrimonial de la Administración"]'::jsonb,3,'Art. 9 RD 951/2005','Normalmente consisten en una comunicación del responsable explicando las causas y las medidas adoptadas.',null),
('aux-canarias:13-448645bf4c','aux-canarias',13,'¿Qué órgano analiza periódicamente la percepción ciudadana sobre los servicios públicos según el RD 951/2005?','["El Instituto Nacional de Estadística", "El Observatorio de la Calidad de los Servicios Públicos", "El Centro de Investigaciones Sociológicas", "El Consejo de Transparencia y Buen Gobierno"]'::jsonb,1,'Art. 26 RD 951/2005','Publica un informe anual de evaluación global con conclusiones y recomendaciones.',null),
('aux-canarias:13-5a3401fe26','aux-canarias',13,'¿Cuántos programas integran el marco general para la mejora de la calidad del RD 951/2005?','["Cinco", "Ocho", "Seis", "Cuatro"]'::jsonb,2,'Art. 3 RD 951/2005','Son seis: análisis de la demanda y evaluación de la satisfacción, cartas de servicios, quejas y sugerencias, evaluación de la calidad, reconocimiento y Observatorio de la Calidad.',null),
('aux-canarias:13-a62433b1a1','aux-canarias',13,'Según el RD 951/2005, la unidad que coordina los programas de calidad en cada departamento ministerial la designa:','["El Inspector General de Servicios de la Administración Pública", "El Secretario de Estado de Función Pública", "El Subsecretario del departamento", "El Ministro del departamento"]'::jsonb,2,'Art. 3 RD 951/2005','Cada Subsecretario designa la unidad responsable de coordinar los programas de calidad en su departamento.',null),
('aux-canarias:13-8037d8b052','aux-canarias',13,'Según el RD 951/2005, la satisfacción de los usuarios con los servicios se medirá:','["De forma sistemática y permanente", "Solo cuando se reciban quejas", "Una vez al año, en el primer trimestre", "Cada tres años, al revisar la carta de servicios"]'::jsonb,0,'Art. 5 RD 951/2005','La medición de la percepción de la calidad por los usuarios se hace de forma sistemática y permanente.',null),
('aux-canarias:13-5239bb24c2','aux-canarias',13,'La resolución que aprueba una carta de servicios, según el RD 951/2005, se publica en:','["El tablón de anuncios de la oficina", "Únicamente en la sede electrónica del órgano", "El Boletín Oficial del Estado", "El Diario de Sesiones del Congreso"]'::jsonb,2,'Art. 11 RD 951/2005','La resolución aprobatoria se publica en el BOE y las cartas se difunden también por internet y en las oficinas.',null),
('aux-canarias:13-090c19eb5a','aux-canarias',13,'Los órganos con carta de servicios deben enviar, según el RD 951/2005, un informe anual sobre su cumplimiento:','["Cada tres años", "Durante el primer semestre de cada año", "En el mes de diciembre", "Durante el primer trimestre de cada año"]'::jsonb,3,'Art. 12 RD 951/2005','Los órganos remiten anualmente, en el primer trimestre, un informe sobre el grado de cumplimiento de los compromisos.',null),
('aux-canarias:13-4f8018e9fd','aux-canarias',13,'Si la unidad de quejas pide al ciudadano que aclare su queja, según el RD 951/2005 este dispone para hacerlo de:','["10 días hábiles", "15 días hábiles", "5 días hábiles", "20 días hábiles"]'::jsonb,0,'Art. 16 RD 951/2005','El plazo de 20 días hábiles para contestar se suspende y el ciudadano tiene 10 días hábiles para responder a la aclaración.',null),
('aux-canarias:13-c64cac1c47','aux-canarias',13,'¿Qué órgano realiza el seguimiento de las quejas y sugerencias en cada departamento, según el RD 951/2005?','["El Defensor del Pueblo", "El Tribunal de Cuentas", "El Consejo de Transparencia y Buen Gobierno de la Administración", "La Inspección General de Servicios del departamento"]'::jsonb,3,'Art. 17 RD 951/2005','Las Inspecciones Generales de Servicios de los departamentos realizan el seguimiento de las quejas y sugerencias.',null),
('aux-canarias:13-15e214d8d1','aux-canarias',13,'Según el RD 951/2005, para obtener el reconocimiento a la excelencia una organización debe haber realizado previamente:','["Una carta de servicios electrónica", "Una encuesta de satisfacción del Centro de Investigaciones Sociológicas", "Una autoevaluación conforme a un modelo de gestión de calidad reconocido", "Una auditoría del Tribunal de Cuentas"]'::jsonb,2,'Art. 23 RD 951/2005','Para optar al reconocimiento a la excelencia es requisito haber realizado una autoevaluación según los modelos de gestión de calidad reconocidos.',null),
('aux-canarias:13-7eaf6086e4','aux-canarias',13,'Según el RD 951/2005, ¿quién designa la unidad encargada de gestionar las quejas y sugerencias?','["La Agencia Española de Protección de Datos", "El Ministerio de Hacienda para todos los departamentos", "Cada órgano o organismo, que debe contestar al ciudadano", "El Defensor del Pueblo para toda la Administración"]'::jsonb,2,'Art. 14 RD 951/2005','Cada órgano designa la unidad responsable de la gestión de quejas y sugerencias, que debe responder al ciudadano.',null),
('aux-canarias:13-4f594cf7d6','aux-canarias',13,'Los órganos que prestan servicios electrónicos operativos deben tener, según el RD 951/2005:','["Un libro de reclamaciones en papel", "Un certificado de calidad ISO", "Cartas de servicios electrónicos", "Un defensor del usuario propio"]'::jsonb,2,'Art. 13 RD 951/2005','Los órganos con servicios electrónicos operativos elaboran cartas de servicios electrónicos.',null),
('aux-canarias:13-7e7da0f07d','aux-canarias',13,'¿Qué norma regula los servicios de información administrativa y atención al ciudadano en la Administración General del Estado?','["El Real Decreto 203/2021, de 30 de marzo de 2021", "El Real Decreto 364/1995, de 10 de marzo de 1995", "El Real Decreto 951/2005, de 29 de julio de 2005", "El Real Decreto 208/1996, de 9 de febrero"]'::jsonb,3,'RD 208/1996','El RD 951/2005 regula el marco general para la mejora de la calidad y el RD 203/2021 el Reglamento de actuación y funcionamiento del sector público por medios electrónicos.',null),
('aux-canarias:13-758878990d','aux-canarias',13,'Según el Real Decreto 208/1996, la información administrativa puede ser:','["Verbal, escrita o telemática", "Ordinaria o extraordinaria", "General o particular", "Pública, reservada o secreta"]'::jsonb,2,'Art. 1 RD 208/1996','Es el cauce a través del cual los ciudadanos conocen sus derechos y obligaciones y la utilización de los bienes y servicios públicos.',null),
('aux-canarias:13-24caf6636b','aux-canarias',13,'La información general, según el Real Decreto 208/1996, se facilitará:','["A los interesados en un procedimiento administrativo o a sus representantes legales debidamente acreditados", "Previo pago de la tasa correspondiente", "A quien la solicite por escrito y acredite un interés legítimo, personal y directo en el asunto", "Obligatoriamente a los ciudadanos, sin exigir para ello la acreditación de legitimación alguna"]'::jsonb,3,'Art. 2.2 RD 208/1996','Se refiere a la identificación, fines, competencia, estructura y localización de los órganos, y a los requisitos de procedimientos y servicios.',null),
('aux-canarias:13-8cb0b2b854','aux-canarias',13,'La información particular, según el Real Decreto 208/1996, es la relativa a:','["La estructura, las funciones y la localización de los órganos administrativos, así como la identificación de sus titulares y su horario de atención al público", "Los requisitos jurídicos para acceder a una prestación pública", "El estado o el contenido de los procedimientos en tramitación y la identificación de las autoridades y el personal bajo cuya responsabilidad se tramiten", "Las publicaciones oficiales editadas por los Ministerios"]'::jsonb,2,'Art. 3.1 RD 208/1996','Lo demás corresponde a la información general.',null),
('aux-canarias:13-4f4ba8486e','aux-canarias',13,'¿A quién puede facilitarse la información particular?','["A las personas que tengan la condición de interesados o a sus representantes legales", "A los abogados colegiados que intervengan en el procedimiento en nombre de un tercero", "A cualquier empleado público de la Administración General del Estado que la pida por escrito", "A cualquier ciudadano que la solicite, aunque no se identifique ni acredite interés alguno"]'::jsonb,0,'Art. 3.2 RD 208/1996','Debe respetarse la normativa de protección de datos personales.',null),
('aux-canarias:13-20a1305a60','aux-canarias',13,'Según el Real Decreto 208/1996, la orientación sobre los requisitos de los procedimientos que se presta en las oficinas de información:','["Vincula a la Administración en la resolución posterior del procedimiento al que se refiera", "Puede incluir la interpretación de la norma aplicable al caso concreto que plantee el ciudadano", "Debe darse siempre por escrito y con la firma del jefe de la oficina", "No puede entrañar una interpretación normativa ni una consideración jurídica o económica"]'::jsonb,3,'Art. 4 b) RD 208/1996','Se limita a la determinación de conceptos, la información sobre opciones legales o la colaboración en la cumplimentación de impresos.',null),
('aux-canarias:13-c00ede71b7','aux-canarias',13,'¿Cuál de las siguientes es una función de atención al ciudadano según el artículo 4 del RD 208/1996?','["La imposición de sanciones por infracciones leves", "La resolución definitiva de los recursos de alzada presentados por los ciudadanos contra actos del propio departamento", "La aprobación de las cartas de servicios del departamento", "La recepción y acogida, para facilitar la orientación y ayuda que precisen en el momento inicial de su visita"]'::jsonb,3,'Art. 4 a) RD 208/1996','Otras funciones son la orientación, la gestión, la recepción de iniciativas y sugerencias y la recepción de quejas.',null),
('aux-canarias:13-acf1785888','aux-canarias',13,'Las oficinas de información y atención al ciudadano de los servicios centrales pueden ser, según el RD 208/1996:','["Oficinas generales, para cualquier asunto, y oficinas especiales, para los procedimientos de cada organismo público adscrito", "Oficinas centrales en la sede de cada Ministerio, que pueden tener oficinas delegadas, y oficinas de organismos públicos", "Oficinas provinciales e insulares", "Oficinas de registro y oficinas de archivo, dependientes en ambos casos de la Secretaría General Técnica del Ministerio correspondiente"]'::jsonb,1,'Art. 8 RD 208/1996','En los órganos territoriales existen oficinas en las Delegaciones y Subdelegaciones del Gobierno.',null),
('aux-canarias:13-02863cebf9','aux-canarias',13,'Según el Real Decreto 208/1996, las oficinas de información de una Administración pueden informar sobre otras Administraciones:','["Cuando lo autorice el Delegado del Gobierno en la Comunidad Autónoma", "Cuando lo autorice el Consejo de Ministros", "Cuando así se prevea en un convenio de colaboración entre ellas", "Cuando el ciudadano lo pida expresamente por escrito"]'::jsonb,2,'Art. 10 RD 208/1996','También pueden crearse oficinas conjuntas de varias Administraciones.',null),
('aux-canarias:13-7cdc928897','aux-canarias',13,'Según el RD 208/1996, la función de orientación e información al ciudadano:','["Incluye interpretar las normas aplicables al caso concreto", "No puede suponer interpretación normativa ni valoración jurídica o económica", "Permite emitir valoraciones jurídicas, aunque no vinculantes", "Excluye ayudar al ciudadano a cumplimentar impresos y solicitudes oficiales"]'::jsonb,1,'Art. 4 b) RD 208/1996','La orientación se limita a aclarar conceptos, explicar opciones y ayudar a cumplimentar impresos; no puede entrañar interpretación normativa ni consideración jurídica o económica.',null),
('aux-canarias:13-604ad13d27','aux-canarias',13,'Según el RD 208/1996, la función de gestión de las oficinas de información comprende:','["La resolución de los procedimientos iniciados en la oficina", "La instrucción completa de los expedientes de queja y de sus recursos", "La expedición de cualquier certificado administrativo", "Las gestiones urgentes y sencillas que requieran respuesta inmediata"]'::jsonb,3,'Art. 4 c) RD 208/1996','La gestión incluye recibir la documentación inicial cuando la norma lo prevea y realizar gestiones urgentes y sencillas que requieran una respuesta inmediata.',null),
('aux-canarias:13-dd19548bf2','aux-canarias',13,'Las quejas por tardanzas, desatenciones u otras actuaciones irregulares corresponden, según el RD 208/1996, a la función de:','["Recepción de quejas y reclamaciones", "Recepción de iniciativas y sugerencias", "Orientación e información", "Asistencia en el derecho de petición"]'::jsonb,0,'Art. 4 e) RD 208/1996','El art. 4 e) atribuye a las oficinas la recepción de las quejas por tardanzas, desatenciones o cualquier otro tipo de actuación irregular.',null),
('aux-canarias:13-4f1b58eed8','aux-canarias',13,'Si un ciudadano quiere ejercer el derecho de petición sin saber a quién dirigirlo, según el RD 208/1996 la oficina debe:','["Inadmitir la petición por falta de destinatario", "Archivarla hasta que el propio ciudadano identifique al órgano competente para resolver", "Orientarle y remitir la petición si no tiene destinatario o lo tiene equivocado", "Indicarle que acuda al Defensor del Pueblo"]'::jsonb,2,'Art. 4 f) RD 208/1996','Las unidades deben orientar sobre el ejercicio del derecho de petición y remitir las peticiones que carezcan de destinatario o lo tengan erróneo.',null),
('aux-canarias:13-e3e9afc6e1','aux-canarias',13,'Según el RD 208/1996, la información general se difundirá preferentemente:','["Exclusivamente a través del Boletín Oficial del Estado", "Por medios a distancia, como publicaciones o el teléfono", "Mediante notificación individual a cada interesado", "Solo de forma presencial en las oficinas de atención"]'::jsonb,1,'Art. 2 RD 208/1996','El art. 2.4 manda utilizar los medios adecuados, favoreciendo los que permiten la información a distancia (publicaciones, teléfono y otras tecnologías).',null),
('aux-canarias:13-c4f89634f5','aux-canarias',13,'¿Quién facilita la información particular según el RD 208/1996?','["La Inspección General de Servicios", "El Centro de Información Administrativa", "Las oficinas de registro de cualquier Administración", "Las unidades de gestión que tramitan los procedimientos"]'::jsonb,3,'Art. 3 RD 208/1996','La información particular la facilitan las unidades de gestión; las oficinas de información pueden conectarse con ellas para responder con rapidez.',null),
('aux-canarias:13-fdffd71e37','aux-canarias',13,'Según el RD 208/1996, el Centro de Información Administrativa tiene nivel orgánico de:','["Subdirección General", "Dirección General", "Servicio", "Secretaría General"]'::jsonb,0,'Art. 6 RD 208/1996','El Centro de Información Administrativa tiene nivel orgánico de Subdirección General.',null),
('aux-canarias:13-91dad2ebdb','aux-canarias',13,'Las oficinas centrales de información de los servicios territoriales de la Administración General del Estado dependen, según el RD 208/1996, de:','["Los ayuntamientos de las capitales de provincia", "Las diputaciones provinciales", "Las consejerías de presidencia de las comunidades autónomas", "Las Delegaciones del Gobierno en las comunidades autónomas"]'::jsonb,3,'Art. 9 RD 208/1996','Las oficinas centrales territoriales se integran en las Delegaciones del Gobierno (y en las antiguas Gobiernos Civiles, hoy Subdelegaciones, y Delegaciones Insulares).',null),
('aux-canarias:13-2a005501b5','aux-canarias',13,'Para crear oficinas integradas de información con participación de varias Administraciones, el RD 208/1996 prevé:','["Un convenio de colaboración entre ellas", "Una ley aprobada por las Cortes Generales", "Una orden del ministerio competente", "Un real decreto del Consejo de Ministros"]'::jsonb,0,'Art. 10 RD 208/1996','El art. 10 permite, mediante convenio de colaboración entre Administraciones, intercambiar información o crear oficinas integradas.',null),
('aux-canarias:14-32a5811ba2','aux-canarias',14,'La información de publicidad activa debe publicarse:','["En las sedes electrónicas o páginas web, de forma clara y estructurada, preferiblemente en formatos reutilizables", "En el boletín oficial correspondiente y, si el organismo dispone de ella, también en su página web, en formato no reutilizable", "En el tablón de anuncios físico de cada organismo y en su sede electrónica, en formato papel", "En la página web, pero solo a petición del interesado y en el formato que este elija, sin obligación de que sean reutilizables ni de actualizarla periódicamente"]'::jsonb,0,'Art. 5.4 Ley 19/2013','Se publica en las sedes electrónicas o páginas web, de manera clara, estructurada y entendible, y preferiblemente en formatos reutilizables.',null),
('aux-canarias:14-0296ad34d5','aux-canarias',14,'El Portal de la Transparencia de la Administración General del Estado depende:','["Del Consejo de Transparencia y Buen Gobierno", "Del Ministerio de la Presidencia", "Del Defensor del Pueblo", "De las Cortes Generales"]'::jsonb,1,'Art. 10.1 Ley 19/2013','El Portal de la Transparencia depende del Ministerio de la Presidencia.',null),
('aux-canarias:14-2b1f4dc1c7','aux-canarias',14,'¿Quién tiene derecho a acceder a la información pública según la Ley 19/2013?','["Los ciudadanos españoles y los extranjeros residentes legalmente en España", "Solo quienes tengan la condición de interesados en un procedimiento administrativo", "Todas las personas, en los términos del art. 105.b) de la Constitución", "Los mayores de edad empadronados en España, en los términos de la Ley 39/2015"]'::jsonb,2,'Art. 12 Ley 19/2013','Todas las personas tienen derecho a acceder a la información pública, en los términos del art. 105.b) de la Constitución.',null),
('aux-canarias:14-08bc6e9789','aux-canarias',14,'Según la Ley 19/2013, se entiende por información pública:','["Los documentos publicados en el BOE y en los boletines autonómicos y provinciales", "Los contenidos o documentos en poder de los sujetos obligados, cualquiera que sea su origen, autor o finalidad, incluidos los privados", "Los documentos que los ciudadanos entregan a la Administración en un procedimiento", "Los contenidos o documentos en poder de los sujetos obligados, elaborados o adquiridos en el ejercicio de sus funciones"]'::jsonb,3,'Art. 13 Ley 19/2013','Son los contenidos o documentos, cualquiera que sea su formato o soporte, en poder de los sujetos obligados, elaborados o adquiridos en el ejercicio de sus funciones.',null),
('aux-canarias:14-9f7300baa0','aux-canarias',14,'Al presentar una solicitud de acceso a la información pública, el solicitante:','["No está obligado a motivarla", "Debe motivarla siempre", "Debe acreditar un interés legítimo", "Debe pagar una tasa previa"]'::jsonb,0,'Art. 17.3 Ley 19/2013','El solicitante no está obligado a motivar su solicitud, aunque puede exponer los motivos.',null),
('aux-canarias:14-7e3638fdfc','aux-canarias',14,'¿En qué plazo debe resolverse una solicitud de acceso a la información pública?','["Diez días desde su recepción por el órgano competente, ampliable por otros diez", "Un mes desde su recepción por el órgano competente, ampliable por otro mes", "Tres meses desde su presentación, ampliable por otros tres", "Quince días hábiles desde su presentación, sin posibilidad de ampliación"]'::jsonb,1,'Art. 20.1 Ley 19/2013','El plazo máximo es de un mes desde la recepción por el órgano competente, ampliable por otro mes por el volumen o la complejidad de la información.',null),
('aux-canarias:14-7156abd1d4','aux-canarias',14,'Si no se resuelve en plazo una solicitud de acceso a la información pública, se entiende:','["Estimada", "Caducada", "Desestimada", "Remitida al Consejo de Transparencia"]'::jsonb,2,'Art. 20.4 Ley 19/2013','Transcurrido el plazo sin resolución expresa, la solicitud se entiende desestimada.',null),
('aux-canarias:14-22ae48b433','aux-canarias',14,'El acceso a la información pública es:','["De pago, conforme a las tasas que fije cada Administración", "Gratuito sin excepción alguna, incluidas la expedición de copias y la transposición a otro formato", "Gratuito para las personas físicas y de pago para las empresas", "Gratuito, sin perjuicio de las exacciones por expedición de copias o cambio de formato"]'::jsonb,3,'Art. 22.4 Ley 19/2013','El acceso es gratuito, aunque pueden exigirse exacciones por la expedición de copias o la transposición a formatos distintos del original.',null),
('aux-canarias:14-727234982f','aux-canarias',14,'La reclamación ante el Consejo de Transparencia y Buen Gobierno:','["Es potestativa y previa a la vía contencioso-administrativa, y se presenta en el plazo de un mes", "Es obligatoria y previa a la vía contencioso-administrativa, y se presenta en el plazo de un mes", "Es potestativa y previa a la vía contencioso-administrativa, y se presenta en el plazo de tres meses", "Sustituye al recurso contencioso-administrativo, y se presenta en el plazo de dos meses"]'::jsonb,0,'Art. 24 Ley 19/2013','Es potestativa y previa a la impugnación en vía contencioso-administrativa. Se presenta en el plazo de un mes.',null),
('aux-canarias:14-036883ebdd','aux-canarias',14,'¿En qué plazo debe resolver el Consejo de Transparencia y Buen Gobierno una reclamación?','["Un mes; transcurrido ese plazo sin resolución, se entiende estimada", "Tres meses; transcurrido ese plazo, se entiende desestimada", "Seis meses; transcurrido ese plazo, se entiende desestimada", "Tres meses; transcurrido ese plazo sin resolución expresa, se entiende estimada"]'::jsonb,1,'Art. 24.4 Ley 19/2013','El plazo máximo es de tres meses. Transcurrido sin resolución, la reclamación se entiende desestimada.',null),
('aux-canarias:14-5cb2b7a099','aux-canarias',14,'El Presidente del Consejo de Transparencia y Buen Gobierno es nombrado por un periodo de:','["Cuatro años renovables", "Seis años", "Cinco años no renovable", "Tres años renovables una vez"]'::jsonb,2,'Art. 37.1 Ley 19/2013','Es nombrado por un período no renovable de cinco años.',null),
('aux-canarias:14-a749d2dd58','aux-canarias',14,'¿Cuál de los siguientes es un límite al derecho de acceso a la información pública?','["Que el solicitante no motive su solicitud ni explique para qué la quiere", "Que la información tenga más de cinco años de antigüedad", "Que la información solo esté disponible en formato papel", "Que el acceso suponga un perjuicio para la seguridad nacional"]'::jsonb,3,'Art. 14.1 Ley 19/2013','Entre los límites están la seguridad nacional, la defensa y las relaciones exteriores, entre otros.',null),
('aux-canarias:14-2b60edbc09','aux-canarias',14,'Según la Ley 19/2013, el Consejo de Transparencia y Buen Gobierno es:','["Un organismo público con personalidad jurídica propia", "Una dirección general del Ministerio de Hacienda", "Un órgano de las Cortes Generales", "Un órgano del Poder Judicial"]'::jsonb,0,'Art. 33 Ley 19/2013','Es un organismo público con personalidad jurídica propia y plena capacidad de obrar.',null),
('aux-canarias:14-43dec96ba5','aux-canarias',14,'Las infracciones muy graves de buen gobierno de la Ley 19/2013 prescriben a los:','["Tres años", "Dos años", "Un año", "Cinco años"]'::jsonb,3,'Art. 32 Ley 19/2013','Las graves a los tres años y las leves al año.',null),
('aux-canarias:14-566b61af20','aux-canarias',14,'Entre la información económica que debe publicarse según el art. 8 de la Ley 19/2013 se encuentran:','["Los datos de salud y las bajas laborales de los empleados públicos de cada departamento", "Las nóminas de todos los funcionarios y del personal laboral, con su nombre y puesto de trabajo", "Las declaraciones del IRPF de los ciudadanos", "Las retribuciones percibidas anualmente por los altos cargos y máximos responsables"]'::jsonb,3,'Art. 8.1 f) Ley 19/2013','También contratos, convenios, subvenciones y presupuestos.',null),
('aux-canarias:14-6f73761c03','aux-canarias',14,'Según la Ley 19/2013, la sanción por infracciones muy graves de buen gobierno incluye:','["Una multa de entre 600 y 6.000 euros y una amonestación pública en el boletín oficial correspondiente", "La destitución y la imposibilidad de ser nombrado alto cargo durante un periodo de entre cinco y diez años", "La suspensión de empleo por un día", "Una amonestación"]'::jsonb,1,'Art. 30 Ley 19/2013','Las infracciones leves se sancionan con amonestación.',null),
('aux-canarias:14-5ed4d5e531','aux-canarias',14,'Según la Ley 19/2013, están obligadas a cumplir las obligaciones de publicidad activa las entidades privadas que perciban durante un año ayudas o subvenciones públicas en una cuantía superior a:','["10.000 euros", "100.000 euros", "50.000 euros", "1.000.000 de euros"]'::jsonb,1,'Art. 3 b) Ley 19/2013','O cuando al menos el 40 % de sus ingresos anuales tengan carácter de ayuda pública, con un mínimo de 5.000 euros.',null),
('aux-canarias:14-a8e21948ce','aux-canarias',14,'El Consejo de Transparencia y Buen Gobierno se estructura en:','["Un Pleno y una Junta de Portavoces de los grupos parlamentarios del Congreso", "Una Sala de lo Contencioso y una Sala de lo Penal", "La Comisión de Transparencia y Buen Gobierno y el Presidente del Consejo", "Un Presidente, un Vicepresidente y una Secretaría General, con un Pleno de doce miembros"]'::jsonb,2,'Art. 35 Ley 19/2013','La Comisión incluye, entre otros, un Diputado y un Senador.',null),
('aux-canarias:14-42f8c76696','aux-canarias',14,'Forman parte de la Comisión de Transparencia y Buen Gobierno, entre otros:','["Un Diputado, un Senador, un representante del Tribunal de Cuentas y uno del Defensor del Pueblo", "Los Presidentes de las Comunidades Autónomas", "Los Alcaldes de capitales de provincia", "Un Diputado, un Senador, un representante del Consejo General del Poder Judicial y uno del Tribunal Supremo"]'::jsonb,0,'Art. 36.2 Ley 19/2013','También representantes de la AEPD, de la Secretaría de Estado de Administraciones Públicas y de la AIReF.',null),
('aux-canarias:14-9184eb51f9','aux-canarias',14,'Si la información solicitada puede afectar a derechos o intereses de terceros, se les concederá para alegaciones un plazo de:','["Cinco días", "Diez días", "Un mes", "Quince días"]'::jsonb,3,'Art. 19.3 Ley 19/2013','El plazo para resolver se suspende hasta recibir las alegaciones o transcurrir el plazo.',null),
('aux-canarias:14-7180ba8685','aux-canarias',14,'Según la Ley 19/2013, se inadmitirán a trámite las solicitudes de acceso:','["Presentadas por personas extranjeras no residentes en España o por quien no acredite un interés legítimo directo", "Que no estén motivadas o en las que el solicitante no acredite un interés directo en la información", "Relativas a información que tenga carácter auxiliar o de apoyo, como notas, borradores u opiniones", "Presentadas por personas jurídicas o por entidades sin personalidad jurídica"]'::jsonb,2,'Art. 18.1 b) Ley 19/2013','También las que requieran reelaboración, las referidas a información en elaboración o las manifiestamente repetitivas o abusivas.',null),
('aux-canarias:14-70adcdf014','aux-canarias',14,'Si el acceso a la información no puede realizarse en el momento de la notificación de la resolución, deberá otorgarse en un plazo no superior a:','["Quince días", "Diez días", "Un mes", "Tres días"]'::jsonb,1,'Art. 22.1 Ley 19/2013','El acceso se realizará preferentemente por vía electrónica.',null),
('aux-canarias:14-d48e95f2e9','aux-canarias',14,'Según el art. 23 de la Ley 19/2013, la reclamación ante el Consejo de Transparencia y Buen Gobierno:','["No tiene efectos", "Es previa y obligatoria al recurso de alzada", "Sustituye a los recursos administrativos", "Es posterior al recurso de reposición"]'::jsonb,2,'Art. 23.1 Ley 19/2013','Tiene la consideración de sustitutiva de los recursos administrativos.',null),
('aux-canarias:14-9572807c35','aux-canarias',14,'¿Qué ley estatal regula la transparencia de la actividad pública y el derecho de acceso a la información?','["La Ley 19/2013, de 9 de diciembre", "La LO 3/2018, de 5 de diciembre", "La Ley 39/2015, de 1 de octubre", "La Ley 37/2007, de 16 de noviembre"]'::jsonb,0,'Ley 19/2013','La Ley 37/2007 regula la reutilización de la información del sector público y la LO 3/2018, la protección de datos.',null),
('aux-canarias:14-026820d73c','aux-canarias',14,'Según el artículo 6 de la Ley 19/2013, los sujetos obligados deben publicar, como información institucional y organizativa:','["Las funciones que desarrollan, la normativa que les sea de aplicación y su estructura organizativa", "Los expedientes de los procedimientos sancionadores que tramiten", "Las retribuciones de todos los empleados públicos, con su nombre y apellidos", "Las actas completas de todas las reuniones de sus órganos colegiados"]'::jsonb,0,'Art. 6.1 Ley 19/2013','Incluyen un organigrama actualizado que identifique a los responsables de los diferentes órganos y su perfil y trayectoria profesional.',null),
('aux-canarias:14-d63e957a8f','aux-canarias',14,'Según el artículo 7 de la Ley 19/2013, ¿qué información de relevancia jurídica debe publicarse?','["Los informes de los servicios jurídicos sobre cualquier asunto en tramitación", "Las denuncias presentadas por los ciudadanos contra las autoridades", "Los anteproyectos de ley y los proyectos de reglamento, entre otros documentos", "Las sentencias firmes dictadas contra la Administración en los últimos cinco años"]'::jsonb,2,'Art. 7 Ley 19/2013','También las directrices, instrucciones y circulares que supongan una interpretación del Derecho o tengan efectos jurídicos y las memorias e informes de los expedientes normativos.',null),
('aux-canarias:14-b067189a4e','aux-canarias',14,'Según la Ley 19/2013, ¿deben publicarse las retribuciones percibidas anualmente por los altos cargos?','["Sí, como información económica, presupuestaria y estadística", "No, porque son datos personales protegidos", "Solo si lo solicita un ciudadano mediante el derecho de acceso", "Las de los Ministros y Secretarios de Estado, pero no las del resto"]'::jsonb,0,'Art. 8.1 f) Ley 19/2013','También se publican las indemnizaciones percibidas con ocasión del abandono del cargo.',null),
('aux-canarias:14-6d055296e7','aux-canarias',14,'¿Cuándo entraron en vigor los títulos preliminar, I y III de la Ley 19/2013 para la Administración General del Estado?','["A los dos años de su publicación en el Boletín Oficial del Estado", "A los seis meses de su publicación en el Boletín Oficial del Estado", "Al año de su publicación en el Boletín Oficial del Estado", "Al día siguiente de su publicación en el Boletín Oficial del Estado"]'::jsonb,2,'Disposición final novena Ley 19/2013','El título II (buen gobierno) entró en vigor al día siguiente de su publicación. Las CCAA y Entidades Locales tuvieron dos años para adaptarse.',null),
('aux-canarias:14-22431bd1dc','aux-canarias',14,'El título II de la Ley 19/2013 regula:','["El buen gobierno", "La publicidad activa", "El derecho de acceso a la información pública", "El Consejo de Transparencia y Buen Gobierno"]'::jsonb,0,'Ley 19/2013','El título I regula la transparencia (publicidad activa y derecho de acceso) y el título III el Consejo de Transparencia y Buen Gobierno.',null),
('aux-canarias:14-d9328d014f','aux-canarias',14,'Cuando un límite al derecho de acceso no afecte a la totalidad de la información solicitada:','["Se deniega el acceso a la totalidad de la información, aunque el límite afecte solo a una parte de ella, para evitar que se conozca el resto", "Se remite la solicitud al Consejo de Transparencia y Buen Gobierno", "Se suspende el procedimiento hasta que el límite deje de aplicarse y se notifica esta circunstancia al solicitante y a los terceros afectados", "Se concede el acceso parcial, omitiendo la información afectada por el límite, salvo que resulte una información distorsionada o sin sentido"]'::jsonb,3,'Art. 16 Ley 19/2013','Debe indicarse al solicitante qué parte de la información ha sido omitida.',null),
('aux-canarias:14-7e76ccf793','aux-canarias',14,'Según la Ley 19/2013, la solicitud de acceso que se refiera a información cuya divulgación requiera una acción previa de reelaboración:','["Se inadmitirá a trámite mediante resolución motivada", "Se remitirá al órgano que elaboró la información originalmente", "Se tramitará con un plazo ampliado de tres meses", "Se estimará, pero el solicitante deberá abonar el coste de la reelaboración"]'::jsonb,0,'Art. 18.1 c) Ley 19/2013','Es una de las causas de inadmisión, junto con la información en curso de elaboración o de carácter auxiliar, entre otras.',null),
('aux-canarias:14-c357dfc528','aux-canarias',14,'Si la solicitud de acceso se refiere a información que no obre en poder del sujeto al que se dirige:','["Este la archivará y el solicitante deberá presentar una nueva solicitud ante el órgano que corresponda", "Este deberá recabar la información del órgano que la posea y resolver la solicitud en el plazo ordinario", "Este la remitirá al competente, si lo conoce, e informará de esta circunstancia al solicitante", "Este la inadmitirá a trámite, aunque conozca cuál es el órgano o entidad competente para resolver"]'::jsonb,2,'Art. 19.1 Ley 19/2013','Si desconoce el órgano competente, procede la inadmisión.',null),
('aux-canarias:14-471506dc8a','aux-canarias',14,'El plazo para resolver una solicitud de acceso a la información puede ampliarse:','["Por tres meses más, sin necesidad de comunicarlo previamente al solicitante, cuando así lo acuerde el titular del órgano que debe resolver", "No puede ampliarse, porque es un plazo improrrogable", "Por otro mes, en el caso de que el volumen o la complejidad de la información lo hagan necesario, previa notificación al solicitante", "Por quince días hábiles, solo si hay terceros afectados"]'::jsonb,2,'Art. 20.1 Ley 19/2013','El plazo ordinario es de un mes desde la recepción de la solicitud por el órgano competente.',null),
('aux-canarias:14-4a51c7a92a','aux-canarias',14,'Según la Ley 19/2013, ¿qué resoluciones sobre el derecho de acceso deben ser motivadas?','["Las que denieguen totalmente el acceso a la información", "Todas las resoluciones, tanto si conceden como si deniegan el acceso", "Las que denieguen el acceso, las que concedan el acceso parcial o a través de una modalidad distinta a la solicitada y las que permitan el acceso con oposición de un tercero", "Las que concedan el acceso, porque afectan a la confidencialidad de la información"]'::jsonb,2,'Art. 20.2 Ley 19/2013','Así lo exige el artículo 20.2.',null),
('aux-canarias:14-5530fdd4fa','aux-canarias',14,'El acceso a la información pública, según la Ley 19/2013:','["Es gratuito, aunque la expedición de copias o la transposición a formatos diferentes del original puede dar lugar a exacciones", "Es gratuito solo para los ciudadanos españoles residentes en España", "Está sujeto al pago de una tasa por cada solicitud presentada, cuya cuantía fija cada año la Ley de Presupuestos Generales del Estado", "Es gratuito, incluida también la expedición de copias en papel o en soporte electrónico y la transposición a otros formatos"]'::jsonb,0,'Art. 22.4 Ley 19/2013','La forma preferente de acceso es la electrónica.',null),
('aux-canarias:14-871a129bec','aux-canarias',14,'¿Qué unidades deben existir en la Administración General del Estado para facilitar el conocimiento y acceso a la información pública?','["Delegaciones de protección de datos", "Unidades de información", "Oficinas de asistencia en materia de registros", "Inspecciones generales de servicios"]'::jsonb,1,'Art. 21 Ley 19/2013','Se encargan, entre otras funciones, de recabar y difundir la información de publicidad activa y de recibir y tramitar las solicitudes de acceso.',null),
('aux-canarias:14-f4e3e784f6','aux-canarias',14,'Según la Ley 19/2013, la información de publicidad activa se publicará:','["De forma periódica y actualizada, en las sedes electrónicas o páginas web, de una manera clara, estructurada y entendible y preferiblemente en formatos reutilizables", "Cuando lo solicite cualquier ciudadano por escrito", "Una vez al año, en el Boletín Oficial del Estado y en los diarios oficiales de las Comunidades Autónomas, en un anexo específico que recoja toda la información obligatoria", "En el tablón de anuncios físico de cada órgano"]'::jsonb,0,'Arts. 5.1 y 5.4 Ley 19/2013','Se establecen los mecanismos adecuados para facilitar la accesibilidad, la interoperabilidad y la calidad de la información.',null),
('aux-canarias:14-fe775bee9b','aux-canarias',14,'Según el artículo 26 de la Ley 19/2013, ¿cuál de los siguientes es un principio general de actuación de los altos cargos?','["Mantener en secreto todas sus reuniones con grupos de interés", "Actuar con transparencia en la gestión de los asuntos públicos", "Afiliarse obligatoriamente a un partido político", "Percibir una retribución acorde con la de su sector privado de origen"]'::jsonb,1,'Art. 26.2 a) Ley 19/2013','Otros principios son la dedicación al servicio público, la imparcialidad, la igualdad de trato y la diligencia.',null),
('aux-canarias:15-60fe65de09','aux-canarias',15,'La LO 3/2018 de Protección de Datos tiene por objeto:','["Sustituir al Reglamento (UE) 2016/679 y regular los derechos digitales", "Adaptar el ordenamiento español al Reglamento (UE) 2016/679 y garantizar los derechos digitales", "Trasponer la Directiva 95/46/CE y regular la videovigilancia", "Adaptar el ordenamiento al Reglamento (UE) 2016/679, pero sin regular los llamados derechos digitales"]'::jsonb,1,'Art. 1 LO 3/2018','Adapta el ordenamiento al Reglamento (UE) 2016/679 y garantiza los derechos digitales conforme al art. 18.4 de la Constitución.',null),
('aux-canarias:15-9f12594032','aux-canarias',15,'El deber de confidencialidad de quienes intervienen en el tratamiento de datos:','["Termina al finalizar la relación con el responsable", "Dura un año tras finalizar la relación", "Se mantiene aun cuando haya finalizado la relación", "Solo afecta al responsable del tratamiento"]'::jsonb,2,'Art. 5 LO 3/2018','Afecta a responsables, encargados y demás intervinientes, y se mantiene aun cuando haya finalizado la relación.',null),
('aux-canarias:15-132d01abab','aux-canarias',15,'¿Cómo define la LO 3/2018 el consentimiento del afectado?','["Toda manifestación de voluntad libre, informada e inequívoca, aunque sea tácita o derive del silencio", "Toda manifestación de voluntad expresa y por escrito, firmada en papel o electrónicamente", "La aceptación tácita de las condiciones, siempre que se haya informado previamente", "Toda manifestación de voluntad libre, específica, informada e inequívoca"]'::jsonb,3,'Art. 6.1 LO 3/2018','Es toda manifestación de voluntad libre, específica, informada e inequívoca, mediante una declaración o una clara acción afirmativa.',null),
('aux-canarias:15-147ae3b86e','aux-canarias',15,'El tratamiento de los datos de un menor puede basarse en su propio consentimiento cuando sea mayor de:','["Catorce años", "Dieciséis años", "Doce años", "Dieciocho años"]'::jsonb,0,'Art. 7.1 LO 3/2018','Solo cuando sea mayor de catorce años, salvo que la ley exija la asistencia de los titulares de la patria potestad o tutela.',null),
('aux-canarias:15-cbbdb206bc','aux-canarias',15,'¿Basta el consentimiento del afectado para tratar datos cuya finalidad principal sea identificar su ideología o religión?','["Sí, siempre", "No, el solo consentimiento no basta para levantar la prohibición", "Sí, si es por escrito", "Solo si lo autoriza la Agencia Española de Protección de Datos"]'::jsonb,1,'Art. 9.1 LO 3/2018','El solo consentimiento no basta para tratar datos cuya finalidad principal sea identificar ideología, afiliación sindical, religión, orientación sexual, creencias u origen racial o étnico.',null),
('aux-canarias:15-2e3b62a5b1','aux-canarias',15,'Los artículos 13 a 18 de la LO 3/2018 regulan los derechos de:','["Petición, queja, sugerencia, acceso a archivos y registros públicos, y reclamación ante la Agencia", "Acceso a la información pública, rectificación, reclamación y oposición", "Acceso, rectificación, supresión, limitación del tratamiento, portabilidad y oposición", "Rectificación, réplica, supresión y olvido en medios de comunicación"]'::jsonb,2,'Arts. 13 a 18 LO 3/2018','Regulan, en este orden, los derechos de acceso, rectificación, supresión, limitación del tratamiento, portabilidad y oposición.',null),
('aux-canarias:15-caa6d790f2','aux-canarias',15,'¿Cuándo deben designar un delegado de protección de datos los responsables y encargados del tratamiento?','["Solo cuando tengan más de 250 empleados o traten datos de más de 10.000 personas", "En ningún caso es obligatorio, aunque la ley recomienda su designación a las entidades públicas", "Solo cuando lo requiera expresamente la Agencia Española de Protección de Datos", "En los supuestos del art. 37.1 del Reglamento (UE) 2016/679 y en las entidades que enumera la ley"]'::jsonb,3,'Art. 34.1 LO 3/2018','Deben designarlo en los supuestos del art. 37.1 del Reglamento europeo y, en todo caso, en las entidades que enumera el propio artículo.',null),
('aux-canarias:15-40f63e581a','aux-canarias',15,'La Agencia Española de Protección de Datos es:','["Una autoridad administrativa independiente de ámbito estatal", "Una dirección general adscrita al Ministerio del Interior, sin personalidad jurídica", "Un órgano adscrito al Consejo General del Poder Judicial", "Una agencia de la Unión Europea con sede en España"]'::jsonb,0,'Art. 44.1 LO 3/2018','Es una autoridad administrativa independiente de ámbito estatal.',null),
('aux-canarias:15-5fbf3d0931','aux-canarias',15,'El mandato de la Presidencia de la Agencia Española de Protección de Datos es de:','["Cuatro años, no renovable", "Cinco años, renovable por otro periodo de igual duración", "Seis años, no renovable, contados desde su toma de posesión", "Cuatro años, renovable por otro periodo de igual duración"]'::jsonb,1,'Art. 48.5 LO 3/2018','El mandato es de cinco años y puede renovarse por otro periodo de igual duración.',null),
('aux-canarias:15-b43c8ab844','aux-canarias',15,'¿Cuándo prescriben las infracciones leves en materia de protección de datos?','["A los seis meses", "A los dos años", "Al año", "A los tres años"]'::jsonb,2,'Art. 74 LO 3/2018','Las infracciones muy graves prescriben a los tres años (art. 72), las graves a los dos años (art. 73) y las leves al año (art. 74).',null),
('aux-canarias:15-212ff18573','aux-canarias',15,'Las sanciones de protección de datos de importe superior a 300.000 euros prescriben a:','["Al año", "Los dos años", "Los seis meses", "Los tres años"]'::jsonb,3,'Art. 78.1 LO 3/2018','Hasta 40.000 € prescriben al año; entre 40.001 y 300.000 €, a los dos años; y las superiores a 300.000 €, a los tres años.',null),
('aux-canarias:15-b43e7b614d','aux-canarias',15,'¿Se aplica el régimen sancionador de la LO 3/2018 al delegado de protección de datos?','["No", "Sí, en todo caso", "Solo por infracciones muy graves", "Solo si es personal laboral"]'::jsonb,0,'Art. 70.2 LO 3/2018','El régimen sancionador de la ley no es de aplicación al delegado de protección de datos.',null),
('aux-canarias:15-eeab76985c','aux-canarias',15,'Los herederos de una persona fallecida, ¿pueden solicitar el acceso, la rectificación o la supresión de sus datos?','["No, salvo que el fallecido lo hubiese autorizado expresamente en vida", "Sí, salvo que el fallecido lo hubiese prohibido expresamente o lo establezca una ley", "Sí, pero solo con autorización judicial y acreditando un interés legítimo", "Sí, durante el primer año tras el fallecimiento, salvo prohibición expresa del fallecido"]'::jsonb,1,'Art. 3.1 LO 3/2018','Pueden hacerlo las personas vinculadas al fallecido por razones familiares o de hecho y sus herederos, salvo prohibición expresa del fallecido o de una ley.',null),
('aux-canarias:15-610f97318e','aux-canarias',15,'El derecho al olvido en búsquedas de Internet permite pedir a los motores de búsqueda:','["Que eliminen de los resultados de una búsqueda por el nombre los enlaces a información inadecuada, inexacta, no pertinente, no actualizada o excesiva", "Que paguen una indemnización automática", "Que borren la página web original en todo caso, junto con todas sus copias y enlaces, aunque la información sea exacta, pertinente y actualizada y su difusión sea lícita", "Que cierren la cuenta del usuario"]'::jsonb,0,'Art. 93.1 LO 3/2018','Es el derecho al olvido frente a buscadores.',null),
('aux-canarias:15-0a7b2cc125','aux-canarias',15,'El acceso a los contenidos gestionados por prestadores de servicios digitales de personas fallecidas se regula en la LO 3/2018 como:','["Testamento digital", "Herencia yacente", "Derecho de rectificación", "Derecho de portabilidad"]'::jsonb,0,'Art. 96 LO 3/2018','Salvo que el fallecido lo hubiese prohibido expresamente.',null),
('aux-canarias:15-e8ac1fa4cb','aux-canarias',15,'En ningún caso se admitirá la instalación de sistemas de grabación de sonidos o videovigilancia en:','["Las entradas de los edificios", "Los aparcamientos", "Lugares destinados al descanso o esparcimiento de los trabajadores, como vestuarios, aseos o comedores", "Las zonas de caja y de atención al público, aunque se informe previamente a los trabajadores"]'::jsonb,2,'Art. 89.2 LO 3/2018','Protección de la intimidad en el trabajo.',null),
('aux-canarias:15-2932e50702','aux-canarias',15,'En los sistemas de información crediticia, los datos solo pueden mantenerse mientras persista el incumplimiento, con el límite máximo de:','["Cinco años desde la fecha de vencimiento de la obligación", "Diez años", "Un año", "Seis años desde la fecha de inclusión en el sistema"]'::jsonb,0,'Art. 20.1 d) LO 3/2018','Límite temporal de los ficheros de morosos.',null),
('aux-canarias:15-ad40b0420e','aux-canarias',15,'Quienes pretendan realizar comunicaciones de mercadotecnia directa deben consultar previamente:','["El censo electoral", "El Registro Civil", "El padrón municipal de habitantes y el censo de empresas", "Los sistemas de exclusión publicitaria"]'::jsonb,3,'Art. 23.4 LO 3/2018','Salvo que el afectado haya prestado su consentimiento a recibirlas.',null),
('aux-canarias:15-2e99b68be2','aux-canarias',15,'El tratamiento de los datos de un menor de catorce años fundado en el consentimiento solo es lícito si consta:','["El consentimiento del propio menor, si tiene madurez suficiente", "El consentimiento del titular de la patria potestad o tutela", "El consentimiento del centro escolar", "Una autorización judicial en todo caso"]'::jsonb,1,'Art. 7.2 LO 3/2018','A partir de los 14 años el menor puede consentir por sí mismo.',null),
('aux-canarias:15-5ec8990bc1','aux-canarias',15,'La prueba del cumplimiento del deber de responder a la solicitud de ejercicio de derechos corresponde a:','["El encargado del tratamiento", "La AEPD", "El responsable del tratamiento", "El afectado"]'::jsonb,2,'Art. 12.4 LO 3/2018','La carga de la prueba recae en el responsable.',null),
('aux-canarias:15-06bedcbb73','aux-canarias',15,'El procedimiento sancionador en materia de protección de datos tendrá una duración máxima de:','["Doce meses desde la fecha del acuerdo de inicio", "Dos años desde la fecha de la reclamación del interesado", "Seis meses desde la fecha de presentación de la denuncia", "Tres meses"]'::jsonb,0,'Art. 64.2 LO 3/2018','Así lo establece el art. 64.2.',null),
('aux-canarias:15-4a227edf56','aux-canarias',15,'El plazo para resolver el procedimiento cuando se reclama exclusivamente la falta de atención de una solicitud de ejercicio de derechos es de:','["Un mes", "Doce meses", "Tres meses", "Seis meses"]'::jsonb,3,'Art. 64.1 LO 3/2018','El procedimiento sancionador tiene una duración máxima de doce meses (art. 64.2).',null),
('aux-canarias:15-db5e86f90a','aux-canarias',15,'Las imágenes captadas por sistemas de videovigilancia deben suprimirse, con carácter general, en el plazo máximo de:','["Una semana desde su captación", "Un mes desde su captación", "Tres meses desde su captación", "Un año desde su captación"]'::jsonb,1,'Art. 22.3 LO 3/2018','Salvo que deban conservarse para acreditar actos contra personas, bienes o instalaciones.',null),
('aux-canarias:15-f263f49957','aux-canarias',15,'Según el art. 2.2 de la LO 3/2018, la ley NO se aplica, sin perjuicio de su art. 3, a:','["Los tratamientos de las Administraciones Públicas", "Los datos de menores", "Los tratamientos de datos de personas fallecidas", "Los datos de salud"]'::jsonb,2,'Art. 2.2 LO 3/2018','También quedan excluidos los tratamientos fuera del RGPD y las materias clasificadas.',null),
('aux-canarias:15-f054c15edb','aux-canarias',15,'La Presidencia y el Adjunto de la AEPD son nombrados:','["Por elección directa de los ciudadanos entre los candidatos propuestos por el Congreso, el Senado y el Consejo General del Poder Judicial, por cinco años", "Por el Consejo de Ministros mediante real decreto, a propuesta del Gobierno y tras su ratificación por la Comisión de Justicia del Congreso", "Por el Consejo General del Poder Judicial", "Por el Rey a propuesta del Senado, por mayoría de tres quintos, tras una comparecencia pública ante la Comisión Constitucional y previo informe favorable del Consejo de Estado"]'::jsonb,1,'Art. 48.3 LO 3/2018','El mandato es de cinco años renovable.',null),
('aux-canarias:15-2e11897d45','aux-canarias',15,'Las actuaciones del responsable para atender las solicitudes de ejercicio de derechos serán, con carácter general:','["De pago obligatorio", "Gratuitas solo para menores", "Sujetas a tasa estatal", "Gratuitas"]'::jsonb,3,'Art. 12.7 LO 3/2018','Sin perjuicio de lo dispuesto en el RGPD para solicitudes infundadas o excesivas.',null),
('aux-canarias:15-908a0a9bf7','aux-canarias',15,'Las infracciones graves en materia de protección de datos prescriben a los:','["Seis meses", "Tres años", "Dos años", "Un año"]'::jsonb,2,'Art. 73 LO 3/2018','Las muy graves a los tres años.',null),
('aux-canarias:15-84c707ffc9','aux-canarias',15,'Según el art. 81 de la LO 3/2018:','["Solo los mayores de edad pueden acceder a Internet", "Todos tienen derecho a acceder a Internet independientemente de su condición personal, social, económica o geográfica", "El acceso a Internet depende de autorización administrativa", "Todos tienen derecho a acceder a Internet, salvo las limitaciones que establezca cada prestador por razones económicas o geográficas"]'::jsonb,1,'Art. 81.1 LO 3/2018','Derecho de acceso universal a Internet.',null),
('aux-canarias:15-c989cd8f9a','aux-canarias',15,'Las infracciones muy graves en materia de protección de datos prescriben a los:','["Un año", "Tres años", "Dos años", "Cinco años"]'::jsonb,1,'Art. 72.1 LO 3/2018','Las graves a los dos años y las leves al año.',null),
('aux-canarias:15-dd0d8e1811','aux-canarias',15,'Los responsables y encargados deben comunicar a la AEPD o autoridad autonómica las designaciones, nombramientos y ceses de los delegados de protección de datos en el plazo de:','["Un mes", "Tres días", "Diez días", "Quince días"]'::jsonb,2,'Art. 34.3 LO 3/2018','Plazo de diez días.',null),
('aux-canarias:15-6f5c896bf7','aux-canarias',15,'El derecho a la desconexión digital garantiza a los trabajadores y empleados públicos:','["El uso libre de redes sociales en el trabajo", "Que puedan desconectar los dispositivos de la oficina durante la jornada laboral cuando lo consideren necesario para concentrarse en sus tareas", "Que no se use el correo electrónico en la empresa", "El respeto de su tiempo de descanso, permisos y vacaciones fuera del tiempo de trabajo legal o convencionalmente establecido"]'::jsonb,3,'Art. 88.1 LO 3/2018','El empleador debe elaborar una política interna, previa audiencia de los representantes.',null),
('aux-canarias:15-20e26061c7','aux-canarias',15,'El ejercicio del derecho de acceso más de una vez durante el plazo de ___ podrá considerarse repetitivo, salvo causa legítima:','["Seis meses", "Tres meses", "Un año", "Un mes"]'::jsonb,0,'Art. 13.3 LO 3/2018','Así lo dispone el art. 13.3.',null),
('aux-canarias:15-97ec0cf29d','aux-canarias',15,'Transcurrido el plazo de prescripción de las posibles responsabilidades, los datos bloqueados deberán ser:','["Destruidos", "Transferidos a la AEPD", "Publicados", "Conservados indefinidamente"]'::jsonb,0,'Art. 32.2 LO 3/2018','El bloqueo es temporal hasta la prescripción.',null),
('aux-canarias:15-88ae4c7109','aux-canarias',15,'Si el afectado presenta una reclamación previa ante el delegado de protección de datos, este deberá comunicar su decisión en el plazo máximo de:','["Un mes", "Diez días", "Seis meses", "Dos meses"]'::jsonb,3,'Art. 37.1 LO 3/2018','Si la AEPD remite la reclamación al delegado, este responde en un mes (art. 37.2).',null),
('aux-canarias:16-f47cd59342','aux-canarias',16,'Según la Ley 40/2015, ¿qué carácter tiene la competencia de los órganos administrativos?','["Delegable en todo caso", "Renunciable con autorización del superior", "Transferible a otras Administraciones por convenio", "Irrenunciable"]'::jsonb,3,'Art. 8.1 Ley 40/2015','La competencia es irrenunciable y se ejerce por los órganos que la tengan atribuida como propia, salvo delegación o avocación.',null),
('aux-canarias:16-d44978bba0','aux-canarias',16,'¿Cuál de estas técnicas sí altera la titularidad de la competencia?','["La desconcentración", "La delegación de competencias", "La delegación de firma", "La encomienda de gestión"]'::jsonb,0,'Art. 8 Ley 40/2015','La delegación, la encomienda, la delegación de firma y la suplencia no alteran la titularidad; la desconcentración transfiere titularidad y ejercicio a órganos dependientes.',null),
('aux-canarias:16-16e34fe36b','aux-canarias',16,'Si una norma atribuye una competencia a una Administración sin especificar el órgano, ¿a quién corresponde instruir y resolver?','["Al órgano superior de esa Administración por razón de la materia, en todo caso y sin excepción", "A los órganos inferiores competentes por razón de la materia y del territorio", "Al órgano que designe en cada caso el titular del departamento ministerial correspondiente", "Al órgano que primero conozca del asunto"]'::jsonb,1,'Art. 8.3 Ley 40/2015','Corresponde a los órganos inferiores competentes por materia y territorio; si hay varios, a su superior jerárquico común.',null),
('aux-canarias:16-9ed25a2ebd','aux-canarias',16,'¿Puede delegarse la competencia para adoptar disposiciones de carácter general?','["Sí, en órganos dependientes jerárquicamente", "Sí, si lo autoriza el superior jerárquico", "Solo en el ámbito de la Administración local", "No, en ningún caso"]'::jsonb,3,'Art. 9.2 b) Ley 40/2015','No pueden delegarse las competencias relativas a la adopción de disposiciones de carácter general.',null),
('aux-canarias:16-f8c4059be6','aux-canarias',16,'¿Puede delegarse la resolución de recursos en el mismo órgano que dictó el acto recurrido?','["Sí, si el recurso es de reposición", "Sí, con publicación en el boletín oficial", "No, está expresamente prohibido", "Solo si lo prevé el reglamento orgánico"]'::jsonb,2,'Art. 9.2 c) Ley 40/2015','No pueden delegarse las competencias relativas a la resolución de recursos en los órganos que hayan dictado los actos recurridos.',null)
insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('aux-canarias:16-2ed20d492e','aux-canarias',16,'¿Dónde deben publicarse las delegaciones de competencias de un órgano de la Comunidad Autónoma de Canarias?','["No necesitan publicación", "En el Boletín Oficial del Estado", "En el Boletín Oficial de Canarias", "En el tablón de anuncios del órgano"]'::jsonb,2,'Art. 9.3 Ley 40/2015','Las delegaciones y su revocación se publican en el boletín de la Administración a que pertenezca el órgano delegante: para Canarias, el BOC.',null),
('aux-canarias:16-e999be6899','aux-canarias',16,'¿A qué órgano se consideran dictadas las resoluciones adoptadas por delegación?','["A ambos de forma solidaria", "Al órgano delegado", "Al superior jerárquico común", "Al órgano delegante"]'::jsonb,3,'Art. 9.4 Ley 40/2015','Las resoluciones adoptadas por delegación indicarán esta circunstancia y se considerarán dictadas por el órgano delegante.',null),
('aux-canarias:16-c2337cb4c8','aux-canarias',16,'¿Pueden delegarse las competencias que se ejercen por delegación?','["No, salvo autorización expresa de una ley", "No, en ningún caso, ni siquiera por ley", "Sí, con consentimiento del delegante", "Sí, siempre que se publique"]'::jsonb,0,'Art. 9.5 Ley 40/2015','Salvo autorización expresa de una ley, no podrán delegarse las competencias que se ejerzan por delegación.',null),
('aux-canarias:16-c773bbca8b','aux-canarias',16,'¿Cuándo puede revocarse una delegación de competencias?','["Previa audiencia del órgano delegado", "En cualquier momento, por el órgano que la confirió", "Solo al finalizar el plazo fijado", "Solo por el superior jerárquico del delegante"]'::jsonb,1,'Art. 9.6 Ley 40/2015','La delegación es revocable en cualquier momento por el órgano que la haya conferido.',null),
('aux-canarias:16-dd5e8713bf','aux-canarias',16,'¿Cabe recurso contra el acuerdo de avocación?','["Sí, recurso de alzada ante el superior jerárquico del órgano que haya acordado la avocación", "Solo recurso contencioso-administrativo directo", "No, aunque puede impugnarse en el recurso contra la resolución del procedimiento", "Sí, recurso potestativo de reposición"]'::jsonb,2,'Art. 10.2 Ley 40/2015','Contra el acuerdo de avocación no cabe recurso, aunque puede impugnarse en el que se interponga contra la resolución final.',null),
('aux-canarias:16-7ffc2de04e','aux-canarias',16,'¿Qué requisito formal debe cumplir la avocación?','["Publicación en el boletín oficial correspondiente antes de que surta efecto la avocación", "Acuerdo motivado notificado a los interesados antes o a la vez que la resolución final", "Informe previo del órgano delegado", "Autorización del órgano colegiado superior"]'::jsonb,1,'Art. 10.2 Ley 40/2015','La avocación se realiza mediante acuerdo motivado notificado a los interesados con anterioridad o simultáneamente a la resolución final.',null),
('aux-canarias:16-f720a5f3fb','aux-canarias',16,'En una delegación en órganos no dependientes jerárquicamente, ¿quién puede avocar un asunto?','["Cualquier órgano superior", "El órgano delegado, devolviéndolo", "El superior jerárquico del órgano delegado", "Únicamente el órgano delegante"]'::jsonb,3,'Art. 10.1 Ley 40/2015','En la delegación en órganos no dependientes jerárquicamente, solo puede avocar el órgano delegante.',null),
('aux-canarias:16-5112b15dd4','aux-canarias',16,'¿Qué puede ser objeto de encomienda de gestión?','["Actividades de carácter material o técnico", "La adopción de disposiciones generales", "La resolución de procedimientos", "Prestaciones propias de los contratos del sector público"]'::jsonb,0,'Art. 11.1 Ley 40/2015','Se encomienda la realización de actividades de carácter material o técnico; no puede tener por objeto prestaciones propias de los contratos.',null),
('aux-canarias:16-65d8fb8381','aux-canarias',16,'En una encomienda de gestión, ¿qué condición tiene el órgano encomendado respecto de los datos personales?','["Corresponsable del tratamiento", "Encargado del tratamiento", "Responsable del tratamiento", "Delegado de protección de datos"]'::jsonb,1,'Art. 11.2 Ley 40/2015','El órgano o entidad encomendado tiene la condición de encargado del tratamiento de los datos personales.',null),
('aux-canarias:16-238695f7f2','aux-canarias',16,'¿Cómo se formaliza una encomienda de gestión entre órganos de distintas Administraciones?','["Por resolución del órgano encomendado", "Por acuerdo verbal de los titulares", "Mediante convenio publicado en el boletín oficial correspondiente", "Mediante contrato administrativo de servicios adjudicado sin publicidad"]'::jsonb,2,'Art. 11.3 b) Ley 40/2015','Entre distintas Administraciones se formaliza mediante convenio, que debe publicarse en el boletín correspondiente.',null),
('aux-canarias:16-1008428310','aux-canarias',16,'¿Necesita publicación la delegación de firma para su validez?','["Sí, en el boletín oficial correspondiente", "Solo si afecta a resoluciones sancionadoras", "Sí, en el tablón de edictos", "No"]'::jsonb,3,'Art. 12.2 Ley 40/2015','La delegación de firma no altera la competencia del delegante y para su validez no es necesaria su publicación.',null),
('aux-canarias:16-3530b254bf','aux-canarias',16,'¿En quién puede delegarse la firma de resoluciones y actos?','["En los titulares de órganos o unidades que dependan del delegante", "En cualquier funcionario de la Administración", "En órganos de otras Administraciones", "Solo en el superior jerárquico"]'::jsonb,0,'Art. 12.1 Ley 40/2015','La firma puede delegarse en los titulares de los órganos o unidades administrativas que dependan del delegante.',null),
('aux-canarias:16-4018630311','aux-canarias',16,'Si no se designa suplente para un órgano vacante, ¿quién ejerce su competencia?','["Nadie hasta el nombramiento del nuevo titular", "Quien designe el órgano inmediato superior", "El órgano delegado más reciente", "El funcionario de mayor antigüedad del órgano"]'::jsonb,1,'Art. 13.1 Ley 40/2015','Si no se designa suplente, la competencia se ejerce por quien designe el órgano administrativo inmediato superior.',null),
('aux-canarias:16-24e9f626fe','aux-canarias',16,'¿Entre qué órganos pueden suscitarse conflictos de atribuciones según la Ley 40/2015?','["Entre órganos de una misma Administración no relacionados jerárquicamente", "Entre órganos de distintas Administraciones", "Entre un órgano y su superior jerárquico, cuando discrepen sobre la competencia para resolver", "Entre cualquier órgano y otro de la misma o distinta Administración, una vez finalizado el procedimiento"]'::jsonb,0,'Art. 14.3 Ley 40/2015','Los conflictos de atribuciones solo pueden suscitarse entre órganos de una misma Administración no relacionados jerárquicamente y en procedimientos no finalizados.',null),
('aux-canarias:16-5a3e867cbc','aux-canarias',16,'¿Qué debe hacer el órgano que se estime incompetente para resolver un asunto?','["Solicitar informe al Consejo Consultivo", "Archivar el expediente y notificar a los interesados que deben presentar nueva solicitud ante otro órgano", "Remitir directamente las actuaciones al competente y notificarlo a los interesados", "Devolver la solicitud al interesado para que la presente ante el órgano que considere competente"]'::jsonb,2,'Art. 14.1 Ley 40/2015','Remitirá directamente las actuaciones al órgano que considere competente, notificándolo a los interesados.',null),
('aux-canarias:17-8483d7146b','aux-canarias',17,'Según el art. 8.2 del TREBEP, los empleados públicos se clasifican en:','["Funcionarios de carrera, funcionarios interinos, personal laboral y personal eventual", "Funcionarios de carrera, funcionarios interinos, personal laboral, personal eventual y personal directivo profesional", "Funcionarios de carrera, personal laboral, personal eventual y personal directivo", "Funcionarios de carrera, funcionarios interinos y personal laboral fijo o temporal"]'::jsonb,0,'Art. 8.2 TREBEP','Se clasifican en funcionarios de carrera, funcionarios interinos, personal laboral (fijo, por tiempo indefinido o temporal) y personal eventual.',null),
('aux-canarias:17-d14b60bc80','aux-canarias',17,'Las funciones que implican participación directa o indirecta en el ejercicio de potestades públicas corresponden:','["A cualquier empleado público, sea funcionario o laboral", "Exclusivamente a los funcionarios públicos", "Al personal laboral fijo y a los funcionarios de carrera, en los términos que establezca la ley de cada Administración", "Exclusivamente a los funcionarios de carrera, nunca a los interinos"]'::jsonb,1,'Art. 9.2 TREBEP','Corresponden exclusivamente a los funcionarios públicos, en los términos que establezca la ley de desarrollo de cada Administración.',null),
('aux-canarias:17-651924a21c','aux-canarias',17,'Un funcionario interino nombrado para cubrir una plaza vacante puede ocuparla como máximo:','["Un año", "Dos años", "Tres años", "Cinco años"]'::jsonb,2,'Art. 10.1 a) TREBEP','Las plazas vacantes pueden cubrirse por interinos cuando no sea posible su cobertura por funcionarios de carrera, por un máximo de tres años.',null),
('aux-canarias:17-91a625d01a','aux-canarias',17,'El nombramiento de interinos por exceso o acumulación de tareas tiene un plazo máximo de:','["Seis meses dentro de un periodo de doce", "Doce meses dentro de un periodo de veinticuatro", "Tres años", "Nueve meses dentro de un periodo de dieciocho"]'::jsonb,3,'Art. 10.1 d) TREBEP','El plazo máximo es de nueve meses dentro de un periodo de dieciocho meses.',null),
('aux-canarias:17-e6e592e86c','aux-canarias',17,'El nombramiento de interinos para ejecutar programas de carácter temporal no puede superar:','["Tres años, ampliable hasta doce meses más por las leyes de Función Pública", "Dos años, ampliable hasta seis meses más por las leyes de Función Pública que se dicten en desarrollo del Estatuto", "Tres años, sin posibilidad de ampliación", "Cuatro años, ampliable hasta doce meses más por las leyes de Función Pública"]'::jsonb,0,'Art. 10.1 c) TREBEP','No puede ser superior a tres años, ampliable hasta doce meses más por las leyes de Función Pública de cada Administración.',null),
('aux-canarias:17-4fffc9f0a4','aux-canarias',17,'El personal eventual realiza funciones:','["De carácter técnico permanente, previstas en la relación de puestos de trabajo de cada Administración", "Expresamente calificadas como de confianza o asesoramiento especial", "De inspección y control, expresamente calificadas como tales", "De confianza, pero que implican el ejercicio de potestades públicas"]'::jsonb,1,'Art. 12.1 TREBEP','El personal eventual solo realiza funciones expresamente calificadas como de confianza o asesoramiento especial.',null),
('aux-canarias:17-509e2c9038','aux-canarias',17,'Haber sido personal eventual, ¿puede constituir mérito para el acceso a la función pública?','["Sí, siempre", "Sí, si se prestaron servicios más de un año", "No", "Solo en la promoción interna"]'::jsonb,2,'Art. 12.4 TREBEP','La condición de personal eventual no puede constituir mérito para el acceso a la Función Pública o para la promoción interna.',null),
('aux-canarias:17-63a37e7a7c','aux-canarias',17,'¿Cuál de los siguientes NO es un requisito para adquirir la condición de funcionario de carrera?','["Superar el proceso selectivo", "Acatar la Constitución", "Haber prestado servicios previos como interino", "Tomar posesión dentro del plazo establecido"]'::jsonb,2,'Art. 62.1 TREBEP','Se requiere superar el proceso selectivo, el nombramiento publicado en el diario oficial, el acatamiento de la Constitución (y Estatuto de Autonomía y resto del ordenamiento) y la toma de posesión.',null),
('aux-canarias:17-80fd899882','aux-canarias',17,'¿Cuál de las siguientes NO es causa de pérdida de la condición de funcionario de carrera?','["La renuncia", "La jubilación total", "La pérdida de la nacionalidad", "La excedencia voluntaria"]'::jsonb,3,'Art. 63 TREBEP','Son causas la renuncia, la pérdida de la nacionalidad, la jubilación total, la pena de inhabilitación firme y la sanción firme de separación del servicio. La excedencia es una situación administrativa.',null),
('aux-canarias:17-71d1b76bc5','aux-canarias',17,'La jubilación forzosa de los funcionarios se declara al cumplir:','["65 años, pudiendo solicitar la prolongación hasta los 70", "67 años, sin posibilidad de solicitar la prolongación de la permanencia en el servicio activo", "65 años, pudiendo solicitar la prolongación hasta los 72", "60 años, pudiendo solicitar la prolongación hasta los 65"]'::jsonb,0,'Art. 67.3 TREBEP','Se declara a los sesenta y cinco años, aunque el funcionario puede solicitar la prolongación de la permanencia hasta los setenta.',null),
('aux-canarias:17-546a513ee0','aux-canarias',17,'El personal eventual:','["Tiene derecho a la inamovilidad tras dos años de servicio, y su nombramiento corresponde al órgano de selección tras un concurso de méritos con convocatoria pública", "Ocupa puestos reservados a funcionarios de carrera", "Solo realiza funciones expresamente calificadas como de confianza o asesoramiento especial, y su nombramiento y cese son libres", "Accede mediante concurso de méritos"]'::jsonb,2,'Art. 12.1 y 12.3 TREBEP','El cese tiene lugar, en todo caso, cuando se produzca el de la autoridad a la que preste su función de confianza.',null),
('aux-canarias:17-3affab6cde','aux-canarias',17,'Los funcionarios pueden solicitar la prolongación de la permanencia en el servicio activo, una vez cumplida la edad de jubilación forzosa, como máximo hasta:','["Sin límite", "Los setenta años", "Los sesenta y siete años", "Los sesenta y ocho años"]'::jsonb,1,'Art. 67.3 TREBEP','La jubilación forzosa se declara al cumplir 65 años.',null),
('aux-canarias:17-10cc5de6c7','aux-canarias',17,'La renuncia voluntaria a la condición de funcionario:','["Habrá de ser manifestada por escrito y será aceptada expresamente por la Administración, salvo que el funcionario esté sujeto a expediente disciplinario o procesado", "Puede manifestarse verbalmente ante el superior jerárquico", "No necesita aceptación expresa y surte efectos desde su presentación, aunque el funcionario esté sujeto a expediente disciplinario o haya sido procesado por un delito", "No está permitida mientras el funcionario no haya cumplido la edad de jubilación, salvo que lo autorice expresamente el Consejo de Gobierno por razones excepcionales de interés público"]'::jsonb,0,'Art. 64 TREBEP','La renuncia no inhabilita para volver a ingresar por el procedimiento de selección.',null),
('aux-canarias:17-0b6b13d193','aux-canarias',17,'Transcurridos tres años desde el nombramiento de un interino en plaza vacante, esta:','["Solo podrá ser ocupada por personal funcionario de carrera, salvo que el proceso selectivo quede desierto", "Se amortiza automáticamente y el interino cesa sin derecho a indemnización, aunque el proceso selectivo no se haya convocado", "Pasa a ser plaza de personal laboral", "Se convierte automáticamente en plaza en propiedad del interino que la ocupa, sin necesidad de proceso selectivo"]'::jsonb,0,'Art. 10.4 TREBEP','Se produce el fin de la relación de interinidad.',null),
('aux-canarias:17-81efd30d1c','aux-canarias',17,'La designación del personal directivo profesional atenderá a principios de:','["Libre designación política por el titular del órgano superior", "Sorteo entre funcionarios del subgrupo A1", "Antigüedad en el cuerpo, y en caso de empate, mérito y capacidad mediante procedimientos que garanticen la publicidad y la concurrencia", "Mérito y capacidad y criterios de idoneidad, mediante procedimientos que garanticen la publicidad y concurrencia"]'::jsonb,3,'Art. 13.2 TREBEP','Así lo establece el art. 13.2.',null),
('aux-canarias:18-50aaf4420f','aux-canarias',18,'¿Qué edad mínima se exige para participar en los procesos selectivos?','["Dieciséis años", "Dieciocho años", "Diecisiete años", "Veintiún años"]'::jsonb,0,'Art. 56.1 c) TREBEP','Tener cumplidos dieciséis años y no exceder, en su caso, la edad máxima de jubilación forzosa.',null),
('aux-canarias:18-a9e6c390b5','aux-canarias',18,'¿Cuáles son los sistemas selectivos de los funcionarios de carrera?','["Concurso y libre designación con convocatoria pública", "Oposición y concurso-oposición; el concurso, solo con carácter excepcional y en virtud de ley", "Oposición y concurso-oposición; el concurso, con carácter ordinario y sin necesidad de previsión en una ley", "Oposición, concurso y entrevista personal, que pueden utilizarse indistintamente según lo que decida cada convocatoria"]'::jsonb,1,'Art. 61.6 TREBEP','Son la oposición y el concurso-oposición. El concurso de valoración de méritos solo cabe excepcionalmente y en virtud de ley.',null),
('aux-canarias:18-3082ee7cd3','aux-canarias',18,'En las ofertas de empleo público se reservará un cupo para personas con discapacidad no inferior al:','["2 % de las vacantes", "5 % de las vacantes", "10 % de las vacantes", "7 % de las vacantes"]'::jsonb,3,'Art. 59.1 TREBEP','De ese cupo, al menos el 2 % de las plazas para personas con discapacidad intelectual.',null),
('aux-canarias:18-38a204830d','aux-canarias',18,'Los procedimientos de provisión de puestos de trabajo de los funcionarios de carrera son, con carácter general:','["La entrevista y la valoración del currículum", "La oposición y el concurso-oposición", "El concurso y la libre designación con convocatoria pública", "El concurso y la libre designación sin convocatoria pública"]'::jsonb,2,'Art. 78.2 TREBEP','El concurso es el procedimiento normal de provisión.',null),
('aux-canarias:18-dff7f5aaca','aux-canarias',18,'La libre designación con convocatoria pública consiste en:','["Una prueba de conocimientos eliminatoria sobre las funciones del puesto, seguida de la valoración de méritos por una comisión técnica independiente", "La antigüedad del candidato", "Un sorteo entre los candidatos", "La apreciación discrecional por el órgano competente de la idoneidad de los candidatos en relación con los requisitos del puesto"]'::jsonb,3,'Art. 80.1 TREBEP','Se aplica a los puestos que determinen las leyes por su especial responsabilidad.',null),
('aux-canarias:18-596a221ce0','aux-canarias',18,'NO pueden formar parte de los órganos de selección:','["Los funcionarios de carrera de otras Administraciones públicas", "Los funcionarios del mismo cuerpo o escala al que se aspira a ingresar y el personal laboral fijo de la misma Administración", "El personal de elección o designación política, los funcionarios interinos y el personal eventual", "El personal laboral fijo y los funcionarios de carrera que hayan preparado a aspirantes en los cinco años anteriores"]'::jsonb,2,'Art. 60.2 TREBEP','Los órganos de selección son colegiados y tienden a la paridad.',null),
('aux-canarias:18-72d619fadc','aux-canarias',18,'Los nacionales de los Estados miembros de la Unión Europea pueden acceder como funcionarios en igualdad de condiciones que los españoles, salvo a los empleos que impliquen:','["Funciones de atención al público en lengua cooficial", "Participación en el ejercicio del poder público o en las funciones de salvaguardia de los intereses del Estado", "Trabajos en entidades locales", "Funciones administrativas, de gestión o de auxilio, aunque no impliquen ejercicio de potestades públicas"]'::jsonb,1,'Art. 57.1 TREBEP','Los extranjeros con residencia legal pueden acceder como personal laboral (art. 57.4).',null),
('aux-canarias:18-a60d6e0cb5','aux-canarias',18,'Los órganos de selección no podrán proponer el acceso a la condición de funcionario de un número superior de aprobados al de plazas convocadas:','["Salvo en la Administración Local, cuando lo acuerde el Pleno", "Salvo que la convocatoria prevea otra cosa", "En ningún caso, y cualquier propuesta que lo contravenga será nula de pleno derecho", "Salvo que lo solicite el tribunal"]'::jsonb,1,'Art. 61.8 TREBEP','Regla general con la excepción prevista.',null),
('aux-canarias:18-75fe32e87d','aux-canarias',18,'Según el TREBEP, ¿cuál es el procedimiento normal de provisión de puestos de trabajo de los funcionarios de carrera?','["La adscripción provisional", "El concurso", "La comisión de servicios", "La libre designación"]'::jsonb,1,'Art. 78 TREBEP','La libre designación con convocatoria pública es el otro procedimiento ordinario, reservado a puestos determinados por su especial responsabilidad o confianza.',null),
('aux-canarias:18-0e9311f2a3','aux-canarias',18,'Según el TREBEP, en las ofertas de empleo público se reserva para personas con discapacidad intelectual, dentro del cupo general, al menos:','["El 7 % de las plazas ofertadas", "El 2 % de las plazas ofertadas", "El 1 % de las plazas ofertadas", "El 5 % de las plazas ofertadas"]'::jsonb,1,'Art. 59.1 TREBEP','El cupo total para personas con discapacidad no es inferior al 7 %, y de él al menos el 2 % es para personas con discapacidad intelectual.',null),
('aux-canarias:19-b3be3eebc6','aux-canarias',19,'¿Cuál de estas NO es una situación administrativa de los funcionarios de carrera?','["Servicios especiales", "Excedencia", "Comisión de servicios", "Suspensión de funciones"]'::jsonb,2,'Art. 85.1 TREBEP','Las situaciones son servicio activo, servicios especiales, servicio en otras Administraciones Públicas, excedencia y suspensión de funciones. La comisión de servicios es una forma de provisión de puestos.',null),
('aux-canarias:19-bc93667b2c','aux-canarias',19,'Para obtener la excedencia voluntaria por interés particular hay que haber prestado servicios efectivos durante un mínimo de:','["Un año inmediatamente anterior a la solicitud", "Dos años inmediatamente anteriores", "Tres años, consecutivos o no, en cualquier Administración", "Cinco años inmediatamente anteriores"]'::jsonb,3,'Art. 89.2 TREBEP','Se exige haber prestado servicios efectivos en cualquier Administración durante un mínimo de cinco años inmediatamente anteriores.',null),
('aux-canarias:19-2c4c071882','aux-canarias',19,'La excedencia por cuidado de cada hijo tiene una duración:','["No superior a tres años", "No superior a un año", "No superior a cinco años", "Sin límite"]'::jsonb,0,'Art. 89.4 TREBEP','El periodo de excedencia por cuidado de cada hijo no puede ser superior a tres años.',null),
('aux-canarias:19-549399bf93','aux-canarias',19,'La suspensión firme de funciones por sanción disciplinaria no puede exceder de:','["Tres años", "Seis años", "Dos años", "Un año"]'::jsonb,1,'Art. 90.2 TREBEP','No puede exceder de seis años. Si supera seis meses, el funcionario pierde su puesto de trabajo (art. 90.1).',null),
('aux-canarias:19-595d31904b','aux-canarias',19,'Según el TREBEP, las faltas disciplinarias se clasifican en:','["Graves y leves", "Penales y administrativas", "Muy graves, graves y leves", "Muy graves y graves"]'::jsonb,2,'Art. 95.1 TREBEP','Las faltas disciplinarias pueden ser muy graves, graves y leves.',null),
('aux-canarias:19-ca49920713','aux-canarias',19,'¿Cuál de las siguientes sanciones NO aparece expresamente en la lista del art. 96.1 del TREBEP?','["Apercibimiento", "Demérito", "Traslado forzoso", "Multa económica"]'::jsonb,3,'Art. 96.1 TREBEP','Recoge la separación del servicio, el despido disciplinario, la suspensión firme de funciones, el traslado forzoso, el demérito, el apercibimiento y cualquier otra que establezca una ley.',null),
('aux-canarias:19-7a8655169d','aux-canarias',19,'¿Cuándo prescriben las faltas leves?','["A los seis meses", "Al año", "A los dos años", "A los tres meses"]'::jsonb,0,'Art. 97 TREBEP','Las faltas muy graves prescriben a los tres años, las graves a los dos años y las leves a los seis meses.',null),
('aux-canarias:19-aaa80f1bd6','aux-canarias',19,'¿Cuándo prescriben las sanciones impuestas por faltas leves?','["A los seis meses", "Al año", "A los dos años", "A los tres años"]'::jsonb,1,'Art. 97 TREBEP','Las sanciones por faltas muy graves prescriben a los tres años, las graves a los dos años y las leves al año.',null),
('aux-canarias:19-7ff94ba645','aux-canarias',19,'La suspensión provisional como medida cautelar en un expediente disciplinario no puede exceder de:','["Tres meses, salvo paralización del procedimiento imputable al interesado", "Un año, salvo paralización del procedimiento imputable a la Administración que lo tramita", "Seis meses, salvo paralización del procedimiento imputable al interesado", "Seis meses, sin excepción alguna"]'::jsonb,2,'Art. 98.3 TREBEP','No puede exceder de seis meses, salvo en caso de paralización del procedimiento imputable al interesado.',null),
('aux-canarias:19-01ccd9c597','aux-canarias',19,'El plazo de prescripción de las sanciones comenzará a contarse:','["Desde la firmeza de la resolución sancionadora", "Desde la notificación del pliego de cargos", "Desde la incoación del expediente", "Desde la comisión de la falta"]'::jsonb,0,'Art. 97 TREBEP','El de las faltas, desde que se hubieran cometido, o desde el cese de su comisión si son continuadas.',null),
('aux-canarias:19-bf17f2a4c7','aux-canarias',19,'Las faltas leves se sancionarán:','["Solo por un juez", "Sin procedimiento", "Por el procedimiento previsto para las faltas graves y muy graves", "Por un procedimiento sumario con audiencia al interesado"]'::jsonb,3,'Art. 98.1 TREBEP','Las faltas muy graves y graves exigen el procedimiento previamente establecido.',null),
('aux-canarias:19-1f5f2714e8','aux-canarias',19,'La suspensión de funciones determinará la pérdida del puesto de trabajo cuando exceda de:','["Un año", "Tres meses", "Un mes", "Seis meses"]'::jsonb,3,'Art. 90.1 TREBEP','El funcionario suspenso queda privado del ejercicio de sus funciones.',null),
('aux-canarias:19-8bbfb6c340','aux-canarias',19,'Durante la suspensión provisional como medida cautelar, el funcionario:','["Percibe íntegramente sus retribuciones hasta que se resuelva el expediente disciplinario", "No percibe ninguna retribución", "Percibirá las retribuciones básicas y, en su caso, las prestaciones familiares por hijo a cargo", "Percibirá las retribuciones complementarias, pero no las básicas"]'::jsonb,2,'Art. 98.3 TREBEP','Si la suspensión se eleva a definitiva, deberá devolver lo percibido.',null),
('aux-canarias:19-3c8aa63e25','aux-canarias',19,'Durante los dos primeros años de excedencia por cuidado de hijos o familiares, el funcionario tiene derecho a:','["Ascender automáticamente de grado", "Nada, salvo el cómputo de antigüedad", "La reserva del puesto de trabajo que desempeñaba", "Seguir percibiendo las retribuciones básicas y la reserva de un puesto en la misma localidad"]'::jsonb,2,'Art. 89.4 TREBEP','Transcurrido ese periodo, la reserva lo es a un puesto en la misma localidad y de igual retribución.',null),
('aux-canarias:19-9a40a4c35e','aux-canarias',19,'Las sanciones impuestas por faltas graves prescriben a los:','["Un año", "Dos años", "Tres años", "Seis meses"]'::jsonb,1,'Art. 97 TREBEP','Las muy graves a los tres años y las leves al año.',null),
('aux-canarias:19-25b4e59ae7','aux-canarias',19,'Las faltas muy graves prescriben a los:','["Dos años", "Seis meses", "Cinco años", "Tres años"]'::jsonb,3,'Art. 97 TREBEP','Las graves a los dos años y las leves a los seis meses.',null),
('aux-canarias:19-3a32f5e68a','aux-canarias',19,'Durante los dos primeros meses de excedencia por razón de violencia de género, la funcionaria tendrá derecho a:','["No percibir retribución alguna, aunque se le reserva el puesto de trabajo y se computa el tiempo a efectos de antigüedad", "Percibir las retribuciones íntegras y, en su caso, las prestaciones familiares por hijo a cargo", "Percibir el 50 % de sus retribuciones básicas y complementarias", "Percibir solo las retribuciones básicas, pero no las complementarias ni las prestaciones familiares por hijo a cargo"]'::jsonb,1,'Art. 89.5 TREBEP','Durante los seis primeros meses tiene reserva del puesto, prorrogable por periodos de tres meses hasta dieciocho.',null),
('aux-canarias:19-8b5978dc5f','aux-canarias',19,'La excedencia por cuidado de un familiar hasta el segundo grado que no pueda valerse por sí mismo tiene una duración no superior a:','["Tres años", "Dos años", "Cinco años", "Un año"]'::jsonb,0,'Art. 89.4 TREBEP','Igual que la excedencia por cuidado de cada hijo.',null),
('aux-canarias:19-b301ec9e53','aux-canarias',19,'Es una falta muy grave según el art. 95.2 TREBEP:','["El descuido leve en el trabajo", "El abandono del servicio", "La falta de puntualidad ocasional", "Un retraso de diez minutos"]'::jsonb,1,'Art. 95.2 c) TREBEP','Otras faltas muy graves: desobediencia abierta, acoso laboral, etc.',null),
('aux-canarias:19-460f95c46a','aux-canarias',19,'La sanción de separación del servicio de los funcionarios solo podrá imponerse por:','["Faltas graves reiteradas en el plazo de un año", "Cualquier falta", "La comisión de faltas muy graves", "Faltas graves cometidas de forma reiterada"]'::jsonb,2,'Art. 96.1 a) TREBEP','En los interinos implica la revocación del nombramiento.',null),
('aux-canarias:19-069a9189fc','aux-canarias',19,'¿Cuál de las siguientes NO es una situación administrativa de los funcionarios de carrera según el artículo 85 del TREBEP?','["Servicios especiales", "Suspensión de funciones", "Servicio en otras Administraciones Públicas", "Expectativa de destino indefinida"]'::jsonb,3,'Art. 85.1 TREBEP','Las situaciones son servicio activo, servicios especiales, servicio en otras Administraciones Públicas, excedencia y suspensión de funciones.',null),
('aux-canarias:19-9b33359e58','aux-canarias',19,'Los funcionarios que acceden a la condición de diputado o senador de las Cortes Generales pasan a la situación de:','["Suspensión provisional de funciones", "Servicio activo con dispensa de funciones", "Excedencia voluntaria por interés particular", "Servicios especiales"]'::jsonb,3,'Art. 87.1 TREBEP','Tienen derecho a reingresar al servicio activo en la misma localidad y en las mismas condiciones y con las retribuciones correspondientes a su categoría.',null),
('aux-canarias:19-3cf4018f48','aux-canarias',19,'Según el TREBEP, los funcionarios en situación de servicios especiales:','["Pierden la condición de funcionario mientras dure la situación", "No tienen derecho a reserva de puesto ni a que se les compute el tiempo a ningún efecto", "Solo tienen derecho al cómputo de trienios, pero no a la reserva de puesto", "Tienen derecho a que se les compute el tiempo en esa situación a efectos de ascensos, reconocimiento de trienios y derechos en el régimen de Seguridad Social"]'::jsonb,3,'Art. 87.2 TREBEP','No se les aplica, sin embargo, el régimen de derechos pasivos si les corresponde otro.',null),
('aux-canarias:20-0949071c52','aux-canarias',20,'¿Cuál de estos es un derecho individual que se ejerce de forma colectiva?','["La inamovilidad en la condición de funcionario", "La formación continua", "Las vacaciones", "El ejercicio de la huelga"]'::jsonb,3,'Art. 15 TREBEP','Son derechos individuales ejercidos colectivamente la libertad sindical, la negociación colectiva y participación, la huelga, el planteamiento de conflictos colectivos y la reunión.',null),
('aux-canarias:20-0867ec2229','aux-canarias',20,'¿Cuántos días de permiso por asuntos particulares tienen los funcionarios al año?','["Seis días", "Cuatro días", "Tres días", "Ocho días"]'::jsonb,0,'Art. 48 k) TREBEP','Por asuntos particulares, seis días al año.',null),
('aux-canarias:20-667e06bc37','aux-canarias',20,'¿Cuántos días de permiso corresponden por matrimonio o registro de pareja de hecho?','["Diez días", "Quince días", "Veinte días", "Siete días"]'::jsonb,1,'Art. 48 l) TREBEP','Quince días por matrimonio o registro o constitución formalizada por documento público de pareja de hecho.',null),
('aux-canarias:20-0415c246a3','aux-canarias',20,'¿Qué duración tiene el permiso por nacimiento para la madre biológica según el TREBEP vigente?','["Dieciséis semanas", "Doce semanas", "Diecinueve semanas", "Veinticuatro semanas"]'::jsonb,2,'Art. 49 a) TREBEP','Tras la última reforma son diecinueve semanas (treinta y dos en caso de familia monoparental). Muchos tests antiguos siguen diciendo dieciséis.',null),
('aux-canarias:20-314e4c3162','aux-canarias',20,'¿Cuántos días de vacaciones retribuidas tienen los funcionarios por año completo de servicio?','["Treinta días naturales", "Veinte días hábiles", "Veinticinco días hábiles", "Veintidós días hábiles"]'::jsonb,3,'Art. 50.1 TREBEP','Veintidós días hábiles, o los que correspondan proporcionalmente si el tiempo de servicio fue menor.',null),
('aux-canarias:20-70916cd2e6','aux-canarias',20,'Las retribuciones básicas están integradas por:','["La productividad y las gratificaciones por servicios extraordinarios", "El sueldo asignado a cada subgrupo o grupo y los trienios", "El complemento de destino y el complemento específico", "El sueldo asignado a cada subgrupo, los trienios y el complemento de destino del puesto que se ocupe"]'::jsonb,1,'Art. 23 TREBEP','Los trienios consisten en una cantidad por cada tres años de servicio.',null),
('aux-canarias:20-a3c2454153','aux-canarias',20,'Los Delegados de Personal representan a los funcionarios en unidades electorales que cuenten con:','["Más de 50 funcionarios", "Menos de 6 funcionarios", "Entre 6 y 49 funcionarios", "Más de 250 funcionarios"]'::jsonb,2,'Art. 39.2 TREBEP','A partir de 50 funcionarios hay Juntas de Personal.',null),
('aux-canarias:20-be137806de','aux-canarias',20,'Según el art. 54.11, los empleados públicos garantizarán la atención al ciudadano en:','["La lengua oficial que solicite y, si lo pide, también en inglés", "Castellano exclusivamente", "La lengua que lo solicite siempre que sea oficial en el territorio", "La lengua que elija el funcionario"]'::jsonb,2,'Art. 54.11 TREBEP','Es otro principio de conducta.',null),
('aux-canarias:20-43ee431c23','aux-canarias',20,'Por traslado de domicilio sin cambio de residencia, el funcionario tiene un permiso de:','["Ningún día", "Dos días", "Un día", "Tres días"]'::jsonb,2,'Art. 48 b) TREBEP','Permiso de un día por traslado de domicilio.',null),
('aux-canarias:20-80d4c592ca','aux-canarias',20,'La funcionaria víctima de violencia de género que reduzca su jornada en un tercio o menos:','["Pierde las retribuciones básicas", "Solo cobra el 50 %", "Mantendrá sus retribuciones íntegras", "Pierde todas sus retribuciones"]'::jsonb,2,'Art. 49 d) TREBEP','Si la reducción es mayor, la disminución de retribuciones es proporcional.',null),
('aux-canarias:20-5f6978b509','aux-canarias',20,'El permiso parental para el cuidado de hijo o menor acogido por tiempo superior a un año, hasta que cumpla ocho años, tiene una duración máxima de:','["Ocho semanas, y no es retribuido", "Un año", "Dieciséis semanas retribuidas", "Cuatro semanas retribuidas"]'::jsonb,0,'Art. 49 g) TREBEP','Se requiere un preaviso de quince días.',null),
('aux-canarias:20-6f40a1d65d','aux-canarias',20,'El teletrabajo de los empleados públicos:','["Es irreversible una vez concedido y solo puede revocarse como sanción disciplinaria tras el expediente correspondiente", "Solo se permite al personal interino", "Es obligatorio para los puestos cuyas funciones permitan prestarse a distancia, salvo renuncia justificada del empleado", "Tendrá carácter voluntario y reversible, salvo en supuestos excepcionales debidamente justificados"]'::jsonb,3,'Art. 47 bis.2 TREBEP','Se realizará en los términos de las normas que se dicten en desarrollo del Estatuto.',null),
('aux-canarias:20-21922a13a1','aux-canarias',20,'Por accidente o enfermedad grave de un familiar de primer grado de consanguinidad o afinidad, el funcionario tiene un permiso de:','["Cinco días hábiles", "Diez días hábiles", "Tres días naturales", "Dos días hábiles"]'::jsonb,0,'Art. 48 a) TREBEP','Para familiares de segundo grado, cuatro días hábiles.',null),
('aux-canarias:20-2d47154286','aux-canarias',20,'Quedan excluidas de la obligatoriedad de la negociación:','["Las retribuciones complementarias de los funcionarios", "Las decisiones que afecten a las potestades de organización de las Administraciones Públicas", "Los criterios generales de acceso, carrera, provisión, sistemas de clasificación de puestos y planes de recursos humanos", "La evaluación del desempeño"]'::jsonb,1,'Art. 37.2 a) TREBEP','Las demás opciones son materias objeto de negociación (art. 37.1).',null),
('aux-canarias:20-f97fa3e255','aux-canarias',20,'Según el art. 54.6 TREBEP, los empleados públicos:','["Pueden aceptar regalos de cualquier valor siempre que los declaren a su superior jerárquico en el plazo de diez días desde su recepción y los inscriban en el registro", "Deben declarar los regalos recibidos en su declaración de bienes", "Solo pueden aceptar regalos de otros empleados públicos o de los ciudadanos, siempre que no superen el valor que fije cada Administración en su código ético", "Rechazarán cualquier regalo, favor o servicio en condiciones ventajosas que vaya más allá de los usos habituales, sociales y de cortesía"]'::jsonb,3,'Art. 54.6 TREBEP','Es un principio de conducta.',null),
('aux-canarias:20-6f14a7bf03','aux-canarias',20,'Las pagas extraordinarias de los funcionarios serán:','["Una al año, por el importe de una mensualidad de retribuciones básicas", "Cuatro al año", "Tres al año, cada una por el importe de una mensualidad de retribuciones básicas y de la mitad de las complementarias, que se abonan en marzo, junio y diciembre", "Dos al año, cada una por el importe de una mensualidad de retribuciones básicas y de la totalidad de las complementarias, salvo excepciones"]'::jsonb,3,'Art. 22.4 TREBEP','Son dos pagas al año.',null),
('aux-canarias:20-01234101d7','aux-canarias',20,'Es un derecho individual de los empleados públicos del art. 14 TREBEP:','["La formación continua y la actualización permanente de sus conocimientos", "La negociación colectiva y la participación en la determinación de las condiciones de trabajo", "La huelga y el planteamiento de conflictos colectivos de trabajo en su unidad", "El planteamiento de conflictos colectivos de trabajo"]'::jsonb,0,'Art. 14 g) TREBEP','Los demás citados son derechos individuales ejercidos colectivamente (art. 15).',null),
('aux-canarias:20-925b55b89a','aux-canarias',20,'A efectos de vacaciones de los funcionarios, los sábados:','["No se consideran días hábiles, salvo en los horarios especiales", "Computan doble", "Se consideran hábiles solo en agosto", "Se consideran siempre días hábiles, cualquiera que sea el horario del funcionario"]'::jsonb,0,'Art. 50.1 TREBEP','Las vacaciones son de 22 días hábiles.',null),
('aux-canarias:20-4ed0d3038e','aux-canarias',20,'La parte de jornada no realizada sin justificación dará lugar a:','["La deducción proporcional de haberes, que no tendrá carácter sancionador", "Ninguna consecuencia económica, aunque deberá recuperarse en otro momento de la semana", "La separación del servicio", "Una sanción disciplinaria grave, previa tramitación del expediente correspondiente"]'::jsonb,0,'Art. 30.1 TREBEP','La deducción no es una sanción.',null),
('aux-canarias:20-f67c57a76b','aux-canarias',20,'Para participar en la promoción interna, los funcionarios deben poseer una antigüedad de, al menos:','["Un año de servicio activo en el mismo cuerpo o escala", "Dos años de servicio activo en el inferior subgrupo o grupo de clasificación profesional", "Tres años de servicio activo en el mismo cuerpo o escala, de los cuales al menos uno en la misma Administración", "Cinco años de servicio activo en cualquier cuerpo o escala de la misma Administración pública"]'::jsonb,1,'Art. 18.2 TREBEP','Además de la titulación y demás requisitos exigidos.',null),
('aux-canarias:20-e40d0bccb6','aux-canarias',20,'Los trienios consisten en una cantidad, igual para cada subgrupo o grupo, por cada:','["Año de servicio", "Cinco años de servicio", "Dos años de servicio", "Tres años de servicio"]'::jsonb,3,'Art. 23 b) TREBEP','Retribución básica por antigüedad.',null),
('aux-canarias:20-11150746b2','aux-canarias',20,'Las retribuciones de los funcionarios de carrera se clasifican en:','["Ordinarias y extraordinarias", "Directas e indirectas", "Básicas y complementarias", "Fijas y variables"]'::jsonb,2,'Art. 22.1 TREBEP','Las pagas extraordinarias son dos al año.',null),
('aux-canarias:20-bc13f0c20d','aux-canarias',20,'Los Pactos y Acuerdos, salvo que se establezca otra cosa:','["Se prorrogarán de año en año si no media denuncia expresa de una de las partes", "Caducan al año de su firma, salvo que se renueven expresamente", "Se prorrogarán por periodos de cuatro años, salvo que una de las partes los denuncie con seis meses de antelación", "Duran cuatro años improrrogables"]'::jsonb,0,'Art. 38.11 TREBEP','Prórroga anual salvo denuncia.',null),
('aux-canarias:20-4dbad3dc27','aux-canarias',20,'Por fallecimiento de un familiar de primer grado en la misma localidad, el permiso es de:','["Cinco días hábiles", "Tres días hábiles", "Dos días hábiles", "Un día"]'::jsonb,1,'Art. 48 a) TREBEP','Si es en distinta localidad, cinco días hábiles.',null),
('aux-canarias:20-9688cd3a4c','aux-canarias',20,'Las Mesas de Negociación quedarán válidamente constituidas cuando las organizaciones sindicales presentes representen, como mínimo:','["El 10 % de los miembros de los órganos unitarios de representación", "La totalidad de los miembros de los órganos unitarios de representación", "La mayoría absoluta de los miembros de los órganos unitarios de representación en el ámbito de que se trate", "Un tercio de los miembros de los órganos unitarios de representación en el ámbito de que se trate"]'::jsonb,2,'Art. 35.1 TREBEP','Ninguna de las partes puede superar quince miembros (art. 35.4).',null),
('aux-canarias:20-453be8b31a','aux-canarias',20,'Si la incapacidad temporal impide disfrutar las vacaciones en el año natural, podrán disfrutarse una vez finalizada, siempre que no hayan transcurrido más de:','["Un año a partir del final del año en que se hayan originado", "Tres años", "Seis meses a partir del final del año en que se hayan originado", "Dieciocho meses a partir del final del año en que se hayan originado"]'::jsonb,3,'Art. 50.2 TREBEP','Las vacaciones no pueden sustituirse por una cuantía económica, salvo cese no voluntario.',null),
('aux-canarias:20-3481b04132','aux-canarias',20,'En el permiso por nacimiento, ¿cuántas semanas inmediatas posteriores al parto son de descanso obligatorio?','["Dos semanas", "Seis semanas", "Diez semanas", "Cuatro semanas"]'::jsonb,1,'Art. 49 a) TREBEP','Las seis semanas posteriores al parto son obligatorias e ininterrumpidas.',null),
('aux-canarias:20-81dc60a748','aux-canarias',20,'La duración del mandato de los Delegados de Personal y de las Juntas de Personal es de:','["Tres años", "Cinco años", "Dos años", "Cuatro años"]'::jsonb,3,'Art. 42 TREBEP','Pueden ser reelegidos en sucesivos procesos electorales.',null),
('aux-canarias:21-b5777555f6','aux-canarias',21,'Según el Decreto 212/1991, ¿bajo qué principio se organiza y funciona la Administración autonómica de Canarias?','["Autonomía funcional de cada consejería", "Coordinación interinsular", "Ordenación jerárquica de sus órganos", "Descentralización territorial plena"]'::jsonb,2,'Art. 2 Decreto 212/1991','El art. 2.1 dispone que la Administración autonómica se organiza y funciona bajo el principio de ordenación jerárquica de sus órganos.',null),
('aux-canarias:21-20f5dd88d1','aux-canarias',21,'Según el Decreto 212/1991, ¿cuáles son los órganos superiores de los departamentos?','["Las direcciones generales, las direcciones territoriales de cada isla y las jefaturas de servicio", "Las secretarías generales técnicas, los servicios, las secciones y los negociados", "Las viceconsejerías, las secretarías generales técnicas y las direcciones generales", "Las consejerías, las viceconsejerías, los servicios y las secciones de cada departamento"]'::jsonb,2,'Art. 2 Decreto 212/1991','El art. 2.2 los enumera: viceconsejerías, secretarías generales técnicas y direcciones generales.',null),
('aux-canarias:21-ac4dd2975f','aux-canarias',21,'¿Con qué finalidad pueden establecerse direcciones territoriales según el Decreto 212/1991?','["Para resolver los recursos de alzada contra los directores generales", "Para coordinar a los cabildos insulares en el ejercicio de las materias que la comunidad autónoma les haya delegado", "Para gestionar el personal de todas las consejerías de una isla", "Para desarrollar las funciones del departamento, o un sector de ellas, en un ámbito espacial localizado"]'::jsonb,3,'Art. 2 Decreto 212/1991','El art. 2.3 permite crearlas para desarrollar las funciones del departamento, o un sector material, en un ámbito espacial localizado.',null),
('aux-canarias:21-302aa8e87f','aux-canarias',21,'¿Cuál de estas facultades NO figura entre las del poder de dirección del art. 3.2 del Decreto 212/1991?','["Inspeccionar y evaluar el rendimiento de los servicios", "Avocar con carácter general las competencias de los inferiores", "Corregir las desviaciones que se produzcan", "Fijar los objetivos a alcanzar"]'::jsonb,1,'Art. 3 Decreto 212/1991','El poder de dirección incluye fijar objetivos, planes, ordenar e impulsar, supervisar, inspeccionar y corregir desviaciones; la avocación nunca puede tener efectos generales (art. 7.2).',null),
('aux-canarias:21-b150bf2565','aux-canarias',21,'Según el Decreto 212/1991, ¿en qué se diferencian las directrices de las instrucciones?','["Las directrices obligan en cuanto a los resultados y el plazo, con libertad en los medios", "Las directrices no son obligatorias para sus destinatarios", "Las directrices solo pueden dictarlas los consejeros", "Las directrices son obligatorias para sus destinatarios en todos sus elementos, también en los medios"]'::jsonb,0,'Art. 4 Decreto 212/1991','Las instrucciones obligan en todos sus elementos; las directrices, en los resultados y, en su caso, el plazo, con libertad en cuanto a los medios.',null),
('aux-canarias:21-f5e4155239','aux-canarias',21,'Según el Decreto 212/1991, ¿cómo son las instrucciones para sus destinatarios?','["Obligatorias solo si las dicta un órgano superior", "Obligatorias en todos sus elementos", "Orientativas, salvo que se publiquen en el BOC", "Obligatorias solo en cuanto a los resultados"]'::jsonb,1,'Art. 4 Decreto 212/1991','El art. 4.2 dice que las instrucciones son obligatorias para sus destinatarios en todos sus elementos.',null),
('aux-canarias:21-3d3feca532','aux-canarias',21,'Si una norma atribuye una competencia a la Administración autonómica sin especificar el órgano, ¿a quién corresponde instruir y resolver según el Decreto 212/1991?','["Al consejero competente por razón de la materia", "Al Gobierno de Canarias, que podrá delegarla en el consejero competente por razón de la materia", "A la secretaría general técnica del departamento, como órgano horizontal de coordinación", "A los órganos inferiores competentes por razón de la materia y del territorio"]'::jsonb,3,'Art. 6 Decreto 212/1991','No corresponde a los órganos centrales, sino a los inferiores competentes por materia y territorio; si hay varios, al de competencia territorial más amplia.',null),
('aux-canarias:21-ecd2731ff9','aux-canarias',21,'Según el Decreto 212/1991, ¿qué alcance puede tener la avocación?','["Todas las competencias del órgano inferior", "Cualquier asunto, si lo autoriza el Gobierno", "Solo un expediente o un conjunto de expedientes determinados", "Una materia completa durante un año"]'::jsonb,2,'Art. 7 Decreto 212/1991','La avocación no puede tener efectos generales y se limita a un expediente o conjunto de expedientes determinados.',null),
('aux-canarias:21-2b7172f29a','aux-canarias',21,'¿Qué requisitos exige el Decreto 212/1991 para la efectividad de la avocación?','["Que se adopte de forma motivada y se comunique al órgano afectado y a los interesados", "Que la apruebe el Gobierno y se publique en el BOC antes de dictar la resolución del expediente", "Que la solicite el órgano inferior por escrito razonado dirigido al superior jerárquico y al consejero", "Que la informe la Dirección General del Servicio Jurídico"]'::jsonb,0,'Art. 7 Decreto 212/1991','El art. 7.3 exige que se adopte de forma motivada y se comunique al órgano afectado y a los interesados en el procedimiento.',null),
('aux-canarias:21-2686cfa798','aux-canarias',21,'Según el Decreto 212/1991, ¿de quién dependen directamente las viceconsejerías?','["Del Consejo de Gobierno", "De las secretarías generales técnicas", "Del Presidente del Gobierno", "De los titulares de los departamentos"]'::jsonb,3,'Art. 9 Decreto 212/1991','En el ámbito de sus atribuciones, las viceconsejerías dependen directamente de los titulares de los departamentos.',null),
('aux-canarias:21-5eba336cd4','aux-canarias',21,'¿Cómo son nombrados los viceconsejeros, los secretarios generales técnicos y los directores generales según el Decreto 212/1991?','["Por el Parlamento de Canarias a propuesta del Gobierno", "Por decreto del Presidente, sin propuesta previa", "Por decreto del Gobierno a propuesta del consejero correspondiente", "Por orden del consejero, previa libre designación con convocatoria pública"]'::jsonb,2,'Arts. 10, 14 y 18 Decreto 212/1991','Los tres son nombrados y cesados por decreto del Gobierno a propuesta del consejero correspondiente.',null),
('aux-canarias:21-379e809ada','aux-canarias',21,'Según el Decreto 212/1991, ¿qué órgano tiene, salvo norma legal, competencia para incoar y resolver los procedimientos sancionadores por infracciones graves?','["Las viceconsejerías", "Las secretarías generales técnicas", "Las direcciones generales", "Los consejeros"]'::jsonb,0,'Art. 11 Decreto 212/1991','Las viceconsejerías resuelven los sancionadores por infracciones graves; las direcciones generales, por las leves (art. 19.2).',null),
('aux-canarias:21-cd822b988f','aux-canarias',21,'Según el Decreto 212/1991, ¿cómo se definen las secretarías generales técnicas?','["Unidades de apoyo y documentación de las decisiones", "Órganos horizontales de coordinación administrativa general de los departamentos", "Órganos a los que corresponde un sector material de las funciones del departamento", "Órganos de participación de los sectores afectados por las acciones públicas del departamento"]'::jsonb,1,'Art. 13 Decreto 212/1991','El art. 13.1 las define como órganos horizontales de coordinación administrativa general.',null),
('aux-canarias:21-21979941cf','aux-canarias',21,'¿Qué órgano elabora el anteproyecto de presupuesto del departamento según el Decreto 212/1991?','["La viceconsejería", "La dirección general competente en presupuestos", "El servicio de contratación", "La secretaría general técnica"]'::jsonb,3,'Art. 15 Decreto 212/1991','El art. 15.3 a) atribuye a la secretaría general técnica elaborar el anteproyecto de presupuesto integrando las propuestas de los demás órganos.',null),
('aux-canarias:21-3ceb03b132','aux-canarias',21,'¿Qué funciones desempeñan directamente las secretarías generales técnicas, según el art. 15.4 del Decreto 212/1991?','["La gestión de las subvenciones nominativas", "El inventario patrimonial y el archivo general", "La resolución de los recursos de alzada", "La contratación de obras de cualquier importe del departamento"]'::jsonb,1,'Art. 15 Decreto 212/1991','Además de las facultades del art. 3.2, desempeñan directamente las funciones de inventario patrimonial y archivo general.',null),
('aux-canarias:21-2944279c68','aux-canarias',21,'En materia disciplinaria, ¿qué corresponde a las secretarías generales técnicas según el Decreto 212/1991?','["Incoar los procedimientos por faltas graves y muy graves y resolverlos si no implican separación del servicio", "Imponer la sanción de separación del servicio a los funcionarios del departamento", "Únicamente sancionar las faltas leves de todo el departamento", "Informar los expedientes que resuelve la Dirección General de la Función Pública, sin incoarlos ni resolverlos"]'::jsonb,0,'Art. 15 Decreto 212/1991','El art. 15.6 d) les atribuye incoar los procedimientos por faltas graves y muy graves y resolverlos cuando la sanción no implique separación del servicio.',null),
('aux-canarias:21-bf3aca9c9b','aux-canarias',21,'Según el Decreto 212/1991, ¿cómo quedan los actos de los secretarios generales técnicos en materia de personal?','["Son recurribles en alzada ante el consejero", "Requieren ratificación del viceconsejero", "Causan estado en vía administrativa", "Son recurribles en alzada ante la Dirección General de la Función Pública"]'::jsonb,2,'Art. 16 Decreto 212/1991','El art. 16.2 dispone que causan estado en vía administrativa; los demás actos admiten alzada ante el consejero.',null),
('aux-canarias:21-76ffe5f835','aux-canarias',21,'¿Ante quién cabe recurso contra los actos de los directores generales en materia de personal según el Decreto 212/1991?','["Ante las secretarías generales técnicas, en los términos del recurso de alzada", "Ante el consejero competente en materia de Administraciones públicas", "Ante la Dirección General de la Función Pública, en los términos del recurso de reposición", "Ante la viceconsejería de adscripción o, en su defecto, ante el consejero del departamento"]'::jsonb,0,'Art. 20 Decreto 212/1991','En materia de personal, el recurso se presenta ante las secretarías generales técnicas en los términos previstos para el de alzada.',null),
('aux-canarias:21-18b87192d0','aux-canarias',21,'Según el Decreto 212/1991, ¿cómo son nombrados los directores territoriales?','["Por el cabildo insular de la isla correspondiente", "Por decreto del Gobierno a propuesta del consejero", "Por concurso de méritos entre funcionarios de carrera del propio departamento, con convocatoria pública en el BOC", "Por el titular del departamento, entre funcionarios de carrera, por libre designación con convocatoria pública"]'::jsonb,3,'Art. 22 Decreto 212/1991','Los nombra el titular del departamento entre funcionarios de carrera mediante libre designación con convocatoria pública, y son libremente removidos.',null),
('aux-canarias:21-feb1ae2f55','aux-canarias',21,'Según el Decreto 212/1991, ¿cómo se definen los negociados?','["Órganos de coordinación horizontal", "Unidades de apoyo y documentación de las decisiones", "Unidades de trámite y ejecución de los cometidos de las secciones", "Unidades de estudio, propuesta y gestión"]'::jsonb,2,'Art. 25 Decreto 212/1991','Los servicios son unidades de apoyo; las secciones, de estudio, propuesta y gestión; y los negociados, de trámite y ejecución.',null),
('aux-canarias:21-f6c87778dc','aux-canarias',21,'¿Cuál de estas atribuciones corresponde a los jefes de servicio según el Decreto 212/1991?','["Resolver los recursos de alzada interpuestos contra los actos de los jefes de sección y de negociado del servicio", "Resolver los procedimientos reglados de simple confrontación de hechos o aplicación automática de normas", "Incoar procedimientos sancionadores por infracciones leves", "Aprobar la relación de puestos de trabajo de su servicio"]'::jsonb,1,'Art. 27 Decreto 212/1991','El art. 27.1 b) les atribuye resolver los procedimientos reglados que consistan en la simple confrontación de hechos o la aplicación automática de normas.',null),
('aux-canarias:21-64b6b0b729','aux-canarias',21,'¿Qué atribuciones de los jefes de servicio pueden ejercer también los jefes de sección y de negociado según el Decreto 212/1991?','["Instruir procedimientos y formular propuestas de resolución", "Notificar resoluciones, expedir certificaciones y diligenciar comparecencias", "Resolver procedimientos reglados", "Proponer gratificaciones y complementos de productividad"]'::jsonb,1,'Art. 27 Decreto 212/1991','El art. 27.2 les permite realizar las atribuciones de las letras c), d) y e): notificar, certificar y diligenciar comparecencias.',null),
('aux-canarias:21-e1b6c293ae','aux-canarias',21,'Según el Decreto 212/1991, ¿cómo se crean los órganos colegiados de los departamentos?','["Por decreto del Gobierno", "Por ley del Parlamento de Canarias", "Por orden del consejero", "Por resolución de la secretaría general técnica"]'::jsonb,0,'Art. 29 Decreto 212/1991','El art. 29.2 dispone que los órganos colegiados se crean por decreto del Gobierno.',null),
('aux-canarias:21-6f27e7f7e1','aux-canarias',21,'A falta de previsión en su norma constitutiva, ¿cómo se nombra al presidente de un órgano colegiado según el Decreto 212/1991?','["Lo elige el pleno del órgano por mayoría de dos tercios en todas las votaciones", "Lo designa el consejero de adscripción", "Entre sus miembros, por mayoría absoluta en primera votación o simple en segunda", "Lo preside siempre el miembro de mayor rango"]'::jsonb,2,'Art. 30 Decreto 212/1991','En defecto de las normas constitutivas, se elige entre los miembros por mayoría absoluta en primera votación o por mayoría simple en segunda.',null),
('aux-canarias:21-84bb93c231','aux-canarias',21,'Según el Decreto 212/1991, ¿qué determinan los reglamentos orgánicos de los departamentos?','["Solo la sede de las consejerías y la distribución de sus servicios entre las islas", "Los presupuestos de los organismos autónomos", "Las retribuciones de los altos cargos y del personal eventual del departamento", "Las estructuras centrales y territoriales y las atribuciones de cada órgano"]'::jsonb,3,'Art. 31 Decreto 212/1991','Determinan las estructuras centrales y territoriales y asignan a cada órgano sus atribuciones; comprenden todos los órganos, unipersonales y colegiados.',null),
('aux-canarias:21-4b0a4c85ee','aux-canarias',21,'¿Cómo se aprueban los reglamentos orgánicos de las consejerías según el Decreto 212/1991?','["Por orden del consejero afectado", "Por decreto del Presidente, a propuesta de la consejería competente en materia de hacienda y presupuestos", "Por ley del Parlamento de Canarias", "Por decreto del Gobierno, a propuesta conjunta de la consejería afectada y de la Presidencia del Gobierno"]'::jsonb,3,'Art. 33 Decreto 212/1991','El art. 33 dispone que se aprueban por decreto del Gobierno, a propuesta conjunta de la consejería afectada y de la Presidencia del Gobierno.',null),
('aux-canarias:21-c5a5018153','aux-canarias',21,'¿Cuál de estos documentos debe acompañar a un proyecto de reglamento orgánico según el Decreto 212/1991?','["Los organigramas con la posición jerárquica de los órganos", "La memoria de impacto de género firmada por el Parlamento", "El dictamen del Consejo Económico y Social", "El informe del Consejo Consultivo de Canarias"]'::jsonb,0,'Art. 32 Decreto 212/1991','El art. 32.1 exige análisis de las áreas funcionales, justificación de la distribución de competencias, organigramas y valoración económica.',null),
('aux-canarias:21-fbdba2fce6','aux-canarias',21,'Según el Decreto 212/1991, ¿quién resuelve los conflictos de atribuciones entre dos consejerías?','["El consejero de mayor antigüedad", "La Presidencia del Gobierno", "El Consejo Consultivo de Canarias", "La Dirección General del Servicio Jurídico"]'::jsonb,1,'DA 1.ª Decreto 212/1991','Los conflictos entre órganos de un departamento los resuelve el superior jerárquico común; entre dos consejerías, la Presidencia del Gobierno.',null),
('aux-canarias:21-b3fcfd0376','aux-canarias',21,'En un conflicto de atribuciones del Decreto 212/1991, ¿en qué plazo debe informar el órgano requerido?','["Diez días", "Cinco días", "Quince días", "Un mes"]'::jsonb,2,'DA 1.ª Decreto 212/1991','El órgano requerido informa en quince días o adopta en ese plazo la resolución propuesta por el requirente.',null),
('aux-canarias:22-e83a197ef4','aux-canarias',22,'Una notificación electrónica se entiende rechazada cuando pasan sin que se acceda a su contenido:','["10 días naturales desde su puesta a disposición", "10 días hábiles desde su puesta a disposición en la sede electrónica", "15 días naturales desde su puesta a disposición", "5 días hábiles desde su puesta a disposición"]'::jsonb,0,'Art. 43.2 Ley 39/2015','Se entiende rechazada cuando han pasado diez días naturales desde su puesta a disposición sin acceder a su contenido.',null),
('aux-canarias:22-a76aa7ab0e','aux-canarias',22,'¿Qué sistema de identificación electrónica menciona expresamente el art. 9.2 de la Ley 39/2015?','["Los certificados electrónicos cualificados de firma electrónica", "El reconocimiento facial mediante la cámara del dispositivo", "La huella dactilar registrada en el DNI", "El número de teléfono móvil asociado a una cuenta bancaria del interesado"]'::jsonb,0,'Art. 9.2 Ley 39/2015','Menciona los certificados cualificados de firma, los de sello electrónico y cualquier otro sistema que las Administraciones consideren válido.',null),
('aux-canarias:22-8210c436c5','aux-canarias',22,'Con carácter general, para realizar cualquier actuación en el procedimiento, los interesados deben:','["Firmar electrónicamente todo", "Acreditar previamente su identidad", "Presentarse en persona", "Aportar un certificado de antecedentes"]'::jsonb,1,'Art. 11.1 Ley 39/2015','Basta con que acrediten previamente su identidad.',null),
('aux-canarias:22-dfc98fa0d5','aux-canarias',22,'¿Para cuál de estas actuaciones exige la Ley 39/2015 el uso de la firma?','["Consultar el estado de un expediente", "Pedir información general", "Interponer recursos", "Solicitar cita previa"]'::jsonb,2,'Art. 11.2 Ley 39/2015','Se exige firma para formular solicitudes, presentar declaraciones responsables o comunicaciones, interponer recursos, desistir y renunciar a derechos.',null),
('aux-canarias:22-9db73beed2','aux-canarias',22,'Las Administraciones deben asistir en el uso de medios electrónicos a:','["Las empresas y demás personas jurídicas", "Los empleados públicos, para los trámites relacionados con su condición de tales", "Las entidades sin personalidad jurídica que carezcan de medios electrónicos propios", "Las personas físicas que no estén obligadas a relacionarse electrónicamente"]'::jsonb,3,'Art. 12.2 Ley 39/2015','Deben asistir a las personas físicas no obligadas, especialmente en identificación y firma, presentación de solicitudes y obtención de copias auténticas.',null),
('aux-canarias:22-5c65005c6b','aux-canarias',22,'La sede electrónica es:','["Un edificio de la Administración donde se atiende al público", "Un programa informático de gestión", "La dirección de correo electrónico oficial de un organismo público, a través de la cual se presentan escritos con plena validez jurídica", "Una dirección electrónica disponible a través de redes de telecomunicaciones cuya titularidad corresponde a una Administración"]'::jsonb,3,'Art. 38.1 Ley 40/2015','Es una dirección electrónica, disponible para los ciudadanos a través de redes de telecomunicaciones, cuya titularidad corresponde a una Administración u organismo público.',null),
('aux-canarias:22-7bc9b56cc0','aux-canarias',22,'El portal de internet de una Administración es:','["El punto de acceso electrónico que permite acceder a la información publicada y, en su caso, a la sede electrónica", "Lo mismo que la sede electrónica, con la misma responsabilidad sobre la integridad y actualización de la información y los servicios", "Un registro electrónico general en el que se presentan escritos dirigidos a cualquier órgano de esa Administración o de otras", "Un tablón de anuncios físico"]'::jsonb,0,'Art. 39 Ley 40/2015','Es el punto de acceso electrónico de titularidad pública que permite acceder a la información publicada y, en su caso, a la sede electrónica.',null),
('aux-canarias:22-b5f25201ff','aux-canarias',22,'Los interesados podrán firmar a través de cualquier medio que permita acreditar:','["La fecha del documento y su número de registro", "Su identidad, pero no la integridad del documento", "La autenticidad de la expresión de su voluntad y consentimiento, pero no la integridad del documento", "La autenticidad de la expresión de su voluntad y consentimiento, y la integridad e inalterabilidad del documento"]'::jsonb,3,'Art. 10.1 Ley 39/2015','La firma debe acreditar autenticidad de la voluntad y la integridad del documento.',null),
('aux-canarias:22-25f8297158','aux-canarias',22,'Las notificaciones se practicarán preferentemente:','["Mediante anuncio en el BOE, salvo que el interesado señale un domicilio", "En papel en el domicilio del interesado, salvo que este solicite la notificación electrónica", "Por medios electrónicos o en papel, a elección del órgano que dicte el acto", "Por medios electrónicos y, en todo caso, cuando el interesado esté obligado a recibirlas por esta vía"]'::jsonb,3,'Art. 41.1 Ley 39/2015','Se practicarán preferentemente por medios electrónicos.',null),
('aux-canarias:22-200d9db865','aux-canarias',22,'Las Administraciones están obligadas a verificar la identidad de los interesados mediante la comprobación de:','["Su huella dactilar o cualquier otro dato biométrico que conste en el DNI o en el documento identificativo equivalente", "Su nombre y apellidos o denominación o razón social, que consten en el DNI o documento identificativo equivalente", "Su dirección de correo electrónico", "Su número de teléfono móvil"]'::jsonb,1,'Art. 9.1 Ley 39/2015','Se verifica con el nombre y apellidos o razón social del DNI o documento equivalente.',null),
('aux-canarias:22-1f118b10ed','aux-canarias',22,'Si nadie se hace cargo de la notificación en papel en el domicilio, se repetirá:','["Dos veces en la misma semana, en horas distintas", "No se repite, y se publica directamente en el BOE", "Una sola vez y en una hora distinta dentro de los tres días siguientes", "Una sola vez y en la misma hora dentro de los cinco días siguientes"]'::jsonb,2,'Art. 42.2 Ley 39/2015','Se repite por una sola vez y en hora distinta dentro de los tres días siguientes.',null),
('aux-canarias:22-e7d7918aa0','aux-canarias',22,'¿Cuál de los siguientes es un sistema de identificación electrónica previsto en el art. 9.2?','["Un mensaje desde un número de teléfono previamente comunicado", "El envío de una fotocopia escaneada del DNI por correo electrónico, junto con la solicitud firmada a mano", "Los sistemas basados en certificados electrónicos cualificados de firma electrónica", "Una llamada telefónica grabada"]'::jsonb,2,'Art. 9.2 Ley 39/2015','También los certificados cualificados de sello electrónico y otros sistemas que las AAPP consideren válidos.',null),
('aux-canarias:22-be13b48c3f','aux-canarias',22,'Las Administraciones podrán practicar notificaciones por medios no electrónicos cuando:','["Para asegurar la eficacia de la actuación sea necesario practicarla por entrega directa de un empleado público", "Sea fin de semana", "La notificación sea favorable al interesado", "El interesado esté obligado a relacionarse electrónicamente con la Administración y no haya accedido a la notificación"]'::jsonb,0,'Art. 41.2 b) Ley 39/2015','También cuando el interesado comparezca espontáneamente en una oficina de asistencia y solicite la comunicación personal.',null),
('aux-canarias:22-5bdb96095a','aux-canarias',22,'Las notificaciones por medios electrónicos se entienden practicadas:','["Al día siguiente de su emisión", "Cuando el interesado contesta", "Cuando se envía al interesado el aviso de puesta a disposición por correo electrónico o SMS", "En el momento en que se produzca el acceso a su contenido"]'::jsonb,3,'Art. 43.2 Ley 39/2015','Se entienden practicadas en el momento del acceso a su contenido.',null),
('aux-canarias:22-0a5aa72201','aux-canarias',22,'La obligación de notificar en plazo se entiende cumplida, en las notificaciones electrónicas, con:','["La puesta a disposición de la notificación en la sede electrónica o en la dirección electrónica habilitada única", "La publicación de un anuncio en el BOE", "El envío del aviso al correo electrónico del interesado, aunque no se ponga a disposición la notificación", "El acceso efectivo del interesado"]'::jsonb,0,'Art. 43.3 Ley 39/2015','Se entiende cumplida con la puesta a disposición en la sede electrónica o la dirección electrónica habilitada única.',null),
('aux-canarias:22-cacadf46fc','aux-canarias',22,'Si en la notificación en papel en el domicilio el interesado no está presente, podrá hacerse cargo de ella:','["Solo un familiar mayor de 18 años", "Cualquier persona mayor de 14 años que se encuentre en el domicilio y haga constar su identidad", "Cualquier persona mayor de 16 años que se encuentre en el domicilio, sin necesidad de hacer constar su identidad", "Únicamente el interesado"]'::jsonb,1,'Art. 42.2 Ley 39/2015','Puede recogerla cualquier persona mayor de catorce años que esté en el domicilio y haga constar su identidad.',null),
('aux-canarias:22-c4769121c6','aux-canarias',22,'Según la Ley 40/2015, el titular de la sede electrónica responde de:','["La integridad, veracidad y actualización de la información y los servicios a los que pueda accederse a través de ella", "Únicamente de la disponibilidad técnica de la sede durante el horario de atención presencial", "La integridad de la información publicada, mientras que su actualización y la de los servicios corresponde al proveedor tecnológico contratado", "La veracidad de la información publicada en el portal, pero no de los servicios electrónicos de la sede"]'::jsonb,0,'Art. 38.2 Ley 40/2015','El titular de la sede responde de la integridad, veracidad y actualización de la información y los servicios accesibles a través de ella.',null),
('aux-canarias:22-01795793fd','aux-canarias',22,'Para identificarse y garantizar una comunicación segura, las sedes electrónicas utilizan:','["El código seguro de verificación del órgano titular de la sede", "Un sello de tiempo cualificado emitido por la Fábrica Nacional de Moneda y Timbre-Real Casa de la Moneda", "Certificados cualificados de autenticación de sitio web o medio equivalente", "La firma electrónica personal de la persona titular del órgano"]'::jsonb,2,'Art. 38.6 Ley 40/2015','El art. 38.6 prevé certificados reconocidos o cualificados de autenticación de sitio web o un medio equivalente.',null),
('aux-canarias:22-793a2735e8','aux-canarias',22,'Según el art. 40 de la Ley 40/2015, las Administraciones Públicas pueden identificarse mediante:','["La firma electrónica personal del titular del departamento ministerial o de la consejería, de forma exclusiva", "Un código seguro de verificación generado por el propio interesado", "Un sello electrónico basado en un certificado electrónico reconocido o cualificado", "El número de identificación profesional de cada uno de sus empleados"]'::jsonb,2,'Art. 40.1 Ley 40/2015','El sello electrónico se basa en un certificado reconocido o cualificado que incluye el NIF y la denominación de la Administración.',null),
('aux-canarias:22-62dca443c8','aux-canarias',22,'Respecto de la información que publique como propia en su portal de internet, la Administración:','["Se entiende identificada", "Debe identificarse además con la firma electrónica cualificada del órgano", "Solo se entiende identificada si incorpora un código seguro de verificación", "Debe indicar el nombre del empleado público que elaboró la información"]'::jsonb,0,'Art. 40.1 Ley 40/2015','Se entenderá identificada la Administración respecto de la información que publique como propia en su portal de internet.',null),
('aux-canarias:22-d176c32571','aux-canarias',22,'Si un interesado no obligado a relacionarse electrónicamente carece de los medios necesarios, su firma electrónica puede realizarla:','["Cualquier empleado público de la oficina, sin necesidad de consentimiento expreso del interesado", "Un funcionario habilitado, si el interesado se identifica ante él y presta su consentimiento expreso", "Un funcionario habilitado, pero solo en los procedimientos que se inician de oficio", "Un familiar del interesado, previa presentación de una declaración responsable"]'::jsonb,1,'Art. 12.2 Ley 39/2015','El funcionario firma con su propio sistema; el interesado debe identificarse y prestar consentimiento expreso, del que queda constancia.',null),
('aux-canarias:22-a098214fde','aux-canarias',22,'Los funcionarios habilitados para la identificación o firma de los interesados que no disponen de medios electrónicos constan en:','["Un registro u otro sistema equivalente que cada Administración mantiene actualizado", "El Registro Central de Personal, en una sección específica de firma electrónica", "Un listado único estatal publicado en la sede electrónica del Ministerio para la Transformación Digital y de la Función Pública", "El registro electrónico de apoderamientos de la Administración correspondiente"]'::jsonb,0,'Art. 12.3 Ley 39/2015','La AGE, las CCAA y las Entidades Locales mantienen actualizado un registro u otro sistema equivalente de funcionarios habilitados.',null),
('aux-canarias:22-5080417d8e','aux-canarias',22,'Si la Administración no envía el aviso al dispositivo o correo electrónico del interesado de que tiene una notificación electrónica:','["La notificación es nula y debe practicarse de nuevo", "La notificación puede considerarse plenamente válida", "La notificación debe repetirse en papel en el domicilio", "El plazo para acceder a la notificación se amplía diez días"]'::jsonb,1,'Art. 41.6 Ley 39/2015','La falta de práctica del aviso no impide que la notificación sea considerada plenamente válida.',null),
('aux-canarias:22-9c6287dd62','aux-canarias',22,'¿Qué registro deben mantener las Administraciones de los funcionarios habilitados para expedir copias auténticas y asistir en la presentación electrónica?','["Un registro o sistema equivalente de funcionarios habilitados", "Un registro electrónico de apoderamientos otorgados por los interesados", "Un registro de convenios suscritos con otras Administraciones públicas", "Un registro de órganos colegiados y de sus miembros titulares y suplentes"]'::jsonb,0,'Art. 12.3 Ley 39/2015','El registro electrónico de apoderamientos recoge las representaciones otorgadas por los interesados.',null),
('aux-canarias:22-ba44e1d9ff','aux-canarias',22,'Según el artículo 9 de la Ley 39/2015, ¿cuál de los siguientes es un sistema válido para que los interesados se identifiquen electrónicamente ante las Administraciones?','["La fotocopia del DNI enviada por correo electrónico", "Los sistemas de clave concertada", "El número de teléfono móvil", "La firma manuscrita escaneada"]'::jsonb,1,'Art. 9.2 Ley 39/2015','También los certificados electrónicos cualificados de firma y de sello y cualquier otro sistema que las Administraciones consideren válido en los términos y condiciones que se establezcan.',null),
('aux-canarias:22-1a0db64ee7','aux-canarias',22,'Según el artículo 43 de la Ley 39/2015, la notificación por medios electrónicos se entiende rechazada cuando:','["Han transcurrido cinco días hábiles desde su envío sin que el interesado haya contestado ni presentado alegaciones", "Han transcurrido diez días naturales desde su puesta a disposición sin que se acceda a su contenido", "Han transcurrido quince días hábiles desde que se dictó el acto", "El interesado no contesta en veinticuatro horas al aviso enviado a su dirección de correo electrónico o a su móvil"]'::jsonb,1,'Art. 43.2 Ley 39/2015','Se entiende practicada en el momento en que se produce el acceso a su contenido.',null),
('aux-canarias:22-86235e8aa1','aux-canarias',22,'¿Qué es la Dirección Electrónica Habilitada única (DEHú)?','["La dirección postal que el interesado designa para recibir las notificaciones en papel cuando no está obligado a relacionarse electrónicamente", "El punto donde el interesado puede consultar las notificaciones electrónicas que le remitan las Administraciones", "La sede electrónica del Ministerio competente en materia de función pública", "El correo electrónico oficial que la Administración asigna a cada ciudadano y a cada empresa para recibir sus comunicaciones oficiales"]'::jsonb,1,'Art. 43 Ley 39/2015 y RD 203/2021','Las notificaciones pueden practicarse por comparecencia en la sede electrónica o a través de la DEHú.',null)
